        title        = 'The Chains That Bind Us',
        starting_npc = 'Any Bastok Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'The president has ordered a full-scale investigation of Zepwell Island. You are to travel to the Quicksand Caves located in the central Altepa Desert. Report to Iron Eater for a briefing.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {},
    },
    ['Bastok Mission 8-2'] = {
        title        = 'Enter the Talekeeper',
        starting_npc = 'Any Bastok Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'You are to investigate the Kuftal Tunnel which connects Zepwell Island with Cape Teriggan. Zeruhn Mines guard Drake Fang will provide you with further details.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Visit Drake Fang in Zeruhn Mines (H-6).', sub = {
                { 'Survival Guide is the fastest path.' },
            } },
            { 'Head for Kuftal Tunnel Map 1. Just inside from the Western Altepa Desert entrance at (H-4). At (H-8), there is a ??? you have to check.', sub = {
                { 'You can also use the Kuftal Tunnel Survival Guide warp.' },
            } },
            { 'Interact with the ???. You\'ll receive a message about "\'a piece of wood buried in the sand, it will ask you if you want to extract it, select yes. then the message \'the piece of wood fell off the cliff."', sub = {
                { 'Everyone in your party must check this ???. If anyone does not check this, they can check it after the NM fight downstairs, and then return to the NM ??? and still receive the Key Item.' },
            } },
            { 'Sneak up and head down around to reach the second ??? down the cliff, directly under the first one.' },
            { 'Checking the ??? will spawn 3 level 68 NM Ghosts: Dervo\'s Ghost, Gizerl\'s Ghost, and Gordov\'s Ghost.', sub = {
                { 'You can pull Gordov\'s Ghost and wait for the other two to depop, or defeat all of them.' },
            } },
            { 'Check the ??? again for a cutscene and the Key Item Old piece of wood.' },
            { 'Return to Drake Fang for a final cutscene.', sub = {
                { '(Optional): Talk to Gumbah (J-7) and Detzo (I-6) in Bastok Mines, and Iron Eater (J-8) in Metalworks for mini-cutscenes.' },
            } },
        },
    },
    ['Bastok Mission 9-1'] = {
        title        = 'The Salt of the Earth',
        starting_npc = 'Any Bastok Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'You have been assigned to an investigation in the Vollbow Region. Speak with senator Alois for further details.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Visit Alois in the President\'s Office Conference Room in Metalworks (J-8).' },
            { 'Head to Rabao and speak to Dancing Wolf in (G-7) for a cutscene.', sub = {
                { 'You may have to speak to him several times to receive the correct cutscene, make sure he mentions Miraclesalt.' },
                { 'If he repeats the same text after talking to him several times but does not mention Miraclesalt, zone and return. It has been observed that 3 cycles of talking and zoning has been required.' },
            } },
            { 'Proceed to Gustav Tunnel (G-6) on Map 2, and reach the ??? located in the pond.', sub = {
                { 'The Unity Warp Level 128 to Gustav Tunnel places you on the correct map, just south of the pond.' },
                { 'Alternatively, there is a Survival Guide to Map 1.' },
                { 'Everything in the area will aggro. If in a party, you could have other players wait at (H-7), as it is safe there from aggro.' },
            } },
            { 'Checking the ??? will spawn Gigaplasm, a slime NM.', sub = {
                { 'Trivial at 99 with Trusts.' },
                { 'You can Sneak pull, sleep the NM and run back to camp. The NM will eventually make its way to you.' },
                { 'Slime NMs have high melee resistance. Casters will be very important, and sleeping the mobs will be imperative.' },
                { 'You will start against one Gigaplasm, defeating it will cause it to divide in 2 Macroplasms. Each of those will divide into 2 Microplasms, and those will divide into 2 Nanoplasms. Try to keep as many mobs asleep as you can. Commence by killing one line of Macroplasms (defeat one, defeat its Microplasms, and then its Nanoplasms), and then the second. Sleep repeatedly. The HP of the mobs gets progressively lower, to the point where a decently equipped BLM should be able to one-shot a Nanoplasm with a single Thunder III. The key to this fight is keeping everything asleep.' },
                { 'Avoid giving the mobs too much TP, as they can use the typical nasty slime TP attacks, like Fluid Spread.' },
            } },
            { 'Defeat all of them and Sneak everyone to the ???. Check it to receive the Key Item Miraclesalt.' },
            { 'Return to Rabao and speak to Dancing Wolf for a cutscene.' },
            { 'Head back to Alois to finish the Mission.' },
        },
    },
    ['Bastok Mission 9-2'] = {
        title        = 'Where Two Paths Converge',
        starting_npc = 'Any Bastok Gate Guard',
        subtitle     = 'Hero Among Heroes',
        repeatable   = 'No',
        description  = 'An adventurer has been attacked while on an investigation to Xarcabard -- and the attacker is said to be none other than the Dark Knight, Zeid! Report to the President\'s Office for a briefing on the situation at hand.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Talk to Iron Eater in Metalworks (J-8) for a cutscene.' },
            { 'Make your way to the Throne Room in Castle Zvahl Keep HP #1.' },
            { 'Gather up, and enter the "Where Two Paths Converge" fight when ready.', sub = {
                { 'Buffs will wear off once you enter, so do it inside.' },
            } },
        },
    },
}

quest_info['windurstmissions'] = {
    ['Windurst Mission 1-1'] = {
        title        = 'The Horutoto Ruins Experiment',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'Title based on Gatehouse where mission was accepted New "Buuma\'s Boomers" Recruit (Windurst Woods) Fresh "North Winds" Recruit (Windurst Waters) New "Best of the West" Recruit (Port Windurst) Heavens Tower Gatehouse Recruit (Windurst Walls)',
        repeatable   = 'No',
        description  = 'The minister of the Orastery in conducting an experiment in the eastern magic tower of the Horutoto Ruins, located in East Sarutabaruta. Inquire at the Orastery first, then go assist him.',
        series       = 'Federation of Windurst',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to any Windurstian Gate Guard, and accept the Mission.', sub = {
                { 'Mokyokyo - Windurst Waters (F-5)' },
                { 'Janshura-Rashura - Port Windurst (B-5)' },
                { 'Rakoh Buuma - Windurst Woods (K-10)' },
                { 'Zokima-Rokima - Windurst Walls (H-7)' },
            } },
            { 'Head for the Orastery in Port Windurst. Speak to Hakkuru-Rinkuru at (E-7) for a cutscene.' },
            { 'Make your way to (J-7) in East Sarutabaruta. You\'re looking for a large stone tower.', sub = {
                { 'The Inner Horutoto Ruins Survival Guide places you at the right tower if you have it unlocked already.' },
            } },
            { '(Optional): Speak to Sama Gohjima near the entrance for some dialogue.' },
            { 'Head down the stairs to the Inner Horutoto Ruins.' },
            { 'Inside, you\'ll be in the Lily Tower on Map 1. Go down the stairs in to the main room.' },
            { 'Run to the other side, and look for the Cracked Wall, around (H-9). Pass through it and go left.' },
            { 'Check the Gate: Magical Gizmo at (I-9) for a cutscene with the Minister.' },
            { 'Now, head back out and check the six different Ancient Magical Gizmos until you are given the Key Item Cracked Mana Orb. It will be at a random Gizmo.' },
            { 'Head back to Hakkuru-Rinkuru and speak with him to finish the Mission.' },
        },
    },
    ['Windurst Mission 1-2'] = {
        title        = 'The Heart of the Matter',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Assist the Manustery in the creation of Cardians. You must go to the southeastern magic tower of the Horutoto Ruins in East Sarutabaruta, and energize the Mana Orbs that serve as the hearts of the Cardians. Inquire at the Manustery first for details.',
        series       = 'Federation of Windurst',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Accept the Mission from any Gate Guard.', sub = {
                { 'Mokyokyo - Windurst Waters (F-5)' },
                { 'Janshura-Rashura - Port Windurst (B-5)' },
                { 'Rakoh Buuma - Windurst Woods (K-10)' },
                { 'Zokima-Rokima - Windurst Walls (H-7)' },
            } },
            { 'Then make your way to the Manustery in Windurst Woods, Speak to Apururu who is at (H-9).', sub = {
                { 'You may need to talk to her twice if you have a Key Item Windurst Trust permit as she will mention talking to her brother, Ajido-Marujido.' },
            } },
            { 'You will receive the following Mana Orbs Key Items:', sub = {
                { 'Key Item First dark Mana Orb' },
                { 'Key Item Second dark Mana Orb' },
                { 'Key Item Third dark Mana Orb' },
                { 'Key Item Fourth dark Mana Orb' },
                { 'Key Item Fifth dark Mana Orb' },
                { 'Key Item Sixth dark Mana Orb' },
            } },
            { 'You are now instructed to go to the Outer Horutoto Ruins.' },
            { 'Head to (J-11) in East Sarutabaruta and speak to Pore-Ohre at the entrance to Marguerite Tower, they will give you the Key Item Southeastern star charm.', sub = {
                { 'Make sure you get this, or you will be unable to energize the orbs later on.' },
            } },
            { 'Check the six pedestals to place a Mana Orb.', sub = {
                { 'Examine the Cracked Walls along the north and south sides to find hidden rooms, which contain 2 more pedestals for your Mana Orbs.' },
            } },
            { 'After all orbs have been set, pass through the Cracked Wall on the east side and then examine the Gate: Magical Gizmo behind it for a cutscene.' },
            { 'After the cutscene, check each pedestal again to retrieve the 6 Glowing Mana Orb Key Items:', sub = {
                { 'Key Item First glowing Mana Orb' },
                { 'Key Item Second glowing Mana Orb' },
                { 'Key Item Third glowing Mana Orb' },
                { 'Key Item Fourth glowing Mana Orb' },
                { 'Key Item Fifth glowing Mana Orb' },
                { 'Key Item Sixth glowing Mana Orb' },
            } },
            { 'When you\'ve collected all 6, head back out of the tower. When you zone, you\'ll receive another cutscene.', sub = {
                { '(Optional): You can speak to Quh Berhuja nearby for some dialogue.' },
                { 'Alternatively, you can use any means of leaving the zone that will not lead you to East Sarutabaruta. Doing this will allow you to skip the cutscene and go straight back to Apururu will which lead to a slightly different cutscene upon finishing the Mission.' },
            } },
            { 'Head back to the Manustery and speak to Apururu to complete the Mission.' },
        },
    },
    ['Windurst Mission 1-3'] = {
        title        = 'The Price of Peace',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Recieve two bags of food offerings from the Rhinostery, and deliver one bag to each of the Yagudo who stand by the altars of offerings in Giddeus. Don\'t forget to report back to the Rhinostery after completing the mission.',
        series       = 'Federation of Windurst',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Accept the Mission from any Gate Guard.', sub = {
                { 'Mokyokyo - Windurst Waters (F-5)' },
                { 'Janshura-Rashura - Port Windurst (B-5)' },
                { 'Rakoh Buuma - Windurst Woods (K-10)' },
                { 'Zokima-Rokima - Windurst Walls (H-7)' },
            } },
            { 'Then make your way to the roof of the Rhinostery in Windurst Waters (J-8) (near Home Point #3), it is located in the southern half of the zone.', sub = {
                { 'Speak with Leepe-Hoppe at (J-9) on the roof of the Rhinostery. He will give you the Key Item Food offering and Key Item Drink offering.' },
            } },
            { 'Head out for Giddeus, which is located at (F-8) in West Sarutabaruta.', sub = {
                { 'If you previously unlocked it, you can teleport directly to (G-12) with Home Point #1 and make your way north from there.' },
            } },
            { 'Make your way to (H-7) and speak to a Yagudo NPC named Laa Mozi to hand over the Key Item Food offering.', sub = {
                { 'You can reach this NPC by taking all left turns from the Sarutabaruta entrance.' },
            } },
            { 'Next, head to (G-7) and speak to a Yagudo NPC called Ghoo Pakya to hand over the Key Item Drink offering.', sub = {
                { 'Return to the Sarutabaruta entrance and take all right turns to reach this NPC.' },
            } },
            { 'Head back to the Rhinostery. As you climb the stairs to the roof, you\'ll receive another cutscene.' },
            { 'Return to the Gate Guard to complete the Mission.' },
        },
    },
    ['Windurst Mission 2-1'] = {
        title        = 'Lost for Words',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'There are reports that the Cat Burglar has her paws on a "Book of the Gods," a restricted book that was lost twenty years ago. Assist the Optistery in investigating the reports, and attempt to retrieve the priceless, but dangerous, tome.',
        series       = 'Federation of Windurst',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head for the Optistery on the northern map of Windurst Waters (near Home Point #1). Speak to Tosuka-Porika at (G-8) (East door).', sub = {
                { '(Optional): The other NPCs and Tosuka-Porika inside the same room have additional dialogue.' },
            } },
            { 'Head to (J-3) in Windurst Woods and speak to Nanaa Mihgo. She will lend you her Key Item Lapis monocle.', sub = {
                { 'You may need to talk to her twice or more if you have a Key Item Windurst Trust permit and Aht Urhgan Lure of the Wildcat Quests started.' },
                { '(Optional): Nanaa\'s cronies nearby have additional dialogue.' },
            } },
        },
    },
    ['Windurst Mission 2-2'] = {
        title        = 'A Testing Time',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'None',
        repeatable   = 'Yes',
        description  = 'Assist the Aurastery\'s School of Magic in the selection of the venue for their next skills test. They want to record the number of monsters you can hunt at a specific area, in a set number of days, to fairly standardize their skills test.',
        series       = 'Federation of Windurst',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Accept the mission from the Gate Guard.', sub = {
                { '(Optional): As usual, you can speak to the gate guards for additional dialogue.' },
            } },
            { 'Head to (L-6) in Windurst Waters and speak to Moreno-Toeno (inside the Aurastery), who gives you the Key Item "Creature Counter" magic doll to keep track of your objective.', sub = {
                { '(Optional): You can talk to the students on the roof and the other NPCs in the same room as Moreno-Toeno for additional dialogue.' },
                { 'You can save some time by setting your Home Point in Windurst Waters and bringing a Warp item.' },
            } },
        },
    },
    ['Windurst Mission 2-3'] = {
        title        = 'The Three Kingdoms',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'Dread Dragon Slayer or Dark Dragon Slayer, Warchief Wrecker, Certified Adventurer',
        repeatable   = 'No',
        description  = 'Determine the state of affairs in San d\'Oria and Bastok, and render assistance on behalf of Heavens Tower. Inquire at our consulate in each country for more information. Traveling by ship from Mhaura to Selbina is recommended.',
        series       = 'Federation of Windurst',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'This Mission can be long if you do not have Home Points, and is broken down in to two legs. Whichever Nation you choose first determines how the next plays out. Option 2, the San d\'Oria path progression, is typically easier and faster.' },
            { 'Speak with Kupipi in Heavens Tower. She is inside the Clerical Chamber. She will give you a Key Item Letter to the consuls.', sub = {
                { 'You may receive Cipher: Semih if you don\'t already have it and are participating in Trust.' },
            } },
        },
    },
    ['Windurst Mission 3-1'] = {
        title        = 'To Each His Own Right',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'On the command of Semih Lafihna, captain of the Sibyl Guards, you are requested to track down the Minister of the Orastery, Ajido-Marujido, and discover his true intentions. Inquire at the Orastery if you lose track of him.',
        series       = 'Federation of Windurst',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to Kupipi in Heavens Tower who will give you the Key Item Starway Stairway bauble.', sub = {
                { 'You will be granted access to the upper portion of Heavens Tower. Check the door on the left to go up.' },
            } },
            { 'Speak to Rhy Epocan at the top of the Tower for a cutscene.', sub = {
                { 'Use the blue teleporter at the top of the tower to return to the main floor.' },
            } },
            { 'Speak to Hakkuru-Rinkuru at the Orastery in Port Windurst (E-7) for hints on Ajido-Marujido\'s whereabouts.', sub = {
                { 'Home Point #1 is closest to Hakkuru-Rinkuru.' },
            } },
            { 'Go to Castle Oztroja and fall down the trap door ((I-8) first Map) for a cutscene.', sub = {
                { 'Enter and go to (I-8). There will be two switches (not torches) and a fairly obvious floor panel. One switch will open the door, one will open the floor. Stand in between the two switches and check one. If it opens the door, check the other. They randomly switch, so it will never be the same, day by day.' },
                { 'The person doing the Mission must be the one to pull the lever. Multiple people doing this mission will need to stand back until the trap door closes then individually pull the lever.' },
                { 'In the same room you drop into there is a Blank Target, which is for the Onion Rings quest. You can collect Key Item Old ring without having the Quest flagged.' },
            } },
            { 'Return to Rhy Epocan to complete the Mission.' },
        },
    },
    ['Windurst Mission 3-2'] = {
        title        = 'Written in the Stars',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'None',
        repeatable   = 'Yes',
        description  = 'On the command of Zubaba, the head lady-in-waiting, you are to journey beneath the central magic tower of the Horutoto Ruins. There, you are to report to the facility managed by Heavens Tower, which protects the talisman that seals Castle Zvahl. Render whatever assistance is necessary.',
        series       = 'Federation of Windurst',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Accept the mission and make your way to Heavens Tower.' },
            { 'Pass by Kupipi and on to the second floor. Speak to Zubaba who will give you the Key Item Charm of light.' },
            { 'Next, you will need to get past the Three Mage Gate in ruins tower at (J-7) in East Sarutabaruta (this is the same tower as the Survival Guide Inner Horutoto Ruins warp).' },
            { 'Pass the Three Mage Gate and continue on to the small room at (G-7).' },
            { 'Check the Gate of Light for a cutscene.' },
            { 'Return to Heavens Tower and speak to Zubaba to finish the mission.' },
        },
    },
    ['Windurst Mission 3-3'] = {
        title        = 'A New Journey',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'As requested by the Star Sibyl, you are to render service at the Embassy of Windurst in Jeuno. Great responsibility and tact are required.',
        series       = 'Federation of Windurst',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Check the Vestal Chamber door at the top of Heavens Tower for a cutscene with the Star Sibyl. You will receive Key Item Letter to the ambassador.' },
            { 'Speak with Pakh Jatalfih at the Windurstian Embassy in Ru\'Lude Gardens (I-9) for a cutscene.' },
            { 'Head to Lower Delkfutt\'s Tower using the Survival Guide teleportation, Outpost warp, or Home Point warp.' },
            { 'You will now likely need to climb to the 10th floor of Delkfutt\'s Tower in order to gain a Delkfutt Key in order to access the Basement of the Tower:', sub = {
                { 'If you already possess the Delkfutt Key (trade it to the door) or the Key Item Delkfutt key (no trading needed) then you may skip this climb:', sub = {
                    { 'Head to Lower Delkfutt\'s Tower (E-8) Map 1 and enter the Basement by clicking the Cermet Door. Once you go through the door, proceed to (L-7) and click the Cermet Door for a cutscene. (Note: Another player using a key does not work.)' },
                    { 'Return to the Windurstian Embassy in Ru\'Lude Gardens and click the Door: Windurstian Emb. for a cutscene to complete the Mission.', sub = {
                        { 'This is the 3rd door inside the embassy building. There are multiple doors with the same name.' },
                    } },
                } },
                { 'If you do not possess the Key, start the climb process detailed below:', sub = {
                    { 'You may be Tractored through this Basement door without the Key. If you decide to go this route, proceed to the "Obtaining Delkfutt Key Short Way" section.' },
                    { 'Otherwise, read the "Obtaining Delkfutt Key Long Way" section.' },
                } },
            } },
        },
    },
    ['Windurst Mission 4-1'] = {
        title        = 'Magicite',
        starting_npc = 'Windurstian Embassy in Ru\'Lude Gardens',
        subtitle     = 'Have Wings Will Fly',
        repeatable   = 'No',
        description  = 'Confiscate the three kinds of magicite in Davoi, Beadeaux, and Castle Oztroja to prevent the resurrection of the Shadow Lord.',
        series       = 'Federation of Windurst',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'To flag the Mission, head to the Windurstian Embassy in Jeuno, Ru\'Lude Gardens (I-9) and speak with clerk Pakh Jatalfih. Then head to the back chamber to talk to the ambassador in a cutscene and receive the Key Item Archducal audience permit.', sub = {
                { 'You will need to go through the door on the left side of the reception desk. The ambassador\'s office is in the end of the corridor. Click Door: Windurstian Emb. for the cutscene.' },
            } },
            { 'Click on the door to the Audience Chamber in Ru\'Lude Gardens (H-6) for a cutscene and the Key Item Letter to Aldo.' },
            { 'Speak to Aldo in Lower Jeuno, in the back of the Neptune\'s Spire Tenshodo H.Q. for a cutscene and the Key Item Silver bell.', sub = {
                { 'If you have done this mission in another Nation then you already have the bell, but you still need to talk to him for a cutscene.' },
            } },
            { 'Obtain the 3 Magicite Key Items. See below for details.' },
            { 'Click the Audience Chamber in Ru\'Lude Gardens (H-5) after obtaining all 3 Magicites for a cutscene and your reward (either an Key Item Airship Pass, or, if you already have one, 20,000 Gil).' },
            { 'Return to Pakh Jatalfih in the Windurstian Embassy to complete the mission, receive 10,000 Gil and Key Item Message to Jeuno (Windurst).' },
        },
    },
    ['Windurst Mission 5-1'] = {
        title        = 'The Final Seal',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'Archmage Assassin',
        repeatable   = 'No',
        description  = 'On the Star Sibyl\'s command, you are to head north to the ruins of Fei\'Yin, somewhere on the Beaucedine Glacier. There, you are to confirm whether the final seal is doing its job.',
        series       = 'Federation of Windurst',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Click the Door: Vestal Chamber at the top of the Tower to start the Mission and to receive Key Item New Fei\'Yin seal.', sub = {
                { 'If you are low level, you might want to use Trusts or form a party of lvl 50+ players.' },
            } },
            { 'Go to Fei\'Yin (located in the northeast corner of Beaucedine Glacier) for a cutscene with Zeid. You will have to reach the Qu\'Bia Arena and clear the BCNM "The Rank 5 Mission".', sub = {
                { 'The majority of enemies in Fei\'Yin detect by Sound sound, however there are several that detect Magic spellcasting.' },
                { 'Quick Travel options:', sub = {
                    { 'Home Point #1 to Fei\'Yin is the fastest way, it puts you right at the zone to Qu\'Bia Arena.' },
                    { 'Unity Warp (Level 128) will place you at the entrance of Fei\'Yin.' },
                    { 'Unity Warp (Level 125) will place you in the central area of Beaucedine Glacier.' },
                } },
                { 'From the entrance of Fei\'Yin:', sub = {
                    { 'Go east to (K-8). There are 2 Dolls in front of a door named Cermet Portal, open it and you\'ll be able to enter Qu\'Bia Arena.' },
                } },
            } },
        },
    },
    ['Windurst Mission 5-2'] = {
        title        = 'The Shadow Awaits',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'Star-ordained Warrior, Shadow Banisher',
        repeatable   = 'No',
        description  = 'As written in the stars and interpreted by the Star Sibyl, you are to destined to journey to Castle Zvahl, which towers over Xarcabard, the end of the known lands. There, you are to witness what fate has in store for our world.',
        series       = 'Federation of Windurst',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to the top of the Heavens Tower in Windurst Walls HP #1 and click the Door: Vestal Chamber.', sub = {
                { 'If you\'re not using Trusts and are level 55-60, form a full party of players.' },
            } },
        },
    },
    ['Windurst Mission 6-1'] = {
        title        = 'Full Moon Fountain',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'At the request of the Orastery, you are to go to the southwestern magic tower of the Horutoto Ruins, located in West Sarutabaruta. Deep within you will find a laboratory, where you are ordered to switch on the magical gizmo.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Talk to Hakkuru-Rinkuru at the Orastery in Port Windurst HP #1 for a cutscene and the Key Item Southwestern star charm.' },
            { 'Go to West Sarutabaruta (F-11) and reach the southwestern tower (Dahlia Tower) to enter the Outer Horutoto Ruins.' },
            { 'You\'ll be in Map 4 of Outer Horutoto Ruins. Go to (I-8) and interact with the Cracked Wall.' },
            { 'Go straight ahead to (J-8), there will be a second Cracked Wall. Proceed until you finally find the Gate: Magical Gizmo and click it to spawn 4 Jack Cardians.', sub = {
                { 'It is not necessary to defeat them all if you allow the others to despawn before defeating the one you pull.' },
                { 'If you\'re low level, sneak up before examining the door, make sure everyone else is well back.' },
                { 'The Cardians are magic aggressive so make sure mages are well out of range.', sub = {
                    { 'If you do this and don\'t let the others despawn before defeating a Cardian. Then you will not receive the cutscene when you examine the door.' },
                } },
                { 'The Cardians NMs do not link with each other, but they will link with other naturally spawning Cardians in the area.', sub = {
                    { 'Jack of Batons (BLM)' },
                    { 'Jack of Coins (RDM)' },
                    { 'Jack of Cups (WHM)' },
                    { 'Jack of Swords (PLD)' },
                } },
            } },
            { 'Examine the door after defeating them for a cutscene. If you see a message saying "A mysterious force is interfering", wait until the NMs have fully despawned off screen before trying again. Eventually the cutscene will trigger.', sub = {
                { '(Optional): Return to Hakkuru-Rinkuru for some dialogue on Ajido-Marujido\'s whereabouts.' },
            } },
            { 'Enter Full Moon Fountain located in Toraimarai Canal Map 1 for a cutscene which completes the mission.', sub = {
                { 'Home Point #1 in Toraimarai Canal is fastest way there.' },
            } },
        },
    },
    ['Windurst Mission 6-2'] = {
        title        = 'Saintly Invitation',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'Hero on Behalf of Windurst, Victor of the Balga Contest',
        repeatable   = 'No',
        description  = 'A mission issued by Heavens Tower. In reply to the Yagudo Holy One\'s invitation, you are to compete and triumph at the contest held at Balga\'s Dais deep within Giddeus.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Select the Door: Vestal Chamber at the top of Heavens Tower for a cutscene.', sub = {
                { 'You will receive Key Item Holy One\'s invitation and the title: "Hero on Behalf of Windurst".' },
            } },
            { 'You will have to proceed to Balga\'s Dais located in Giddeus, and clear the BCNM "Saintly Invitation". You will receive the Key Item Balga champion certificate.', sub = {
                { 'Home Point #1 to Giddeus is the fastest way.' },
            } },
        },
    },
    ['Windurst Mission 7-1'] = {
        title        = 'The Sixth Ministry',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'At the request of the Optistery, you are to find former minister Karaha-Baruha\'s laboratory in Toraimarai Canal, and delve deeper into the mystery of the Book of the Gods.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Talk to Tosuka-Porika in the Optistery eastern building in Windurst Waters HP #1 (G-8) for a cutscene and to receive the Key Item Optistery ring.' },
            { 'Head to Toraimarai Canal (G-8) Map 2 and defeat the 4 Hinge Oils in the room.', sub = {
                { 'Quickest way to get there is to enter through the Windurst Walls (I-3) Priming Gate using the Key Item Rhinostery certificate, take a right at the bottom of the stairs, get into the water and keep turning left until you reach some stairs, which you should go up. From here, head south → east → north to reach the Slimes in (G-8).' },
                { 'Alternatively if you have the Home Point #1 of Toraimarai Canal, go south from it entering a big room, continue towards your left to exit the room and begin walking through the canals. On Map 1 of the canals stay on the above path and walk towards point B. Once you reach point B on the above section keep going north on the only path and go down in the water section of the canals, go back to B and cross into Map 2, take a first right and go south, at the first stairs go up to the raised path and go towards (G-8) where you will find the oozes and door.' },
            } },
            { 'After defeating the 4 Slimes, head northeast to the stairs at (H-8) and examine the Marble Door at the top.', sub = {
                { 'All four Hinge Oils must be defeated before you can enter The Animastery. Hinge Oils will repop after 16 minutes.' },
            } },
            { 'Examine the Tome of Magic lying on the ground to begin a cutscene.', sub = {
                { 'This is near the desk and a skull resting on a chair.' },
            } },
        },
    },
    ['Windurst Mission 7-2'] = {
        title        = 'Awakening of the Gods',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Rhinostery minister Rukususu has traveled to Elshimo to investigate the facts concerning Iru-Kuiru, a researcher from thirty years past. The Rhinostery has asked you to bring Minister Rukususu back for her own safety.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Talk to Leepe-Hoppe on the roof of the Rhinostery, located in the southern half of Windurst Waters near Home Point #3.', sub = {
                { 'The correct dialogue involves Rukususu and Kerutoto.' },
            } },
            { 'Talk to Kerutoto in the Rhinostery northern building for a cutscene.', sub = {
                { 'You may need to talk to her over 3 times.' },
                { 'The correct cutscene is the one where she talks about Leepe-Hoppe and Rukususu, not the Diabolos one.', sub = {
                    { 'If she continues to give you the cutscene for Diabolos, accept the Quest and talk to her twice to activate the cutscene needed for this Mission.' },
                } },
                { 'Optional: Talk to Vanono in Kazham at (G-7) for a brief message.', sub = {
                    { 'Before minister Rukususu returned to the mainly-mainlands, I was able to giver her my report on my findings here in Elshimo. She was very pleased with all the lovely-wuvly discoveries that we had made. But we couldn\'t have done it without the help of adventurers like you!' },
                } },
            } },
            { 'Talk to Romaa Mihgo in Kazham at (H-11) in Mihgo\'s Residence.' },
            { 'Travel to the Temple of Uggalepih. You will have to kill Bonze Marberry for a Cursed Key (G).', sub = {
                { 'If you\'re in a party, each player will require one.' },
                { 'The key won\'t drop if you already have one. Check your storage.' },
                { 'Bonze Marberry is located on Map 3 near (J-9). It will drop 2 keys per kill, and respawns every 5 minutes. This NM uses Everyone\'s Rancor, therefore it is recommended to reset your Tonberry Hate if your Hate is high and you\'re fighting him at a low level.' },
                { 'Quick travel options: Use the Yhoator Jungle Outpost Warp, Unity Warp or Survival Guide. → Run to the Bloodlet Spring Den of Rancor entrance at (J-7) → From this entrance of Den of Rancor, follow the right wall until you zone in Temple of Uggalepih. This will directly lead you on Map 3. → Go upstairs and follow the left wall. The NM will be in the room at (J-9).' },
            } },
            { 'After obtaining your Cursed Key, trade it to the Granite Door at (J-6) on the same map for a cutscene. You will receive Key Item Book of the Gods.', sub = {
                { 'Optional: Inspect three Tome of Magic.', sub = {
                    { 'A workbook written by Iru-Kuiru. "That place was most definitely cursed. It was as if each of us were having our strings pulled by some unseen force..." "The Goddess only knows what that power was. I knew fear like I had never known before, and was struck mindless with panic before the terror that lurked within these walls."' },
                    { 'A diary written by Iru-Kuiru. "A letter has arrived from the homeland. The San d\'Orian member of the Allied Expedition, Francmage M Mistalle, has lost his life to the curse..." "And then yesterday, my friend and fellow Allied explorer, Yow Rabntah, was taken from this world..." "I can feel the shadow closing in on me. I believe the darkness will claim me before I am able to finish this research. And I was so close to putting all the pieces of this legend together..."' },
                    { 'A tome written on the subject of Fei\'Yin. "I would like to bring attention to the many small chambers that exist in the subterranean levels of the ruins of Fei\'Yin." "In each of these chambers stands an automaton. A golem, or giant, if you will. Were these golems given the task of sentry, or simply employed as servants?" "It is possible to conclude from the artifacts discovered in these ruins that it was once the abode of ancient people. One can further deduce from the evidence that this civilization was wiped out by some sudden calamity."' },
                } },
            } },
            { 'Return to Leepe-Hoppe to complete the Mission.' },
        },
    },
    ['Windurst Mission 8-1'] = {
        title        = 'Vain',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'Fugitive Minister Bounty Hunter',
        repeatable   = 'No',
        description  = 'At the request of the Aurastery, you are to discover the whereabouts of their former minister who fled from his duties several years ago.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Talk to Moreno-Toeno in Windurst Waters (L-6) at the Aurastery (northern section, eastern building, HP#2 is closest) for a cutscene and to obtain the Key Item "Star Seeker".' },
            { 'Click the Qu\'Hau Spring in Ro\'Maeve (H-6) for a cutscene.', sub = {
                { 'Quick travel options: the Survival Guide to Ro\'Maeve is the fastest way. The Voidwatch warp to Hall of the Gods or Ro\'Maeve are the next best options, respectively.' },
            } },
            { 'Go to Davoi and kill Dirtyhanded Gochakzuk NM to obtain a Curse Wand (G). The NM will drop 2 wands per kill, and respawns every 5 minutes.', sub = {
                { 'If you\'re in a party, each player will require one.' },
                { 'The wand won\'t drop if you already have one. Check your storage.' },
                { 'The NM is located on the center island (H-8), so you have to go though Monastic Cavern: Enter Monastic Cavern from entrance 2 at (H-11) in Davoi → Once inside, keep going and take the exit 4 at (I-8) → From here follow the road west around the hill to a wooden elevator, pull the lever to get to the monastery building → Inside, after 2 Oak Doors, the NM will be sitting on a big "throne".' },
                { 'Quick travel options: the Proto-Waypoint to Davoi is the fastest way. Drop into the water, follow the water south-east to (J-10) to get back on land, then hug left until you reach entrance 2. The Survival Guide to Davoi is almost as fast.' },
            } },
            { 'Take the elevator back down and walk to the bridge off the center island. Do not drop down in the river or you\'ll have to do the walk of shame back through the cave!' },
            { 'Keep going until you reach Sedal-Godjal at (J-8). Speak to him for a cutscene. He will turn your Key Item "Star Seeker" into the Key Item Magic-drained "Star Seeker".', sub = {
                { 'You may need to talk multiple times. This can be done before or after obtaining the Curse Wand.' },
            } },
            { 'Trade the Curse Wand to Sedal-Godjal for a cutscene.', sub = {
                { 'Optional: Talk to Sedal-Godjal again.', sub = {
                    { 'When the refinrocements arrive from San d\'Oria, I\'ll return to Windurst. The professor mustaru have forgotten about Mojiji by now. Huh? He\'s still getting letters. But, I\'m not writing them anymore!' },
                } },
            } },
            { 'Return to Moreno-Toeno for a cutscene that completes the Mission.', sub = {
                { 'Optional: Talk to Moreno-Toeno again.', sub = {
                    { 'In closing, there is the case of Mojiji... With the sudden cessation of Mojiji\'s correspondence, Professor Koru-Moru slid into an unsettling slump. Let me just say that some of us struck on the same solution as sly old Sedal-Godjal...' },
                } },
            } },
        },
    },
    ['Windurst Mission 8-2'] = {
        title        = 'The Jester Who\'d Be King',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'The time for the Dark Dungeon jailbreak is at hand! At the request of the Manustery, you are to collect the ministry rings from all five ministers.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Talk to Apururu in Windurst Woods HP #1 inside the northern Manustery building for a cutscene. You will obtain the Key Item Manustery ring.' },
            { 'Talk to the following NPCs, in any order, to receive the Key Item Rhinostery ring, Key Item Aurastery ring, and Key Item Optistery ring:', sub = {
                { 'Rukususu in Fei\'Yin at (F-6) on Map #2. Click the Cermet Door of the north-western small room for a cutscene with her.', sub = {
                    { 'Home Point #2 to Fei\'Yin is the fastest way.' },
                } },
                { 'Sedal-Godjal in Davoi (J-8). He can only be reached by going through Monastic Cavern. Enter Monastic Cavern from entrance 2 at (H-11) in Davoi. Once you\'re in, hug the right wall and exit at (H/I-8). Once you\'re back in Davoi, you can reach Sedal-Godjal by going east.', sub = {
                    { 'Proto-Waypoint to Davoi is the fastest way. Drop into the water, follow the water south-east to (J-10) to get back on land, then hug left until you reach entrance 2.' },
                    { 'Survival Guide to Davoi is almost as fast.' },
                } },
                { 'Tosuka-Porika in Windurst Waters North HP #1, inside the eastern Optistery building.' },
            } },
            { 'Return to Apururu for dialogue regarding the final ring.' },
        },
    },
    ['Windurst Mission 9-1'] = {
        title        = 'Doll of the Dead',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'Guiding Star',
        repeatable   = 'No',
        description  = 'The Orastery Minister has awoken and the Bearer of Darkness once again terrorizes Heavens Tower. At the request of the Manustery you are to speak with a person imprisoned within the Boyahda Tree and discover the truth behind the doll of the dead.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Talk to Apururu in Windurst Woods HP #1 inside the northern Manustery building (H-9) for a cutscene.' },
            { 'Zone into Heavens Tower for a cutscene.', sub = {
                { 'Optional: Every NPC upstairs (past the Starway Stairway door) has unique dialogue to this mission. Now is your chance to hear what they have to say!' },
            } },
            { 'Click the Door: Vestal Chamber on the top floor of the tower for a cutscene with the Star Sibyl.', sub = {
                { 'You will automatically be placed directly in front of this door after the previous cutscene.' },
            } },
            { 'Return to Apururu for a cutscene.' },
            { 'Trade Goobbue Humus to the single Mandragora Warden in The Boyahda Tree at (F-4) in the hidden area of Map 1 for a cutscene. You will receive a Key Item Letter from Zonpa-Zippa.', sub = {
                { 'The pair of Mandragora Warden are the wrong ones.' },
                { 'Goobbue Humus is a drop from the Goobbue Gardeners (R) found in The Sanctuary of Zi\'Tah and Old Goobbues (UR) found in The Boyahda Tree.' },
                { 'Recommended to farm it with Treasure Hunter 8 (or any TH) in The Sanctuary of Zi\'Tah which has 13 spawns and 5 minutes respawn. All the Goobbue Gardener spawns are in the north-east and south-east section of the map.', sub = {
                    { 'Easiest transportation option is the Level 122 The Sanctuary of Zi\'Tah Unity warp.' },
                } },
            } },
            { 'Return to Apururu for a cutscene.' },
            { 'Zone into Full Moon Fountain for a cutscene that completes the Mission.', sub = {
                { 'Home Point #1 to Toraimarai Canal is the fastest way.' },
            } },
        },
    },
    ['Windurst Mission 9-2'] = {
        title        = 'Moon Reading',
        starting_npc = 'Any Windurst Gate Guard',
        subtitle     = 'Vestal Chamberlain',
        repeatable   = 'No',
        description  = 'To lure the Bearer of Darkness to the Full Moon Fountain, you must collect the three verses of the ancient people. As her guiding star, the Star Sibyl is counting on you to help her decide the path for Windurst\'s future. The fate of Windurst rests upon your shoulders!',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Optional: Talk to everyone from Kupipi and beyond for unique dialogue to this part of the mission within Heavens Tower. The guards just before the teleporter in Windurst Walls will also vary at different points in these missions.', sub = {
                { 'After the upcoming cutscene on the top floor, the dialogue will also be changed for 3 of the 4 Mithra on the top floor closest to the chamber (Shaz Norem\'s does not change).' },
                { 'All this dialogue will change yet again after the BCNM of this mission, so before then is your only opportunity to experience it.' },
            } },
            { 'Click the Door: Vestal Chamber on the top floor of Heavens Tower for a cutscene about the Star Sibyl.' },
            { 'Collect the following 3 Key Items in any order:' },
        },
    },
}

quest_info['sandoriamissions'] = {
    ['San d\'Oria Mission 1-1'] = {
        title        = 'Smash the Orcish Scouts',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'None',
        repeatable   = 'Yes',
        description  = 'Mission Orders: Hunt Orcs lurking outside San d\'Oria and bring back one of their axes.',
        series       = 'Kingdom of San d\'Oria',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to any San d\'Orian Gate Guard to begin this Mission.', sub = {
                { 'Ambrotien - Southern San d\'Oria (K-10)' },
                { 'Endracion - Southern San d\'Oria (F-9)' },
                { 'Grilau - Northern San d\'Oria (D-8)' },
            } },
            { 'Go outside the city and kill Orcish Fodder until you receive an Orcish Axe.', sub = {
                { 'Orcish Fodder can be found in East Ronfaure and West Ronfaure.' },
            } },
            { 'After you receive an Orcish Axe return to the Gate Guard and trade them the Orcish Axe to finish the Mission.' },
        },
    },
    ['San d\'Oria Mission 1-2'] = {
        title        = 'Bat Hunt',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'None',
        repeatable   = 'Yes',
        description  = 'Mission Orders: Exterminate bats from King Ranperre\'s Tomb, and bring back proof of your deeds.',
        series       = 'Kingdom of San d\'Oria',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to any San d\'Orian Gate Guard, and select "Bat Hunt" to begin this Mission.' },
            { 'Go to (H-11) in East Ronfaure to zone into King Ranperre\'s Tomb.', sub = {
                { 'If you do not have a map for King Ranperre\'s Tomb, one may be purchased from Violitte – Southern San d\'Oria (G-10) or Elesca – Northern San d\'Oria (I-8).' },
            } },
            { 'Kill Ding Bats in King Ranperre\'s Tomb (which spawn at night from 18:00 to 6:00) until you receive Orcish Mail Scales.', sub = {
                { 'This can be done before or after clicking the Tombstone.' },
                { 'There are 2 Bats at the entrance and more around the Tombstone.' },
            } },
            { 'Touch the Tombstone at (H/I-10) for a cutscene.', sub = {
                { 'There is a ghost that aggros by it at night if low level. Can just click the Tombstone to lose aggro or use sneak.' },
            } },
            { 'Return to a Gate Guard and trade them the Orcish Mail Scales to complete the Mission.' },
        },
    },
    ['San d\'Oria Mission 1-3'] = {
        title        = 'Save the Children',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'Fodderchief Flayer',
        repeatable   = 'Yes',
        description  = 'Mission Orders: Rescue the children held captive in the Orcish camp in Ghelsba Outpost.',
        series       = 'Kingdom of San d\'Oria',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Talk to any Gate Guard and accept the Mission.' },
            { 'Next speak to Arnau in the Cathedral in Northern San d\'Oria.', sub = {
                { 'He is the main NPC at the Altar in the Chapel section of the Cathedral.' },
            } },
            { 'After the cutscene, head to Ghelsba Outpost. The entrance is located at (E-4) in West Ronfaure.', sub = {
                { 'The map for Ghelsba Outpost may be purchased for 600 Gil from either Elesca at (I-8) in Northern San d\'Oria or Violitte at (G-10) in Southern San d\'Oria.' },
            } },
            { 'Make your way to the Hut Door in the large area around (G-9). The door itself is located at (F-10).' },
            { 'Interact with the Hut Door and clear the BCNM Save the Children. You will obtain Key Item Orcish hut key.', sub = {
                { 'Up to 6 people are allowed into this BCNM if they are on or have completed this Mission.' },
                { 'When entering the battlefield, a Level Restriction (Status) effect will be applied (level unlimited), which serves to reset TP, desummons Trusts, and prevents exp loss if you\'re defeated. Trusts can be used in the battlefield: be sure to wait until your trust magic Recast Time is ready, and summon them after entering the battlefield but before entering combat.' },
                { 'You will fight 3 Orcs.', sub = {
                    { 'Fodderchief Vokdek (WAR)' },
                    { 'Strongarm Zodvad (RNG)' },
                    { 'Sureshot Snatgat (RNG)' },
                } },
            } },
            { 'Interact with the Hut Door after clearing the BCNM for a cutscene.' },
            { 'Return to a Gate Guard to complete the Mission and receive Rank 2.', sub = {
                { '(Optional): There is an additional cutscene at Arnau after speaking with the Gate Guard.' },
            } },
        },
    },
    ['San d\'Oria Mission 2-1'] = {
        title        = 'The Rescue Drill',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Participate in the Temple Knights\' rescue drill out on La Theine Plateau.',
        series       = 'Kingdom of San d\'Oria',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to any Gate Guard and accept the mission.' },
            { 'Head to La Theine Plateau and speak to Galaihaurat at (E-6), at the very top of the cliffs.', sub = {
                { 'If you are already level 99, the fastest travel option is the warp to Abyssea - La Theine via Horst that puts you at at (E-4). Second place is the Ordelle\'s Caves Survival Guide.' },
            } },
            { 'At the east side of (F-6), head down the ramp.' },
            { 'Continue into Ordelle\'s Caves at (F-7), in a tunnel at the south of the canyon.', sub = {
                { '(Optional): You can talk to Equesobillot, Deaufrain, Vicorpasse, Augevinne, Yaucevouchat, Laurisse, and Narvecaint for some additional dialogue as you head down into and through the canyon.' },
            } },
            { 'Once inside Ordelle\'s Caves, follow the left wall and talk to Ruillont at (G-3) in the corner behind a rock, in the small pond.' },
            { 'Go back to La Theine Plateau. Either Deaufrain (halfway up the ramp out of the canyon), Equesobillot (at the top of the ramp out of the canyon) or Galaihaurat (at the top of the cliffs by a wall next to the canyon) will have the Bronze Sword needed to progress the mission.', sub = {
                { 'The NPC which has the sword seems to be entirely random for each player.' },
            } },
            { 'Head back to Ruillont in Ordelle\'s Caves, and trade his Bronze Sword to him.' },
            { 'Go back to La Theine Plateau and talk to Vicorpasse (F-6) for Key Item Rescue training certificate.' },
            { 'Return to a Gate Guard to complete the mission.' },
        },
    },
    ['San d\'Oria Mission 2-2'] = {
        title        = 'The Davoi Report',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'None',
        repeatable   = 'Yes',
        description  = 'Retrieve the latest scouting report from the Temple Knight scout somewhere in Davoi.',
        series       = 'Kingdom of San d\'Oria',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Talk to any Gate Guard and accept the Mission.', sub = {
                { 'There are two in Southern San d\'Oria, Ambrotien at (K-6) and Endracion at (F-9). There is also a gate guard in Northern San d\'Oria, Grilau at (D-8).' },
                { 'A map of Davoi can be purchased for 3000 Gil from Elesca at (I-8) of North San d\'Oria or Violitte at (G-10) of Southern San d\'Oria, but it is not required.' },
            } },
            { 'Make your way to Davoi. To reach Davoi, zone into Jugner Forest from La Theine Plateau at (M-8). Then follow the right wall of Jugner Forest to the zone into Davoi at (G-12).' },
            { 'Talk to the NPC Zantaviat just inside the zone.' },
            { 'Walk south until you reach a pond at (J-8). On the South bank of the pond you will find a ! targetable location. Click on it to receive the Key Item Lost document.' },
            { 'Return to Zantaviat to recieve the Key Item Temple Knights\' Davoi report.' },
            { 'Return to a Gate Guard.' },
            { 'Examine the Door: Papal Chambers, which is on the top floor of the Cathedral in Northern San d\'Oria.' },
            { 'After the cutscene, the Mission will be completed.' },
        },
    },
    ['San d\'Oria Mission 2-3'] = {
        title        = 'Journey Abroad',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'Black Dragon Slayer or Dark Dragon Slayer, Certified Adventurer',
        repeatable   = 'No',
        description  = 'Visit the faraway nations of Bastok and Windurst and receive official recognition as an adventurer.',
        series       = 'Kingdom of San d\'Oria',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'You will be instructed to speak with Halver. He is located at (I-9) just inside the door of Chateau d\'Oraguille, entered from Northern San d\'Oria.' },
            { 'Halver will instruct you to visit two other Nations: Bastok and Windurst.', sub = {
                { 'After reaching Rhapsodies of Vanadiel Mission 1-7 you will be given a Cipher: Halver if you do not already possess this Trust.' },
            } },
            { 'The next leg of this Mission can be done in two different ways:', sub = {
                { 'Go to Bastok first and then to Windurst.' },
                { 'Go to Windurst first and then Bastok.' },
            } },
            { 'If you have never visited Bastok or Windurst, you can "Unity warp" to either South Gustaberg or East Sarutabaruta, then make the rest of the trek on foot. Speak to Urbiolaine in Southern San d\'Oria (G-10) and choose "Bring me to a Wanted encounter area", then "Content level 99 and below."' },
            { 'The Bastok Path may be quicker due to the ease of obtaining the item involved.', sub = {
                { 'Bastok will require obtaining a Mine Gravel, which can be bought off the Auction House.' },
                { 'Windurst will require obtaining two Parana Shields, but these are 100% drops and can be obtained in 5 minutes apart.' },
            } },
            { 'The Windurst Path final BCNM may be a bit easier as the Petrify AoE will not be used.' },
        },
    },
    ['San d\'Oria Mission 3-1'] = {
        title        = 'Infiltrate Davoi',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'None',
        repeatable   = 'Yes',
        description  = 'The scout in Davoi needs the help of an adventurer.',
        series       = 'Kingdom of San d\'Oria',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'This Mission is Required.' },
        },
    },
    ['San d\'Oria Mission 3-2'] = {
        title        = 'The Crystal Spring',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'None',
        repeatable   = 'Yes',
        description  = 'Catch a crystal bass from Crystwater Spring, located on the eastern edge of Jugner Forest.',
        series       = 'Kingdom of San d\'Oria',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Talk to any Gate Guard and accept the Mission.', sub = {
                { 'There are two in Southern San d\'Oria, Ambrotien at (K-6) and Endracion at (F-9). There is also a gate guard in Northern San d\'Oria, Grilau at (D-8).' },
            } },
            { 'Buy a Crystal Bass from the Auction House ( ➞ Food ➞ Fish) or you can catch one in Jugner Forest.', sub = {
                { 'It is MUCH easier to buy one from the Auction House. Crystal Bass cap at 35 for fishing, so plan accordingly.' },
                { 'See below for fishing tips.' },
            } },
            { 'Trade the Crystal Bass to the Gate Guard.' },
            { 'Enter Chateau d\'Oraguille for a cutscene.' },
            { 'Talk to Chalvatot located in the late Queen Leaute\'s Garden by her Tombstone (F-7) inside Chateau d\'Oraguille for a cutscene. Afterwards the Mission is completed.', sub = {
                { 'Repeating this Missions is similar to Mission 1-2. You do not need to zone between repeating, you also do not have to repeat the steps in Chateau d\'Oraguille.' },
            } },
        },
    },
    ['San d\'Oria Mission 3-3'] = {
        title        = 'Appointment to Jeuno',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Head to the Embassy of San d\'Oria in Jeuno to fill your appointed post.',
        series       = 'Kingdom of San d\'Oria',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to Halver in Chateau d\'Oraguille at (I-9).' },
            { 'Click the Door: Great Hall behind Halver for a cutscene. You will obtain Key Item Letter to the ambassador.' },
            { 'Head to the San d\'Orian Embassy in Ru\'Lude Gardens (H-9) and speak with Nelcabrit.', sub = {
                { 'If you already possess the Delkfutt Key (trade it to the door) or the Key Item Delkfutt key (no trading needed) then you may skip this climb:', sub = {
                    { 'Head to Lower Delkfutt\'s Tower (E-8) Map 1 and enter the Basement by clicking the Cermet Door. Once you go through the door, proceed to (L-8) and click the Cermet Door for a cutscene. (Note: Another player using a key does not work.)' },
                    { 'Return to the San d\'Orian Embassy in Ru\'Lude Gardens and click the Door: San d\'Orian Emb. for a cutscene to complete the Mission.' },
                } },
                { 'If you do not possess the Key, start the climb process detailed below:', sub = {
                    { 'You may be Tractored through this Basement door without the Key. If you decide to go this route, proceed to the "Obtaining Delkfutt Key Short Way" section.' },
                    { 'Otherwise, read the "Obtaining Delkfutt Key" section.' },
                } },
            } },
            { 'Head to Lower Delkfutt\'s Tower using the Survival Guide teleportation, Outpost warp, or Home Point warp.' },
            { 'You will now likely need to climb to the 10th floor of Delkfutt\'s Tower in order to gain a Delkfutt Key in order to access the Basement of the Tower:' },
        },
    },
    ['San d\'Oria Mission 4-1'] = {
        title        = 'Magicite',
        starting_npc = 'San d\'Orian Embassy in Ru\'Lude Gardens',
        subtitle     = 'Have Wings Will Fly',
        repeatable   = 'No',
        description  = 'Seize the three types of magicite from Davoi, Beadeaux, and Castle Oztroja to prevent the Shadow Lord\'s return.',
        series       = 'Kingdom of San d\'Oria',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'To flag the Mission, speak with Nelcabrit, then click the Door: San d\'Orian Emb. in Ru\'Lude Gardens (G-10) for the Key Item Archducal audience permit.', sub = {
                { 'The 3rd door on the left in the San d\'Orian Embassy is the correct one.' },
            } },
            { 'Click on the Door: Audience Chamber in Ru\'Lude Gardens (H-5) for a cutscene and the Key Item Letter to Aldo.' },
            { 'Speak to Aldo in Lower Jeuno, in the back of the Neptune\'s Spire Tenshodo H.Q. for a cutscene and the Key Item Silver bell.', sub = {
                { 'If you have done this mission in a other Nation then you already have the bell, but you still need to talk to him for a cutscene.' },
            } },
            { 'Obtain the 3 Magicite Key Items. See below for details.' },
            { 'Click the Audience Chamber in Ru\'Lude Gardens (H-5) after obtaining all 3 Magicites for a cutscene and your reward (either an Key Item Airship Pass, or, if you already have one, 20,000 Gil).' },
            { 'Return to Nelcabrit in the San d\'Orian Embassy to complete the mission, receive 10,000 Gil and Key Item Message to Jeuno (San d\'Oria).' },
        },
    },
    ['San d\'Oria Mission 5-1'] = {
        title        = 'The Ruins of Fei\'Yin',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'Archmage Assassin',
        repeatable   = 'No',
        description  = 'This mission involves traveling to Fei\'Yin, located on the Beaucedine Glacier. Visit Chateau d\'Oraguille to learn more.',
        series       = 'Kingdom of San d\'Oria',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into Chateau d\'Oraguille for a cutscene that includes King Destin.' },
            { 'Visit any Gate Guard and accept the Mission.' },
            { 'Return to Chateau d\'Oraguille and speak to Halver to receive Key Item New Fei\'Yin seal.', sub = {
                { 'If you are low level, you might want to use Trusts or form a party of lvl 50+ players.' },
            } },
            { 'Go to Fei\'Yin (located in the northeast corner of Beaucedine Glacier) for a cutscene with Zeid. You will have to reach the Qu\'Bia Arena and clear the BCNM "The Rank 5 Mission".', sub = {
                { 'The majority of enemies in Fei\'Yin detect by Sound sound, however there are several that detect Magic spellcasting.' },
                { 'Quick Travel options:', sub = {
                    { 'Home Point #1 to Fei\'Yin is the fastest way, it puts you right at the zone to Qu\'Bia Arena.' },
                    { 'Unity Warp (Level 128) will place you at the entrance of Fei\'Yin.' },
                    { 'Unity Warp (Level 125) will place you in the central area of Beaucedine Glacier.' },
                    { 'Domenic will teleport characters to Qu\'Bia Arena for 1,000 gil (upon completion of Beyond Infinity). Just zone out for the cutscene (and the Home Point), then zone back in.' },
                } },
                { 'From the entrance of Fei\'Yin:', sub = {
                    { 'Go east to (K-8). There are 2 Dolls in front of a door named Cermet Portal, open it and you\'ll be able to enter Qu\'Bia Arena.' },
                } },
            } },
        },
    },
    ['San d\'Oria Mission 5-2'] = {
        title        = 'The Shadow Lord',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'Shadow Banisher',
        repeatable   = 'No',
        description  = 'Head to Castle Zvahl in Xarcabard. Visit Chateau d\'Oraguille to learn more.',
        series       = 'Kingdom of San d\'Oria',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to Halver for a some text about Prince Trion.' },
            { 'Examine Door: Prince Royal\'s Rm for a cutscene with Trion.', sub = {
                { 'If you\'re not using Trusts and are level 55-60, form a full party of players.' },
            } },
        },
    },
    ['San d\'Oria Mission 6-1'] = {
        title        = 'Leaute\'s Last Wishes',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'This mission involves the late Queen Leaute. Visit Monarlais Halver in Chateau d\'Oraguille to learn more.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to Chateau d\'Oraguille and speak with Halver.' },
            { 'Select the Great Hall door for a cutscene.', sub = {
                { 'Make sure to get the cutscene where the King asks you to retrieve a Dreamrose.' },
            } },
            { 'Speak with Halver again.' },
            { 'Go to (G-7) in Western Altepa Desert. The Dreamrose is butted up against Revelation Rock, in the southern section of the oasis (look for the body of water on your map).', sub = {
                { 'The Unity Warp (Level 125) will bring you close.' },
                { 'Alternatively, you could use the Survival Guide.' },
            } },
            { 'Check the Dreamrose to spawn Sabotender Enamorado.', sub = {
                { 'If you\'re low level, it is recommended that you bring enough people, pets and/or Trusts to reduce the damage done by 1000 Needles. It is possible to do it with less, but spreading the damage out will help any HP concerns.' },
            } },
            { 'Check the Dreamrose after defeating the NM to receive the Key Item Dreamrose.' },
            { 'Return to Halver.' },
            { 'Go toward the Garden at (F-8) for another cutscene. At the end of the cutscene, you\'ll receive the Key Item Piece of paper.' },
        },
    },
    ['San d\'Oria Mission 6-2'] = {
        title        = 'Ranperre\'s Final Rest',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Prince Trion seeks an adventurer. Find the prince in his chamber to learn more.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'You\'ll be instructed to go see Prince Trion. Visit him in his room at (H-7) in Chateau d\'Oraguille' },
            { 'If you\'re low level, gather a party or use Trusts.' },
            { 'Head for (H-8) in King Ranperre\'s Tomb on Map 1.' },
            { 'When ready, check the Heavy Stone Door to spawn three (3) Skeleton NMs: Corrupted Soffeil (BLM), Corrupted Yorgos (WAR) and Corrupted Ulbrig (BLM).', sub = {
                { 'They can be pulled one by one using Sneak.' },
                { 'All 3 must be slain.' },
                { 'The NMs are immune to Sleep and Lullaby.' },
                { 'They will use Blood Saber, so keep damage negating buffs up to reduce the HP regained.' },
                { 'Corrupted Yorgos has approximately 7250 HP.' },
            } },
            { 'When defeated, check the Heavy Stone Door again, and enter. Check the Tombstone inside for a cutscene, at the end of which, you\'ll receive the Key Item Ancient San d\'Orian book.', sub = {
                { '(Optional): Return to Prince Trion, and you will be instructed to go see the Gate Guard.' },
            } },
            { 'Talk to any Gate Guard. A cutscene will play out saying they sent the book to scholars to decipher.' },
            { 'You must talk to the Gate Guard once more to have them tell you that the deciphering will take some time.' },
            { 'Zone and talk to the Guard again who will tell you to see Prince Trion.' },
            { 'Return to Prince Trion and speak with him for a cutscene. You may need to talk to him twice.' },
            { 'Return to the Heavy Stone Door in King Ranperre\'s Tomb again for another cutscene. You\'ll be instructed to defeat enemies, but you only need to activate the door again.' },
            { 'Return to a Gate Guard to complete the Mission.' },
        },
    },
    ['San d\'Oria Mission 7-1'] = {
        title        = 'Prestige of the Papsque',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'The papsque has requested an adventurer of renown. Speak to His Holiness in the cathedral. His chambers lie upstairs.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to the Cathedral in Northern San d\'Oria and go to the Papal Chambers, located on the third floor at (M-6).' },
            { 'If you\'re low level, form a party and/or use Trusts.', sub = {
                { 'Sneaking is recommended, bring some Silent Oils.' },
            } },
            { 'Head to Bostaunieux Oubliette, which can be accessed from Chateau d\'Oraguille (I-8). If you already explored the place, alternate paths are available below.', sub = {
                { 'Head for (E-7/8) and use Sneak. Speak to Couchatorage standing by the Sewer Lid to drop down to Map 2. Be sure to grab the Survival Guide nearby if this is your first time here.' },
                { 'Follow the right wall and you\'ll eventually zone to West Ronfaure at (E-8). There will be a ??? in front of you.' },
            } },
            { 'When prepared, check the ??? to spawn an Orc NM Marauder Dvogzog.', sub = {
                { 'It is a level 67 MNK with approximately 16,000 HP, capable of using Hundred Fists.' },
            } },
            { 'Check the ??? again to receive the Key Item Ancient San d\'Orian tablet.', sub = {
                { 'Should you fall off of the ledge, you\'ll need to run back through the Oubliette and fight the NM again.' },
            } },
            { 'Return to the Cathedral and visit the Papal Chambers for the final cutscene.' },
        },
    },
    ['San d\'Oria Mission 7-2'] = {
        title        = 'The Secret Weapon',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Reports from Ghelsba indicate that the Orcs in Yughott Grotto are up to something. Investigate, but speak of this to no one.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak with a Gate Guard who will instruct you to go to the Garden in Chateau d\'Oraguille.' },
            { 'Head for Chateau d\'Oraguille and go towards (F-8). You will receive a cutscene.' },
            { 'Return to the Gate Guard to receive the Mission.' },
            { 'If you\'re low level, gather a party and/or use Trusts.', sub = {
                { 'Only players who are on 7-2 or have completed it may enter.' },
                { 'It is recommended that you bring a BLM and/or a BRD for sleeping the mobs.' },
            } },
            { 'You will have to reach Horlais Peak, accessible via travelling through Ghelsba Outpost and Yughott Grotto.', sub = {
                { 'Yughott Grotto Home Point #1 places you right ouside the entrance to the Peak.' },
            } },
            { 'Once you\'re there, get ready and enter the BC.', sub = {
                { 'The fight is against 3 Orcs and 2 Warmachines:' },
                { 'Darokbok of Clan Reaper (Level 68, PLD)' },
                { 'Derakbak of Clan Wolf (Level 68, DRG)' },
                { 'Jagidbod of Clan Reaper (Level 68, RNG)' },
                { 'Wolf Clan Warmachine (Level 68)' },
                { 'Reaper Clan Warmachine (Level 68)' },
                { 'Open the fight with Elemental Seal + Sleepga II. Fight the Warmachines first, then the Paladin, the Dragoon and Wyvern, and the Ranger last. A Melee/NIN can pretty easily solo any of the NMs. Prioritize the Warmachines.' },
            } },
            { 'When finished, you\'ll receive another cutscene, and receive the Key Item Crystal dowser.' },
            { 'Head back to San d\'Oria and speak to any Gate Guard to finish the mission.' },
        },
    },
    ['San d\'Oria Mission 8-1'] = {
        title        = 'Coming of Age',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Princess Claidie will soon celebrate her coming-of-age, and the court in d\'Oraguille needs help with the ceremonies. Speak to Monarlais Halver and offer your assistance.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Go to Chateau d\'Oraguille, where you\'ll receive a cutscene upon entering.' },
            { 'Speak to Halver for instructions.', sub = {
                { '(Optional): Interact with the two doors to the Princes\' quarters for short cutscenes.' },
            } },
            { 'Travel to the Quicksand Caves Map 2.', sub = {
                { 'The cave entrance at Eastern Altepa Desert (H-10) will place you on Map 2.', sub = {
                    { 'Located just east of the Survival Guide warp to Eastern Altepa Desert.' },
                    { 'Alternatively, using the Unity Warp (Level 125) for Quicksand Caves will place you at (J-6) on Map 1. You will need to walk south and then west to (F-10) to reach Map 2.' },
                } },
            } },
            { 'You will need to drop down a hole at (E-11) to reach an isolated portion of the map.' },
            { 'Once you drop down, travel to the Fountain of Kings at (G-14).' },
            { 'Clear the area and check Fountain of Kings. This will spawn 2 Kraken NMs: Honor and Valor:', sub = {
                { 'You can pull them one at a time, they will not link, but will aggro to Sound sound.' },
                { 'Valor uses Hundred Fists.' },
                { 'Honor casts Paralyga and Silencega.' },
                { 'It is possible to land Blind and Gravity on either, but both resist Sleep.' },
                { 'Letting one depop and then defeating the other makes this a lot easier to deal with.' },
            } },
            { 'Check the Fountain of Kings again, after the bodies disappear, for some Key Item Drops of Amnio.' },
            { 'Return to Halver.' },
            { 'Wait 1 Earth minute, then exit the Chateau (into Northern San d\'Oria) for another cutscene.' },
        },
    },
    ['San d\'Oria Mission 8-2'] = {
        title        = 'Lightbringer',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Royaulais Destin himself has summoned you for a vital mission. Seek audience with His Majesty in Chateau d\'Oraguille immediately.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to Chateau d\'Oraguille and check the Great Hall door for a cutscene.' },
            { 'Speak with Rahal (H-9, western door directly across from the entry way) to receive the Key Item Crystal dowser and further instructions.' },
            { 'Head to the Temple of Uggalepih and farm a Prelate Key from the Tonberry Stabbers on Map 3/4.', sub = {
                { 'See the note below before farming the key. Alternatively you may farm Tonberry Choppers in the Yhoator Jungle or Tonberry Slashers in the Den of Rancor.' },
                { 'Several Tonberry Slashers spawn in the large room near the Den of Rancor Unity Warp (Level 128).' },
            } },
            { 'Make your way through the Temple until you reach the door at (I-10) on Map 2, that can only be opened by killing the Temple Guardian.', sub = {
                { 'The Temple of Uggalepih Geomagnetic Fount is closest.' },
                { 'Alternate Route: Take the Survival Guide to Temple. Exit out to Yhoator Jungle. Go around the corner to entrance #3 back into the temple, and you will be on Map 2.' },
                { 'The Guardian will not be there and the door will be open if someone has defeated it in the last 15 minutes.' },
            } },
            { 'Pass into the big room, and head upstairs and through the door at (J-10) which requires the Prelate Key.', sub = {
                { 'Note: The door on top of the east set of stairs can be bypassed without a Prelate Key. One way of doing this is summoning a Trust that moves away from you, such as Yoran-Oran, engaging an enemy in front of the door, and hoping that the Trust runs through the door. This is a much faster method than dealing with the low drop rate of the key.' },
                { 'You only need 1 Prelate Key to open this door for yourself or an entire party. As soon as someone makes it behind this door they can open it for anyone else coming through.' },
            } },
            { 'In the south hallway examine the three ??? in any order. From west to east, they are in the first (G-10), third (H-10), and fourth rooms (I-10). The fourth room has multiple ???, ensure you get the message "Obtained key item: Piece of a broken key."', sub = {
                { 'Each ??? will provide a Key Item Piece of a broken key.' },
                { 'Each player in the party must obtain the 3 Key Item Piece of a broken key in order to complete the final cutscene.' },
            } },
            { 'After you have all 3 keys, select the second door (H-10) to spawn 2 Doll NMs: Nio-Hum and Nio-A.', sub = {
                { 'Both have around 6500 HP, do regular Doll attacks, and cannot be slept.' },
                { 'You may pull one at a time if Sneak is activated before spawning.' },
                { 'The Dolls are aggressive to magic so you may not pull with magic.' },
            } },
            { 'After the Dolls have been defeated, check the door again for a cutscene.', sub = {
                { 'This cutscene will detail that you failed to find the sword you came here for, it is the correct cutscene. You can warp out after this.' },
            } },
            { 'Return to Chateau d\'Oraguille and check the Great Hall door for a cutscene.' },
            { 'You will be awarded Rank 9 and 80,000 Gil.' },
        },
    },
    ['San d\'Oria Mission 9-1'] = {
        title        = 'Breaking Barriers',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Darkness looms over San d\'Oria. Report to the Audience Chamber in Chateau d\'Oraguille for further details.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { '(Optional): The following are optional steps you can take.', sub = {
                { 'Interact with the two doors to the Princes\' Quarters for short cutscenes.' },
                { 'Speak with Curilla and Rahal for small talk about the previous Mission. They will also have different dialogue after the KIs are obtained but before the Mission is completed.' },
            } },
            { 'Go to the Chateau and check the Great Hall door for a cutscene.' },
            { 'You must now travel to 3 ??? and obtain 3 Key Items.' },
        },
    },
    ['San d\'Oria Mission 9-2'] = {
        title        = 'The Heir to the Light',
        starting_npc = 'Any San d\'Oria Gate Guard',
        subtitle     = 'San d\'Orian Royal Heir',
        repeatable   = 'No',
        description  = 'The Rites of Succession will be held at the cathedral in Northern San d\'Oria. You are to report there for guard duty.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into Northern San d\'Oria for a lengthy cutscene.', sub = {
                { 'If you accepted the Mission from the Northern San d\'Oria gate guard, you can talk to Arnau to see they are still preparing the Rites.' },
                { 'You will be prohibited from zoning into Chateau d\'Oraguille due to increased security until you\'ve triggered the cutscene in Northern San d\'Oria.' },
            } },
            { 'Zone into Chateau d\'Oraguille for a cutscene.' },
            { 'Head to Fei\'Yin for a cutscene.' },
            { 'Make your way to Qu\'Bia Arena for a two-part BCNM fight, "The Heir to the Light".', sub = {
                { 'Use Fei\'Yin Home Point #1 or Domenic to teleport right outside the arena, then walk a short distance to zone into the small room with the Burning Circle.' },
            } },
            { 'Part One will have Death Clan Destroyer (WHM Warmachine), Yukvok of Clan Death (Unsleepable Orc RNG), 3 Worgbut of Clan Death, 3 Rallbrog of Clan Death, and 3 Vangknok of Clan Death (Orcs, Sleepable).', sub = {
                { 'Open with Elemental Seal+Sleepga II or Horde Lullaby, and start attacking the Ranger mob first. Make sure you silence the Warmachine, as it is a WHM who can Curaga and wake everything up. Defeat the Ranger, followed by the Warmachine, and then take our the rest.' },
                { 'Sleep the last mob before killing it, and give yourself a rest. There will be no time after the first part of the fight to rest.' },
            } },
            { 'Part Two will include Prince Trion fighting by your side, against 3 Orc NMs, Warlord Rojgnoj (PLD unsleepable), Rojgnoj\'s Left Hand (BLM), and Rojgnoj\'s Right Hand (DRK).', sub = {
                { 'Trion will randomly attack a mob, and should be helped. Preferably, the order to kill the NMs is BLM > PLD > DRK. Trion can be cured and can die in the BC. Should he die, you will be ejected from the BC. Despite being a Paladin, he isn\'t great at keeping himself alive.' },
                { 'Keep the other mobs silenced, a Paladin with Invincible is useful here for keeping attention.' },
            } },
            { 'Upon clearing the battlefield, zone into Northern San d\'Oria for a cutscene.' },
            { 'Head to the Chateau and check the Great Hall door for another cutscene.' },
            { 'Make your way to (H-8) in King Ranperre\'s Tomb and check the Heavy Stone Door -- the same from a previous mission -- for yet another cutscene.' },
            { 'Go back to the Chateau and speak to Halver and you will receive your rewards.', sub = {
                { '(Optional): Exit to Northern San d\'Oria and proceed to the Papal Chamber door.' },
            } },
            { 'Zone into Southern San d\'Oria for a final epilogue cutscene!' },
        },
    },
}

quest_info['zilartmissions'] = {
    ['Divine Might'] = {
        title        = 'Divine Might',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = '',
        series       = '',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter The Shrine of Ru\'Avitau from the (H-9) entrance in Ru\'Aun Gardens.', sub = {
                { 'Survival Guide puts you on the path to it, if you have it.' },
                { 'Home Point #5 is another fast alternative.' },
            } },
            { 'Head North a short distance to find a Blank Target at (G/H-11).' },
            { 'Examine the Blank Target for a cutscene.' },
            { 'Examine the Blank Target again for dialogue about how to obtain an Ark Pentasphere.', sub = {
                { 'Divine Might now appears in your Outlands Quests log.' },
            } },
            { 'You, or someone in your group, will need to obtain an Ark Pentasphere.', sub = {
                { 'Ark Pentaspheres are created by trading 1 Illuminink and 1 Parchment to the Qu\'Hau Spring at (H-6) in Ro\'Maeve during a full moon and between 18:00 and 06:00 game time.' },
                { 'Illuminink drops off Cursed Puppet and Magic Flagon in Ro\'Maeve.' },
            } },
            { 'Trade the Ark Pentasphere to any of the Shimmering Circles in La\'Loff Amphitheater to access the battlefield.' },
        },
    },
    ['Promathia Mission 8-5'] = {
        title        = 'The Last Verse',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'N/A',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {},
    },
    ['Zilart Mission 1'] = {
        title        = 'The New Frontier',
        starting_npc = 'Obtain Rank 6 and zone in to Norg.',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Vana\'diel is expanding day by day. What adventures await you in the Outlands?',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Entering Norg will trigger a cutscene.', sub = {
                { 'If you previously chose to postpone the cut-scene, use Tales\' Beginning which is located near Home Point #1 in Norg to resume the story.' },
            } },
        },
    },
    ['Zilart Mission 2'] = {
        title        = 'Welcome t\'Norg',
        starting_npc = 'None',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Lion has someone she wants you to meet. She will be waiting for you at the room at the end of the hallway on the second floor of Norg.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head for (L-8) in Norg and enter the Oaken Door. You\'ll receive a cutscene with Gilgamesh.' },
        },
    },
    ['Zilart Mission 3'] = {
        title        = 'Kazham\'s Chieftainess',
        starting_npc = 'None',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Before you travel to the Temple of Uggalepih, you are to meet with the Kazham chieftainness, Jakoh Wahcondalo.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Go to Kazham (J-9) and speak with Jakoh Wahcondalo. She will give you a Key Item Sacrificial Chamber key required to progress further in the Temple of Uggalepih.', sub = {
                { 'Using Elshimo Low > Kazham > Home Point #1 will bring you right next to the house of Jakoh Wahcondalo.' },
            } },
        },
    },
    ['Zilart Mission 4'] = {
        title        = 'The Temple of Uggalepih',
        starting_npc = 'None',
        subtitle     = 'Bearer of the Wisewoman\'s Hope',
        repeatable   = 'No',
        description  = 'The Temple of Uggalepih is an ancient place where it is said that evil deities were once worshipped. Gilgamesh has ordered you to travel there and search out a strange, old hermit.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter the Temple from the main entrance in Yhoator Jungle (J-11/12).', sub = {
                { 'The Voidwatch warp brings you to this entrance.' },
            } },
            { 'Make your way to the northwestern exit at (F-5). Pick up the Survival Guide on the way.', sub = {
                { 'You will zone out into Yhoator Jungle. Make a left after zoning.' },
            } },
            { 'Enter the temple again from (H-11), and work your way down to the Temple Guardian at (I-10).', sub = {
                { 'Kill the guardian if he is up, otherwise the door will be open already.' },
            } },
            { 'Go ahead to (I-7). The door is on the far side of the room. Whoever has the Key ItemPaintbrush of souls needs to stand at the empty frame in the middle of the wall. Everyone else wait by the door.', sub = {
                { 'To use the Paintbrush, check the frame and confirm you wish to continue. You should get a message saying "a new painting begins to appear on the canvas". Wait 30 seconds without moving or entering any commands, and check it again. You should get another message about the Den of Rancor, and the door will open.' },
                { 'The person who is checking the frame cannot be aggro\'d or acted on during these 30 seconds, otherwise you\'ll have to start over.' },
            } },
        },
    },
    ['Zilart Mission 5'] = {
        title        = 'Headstone Pilgrimage',
        starting_npc = 'None',
        subtitle     = 'Bearer of the Eight Prayers',
        repeatable   = 'No',
        description  = 'Somewhere on the island of Zepwell lie the remains of an ancient temple.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Due to the long nature of this mission, it is recommended that you take precautions to ensure that you have received the key items. This mission can take a while, as it requires travel to a lot of different places, some in the far corners of large and dangerous zones. Always ensure that when checking a headstone you receive the message that you obtained the key item.' },
            { 'If you are too far away the game can give you the message, "You need to move closer to key item" and at a quick glance this can appear the same as you acquiring it. Be sure to double check.' },
            { 'There are two types of headstones, one type only gives the key item, others spawn NMs that you must defeat before you may receive the key item.' },
            { 'Several headstones are close to Cloister home points, it\'s recommended to grab those on the way if you haven\'t unlocked them yet.' },
        },
    },
    ['Zilart Mission 6'] = {
        title        = 'Through the Quicksand Caves',
        starting_npc = 'None',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'You must hurry to Zepwell\'s Island\'s ancient temple.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Everything here is aggressive to Sound sound, so make sure everyone has Sneak.', sub = {
                { 'Using the Unity Warp 125 will locate you in Western Altepa Desert (I-7).' },
            } },
            { 'Proceed to Western Altepa Desert and head for the tunnel at (C/D-11) south side.', sub = {
                { 'Following this tunnel will bring you to an unmarked area of the desert.' },
            } },
            { 'Head down the ramp to (D-12) and enter Quicksand Caves.' },
            { 'Go to (I-9) and step on the weight pad and go through the door.', sub = {
                { 'If the KI Key Item Loadstone was acquired, you still need to step on the weight pads.' },
            } },
            { 'Go west to (H-7) and use another weight pad to pass through a door.' },
            { 'In the next room, drop down the hole to a hidden area.' },
            { 'Head to (D-4) to zone in to the Chamber of Oracles.' },
        },
    },
    ['Zilart Mission 8'] = {
        title        = 'Return to Delkfutt\'s Tower',
        starting_npc = 'None',
        subtitle     = 'Destroyer of Antiquity',
        repeatable   = 'No',
        description  = 'Hurry to Delkfutt\'s Tower and stop the Zilartian princes from completing their plan to open the Gate of the Gods.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { '(Optional) Aldo\'s Decision: At the Tenshodo HQ in Lower Jeuno, speak to Aldo for a cutscene.' },
            { 'Zone into Lower Delkfutt\'s Tower from Qufim Island or via Survival Guide for a cutscene.' },
            { 'Zone into Stellar Fulcrum for a cutscene.', sub = {
                { 'Home Point # 1 in Upper Delkfutt\'s Tower puts you right at this zone. You can then use the teleporter.' },
            } },
            { 'Having a Delkfutt Key or Key Item Delkfutt key will greatly speed this mission up.' },
            { 'If you have a key, proceed to (E-8) on the first floor and go through the cermet door to the basement.', sub = {
                { 'Then proceed to (J-8) for another cermet door.' },
                { 'In the middle of the spiral staircase at (H-8) click the ??? to be teleported to the 10th floor.' },
            } },
            { 'If you do not have the key then you will have to climb the tower regularly.' },
        },
    },
    ['Zilart Mission 9'] = {
        title        = 'Ro\'Maeve',
        starting_npc = 'None',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'The Gate of the Gods, Tu\'Lia, has been restored by Eald\'narche. What do his words "Ro\'Maeve" and "blessed by the light" mean? What is Lion\'s next move?',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { '(Optional) Head to the Tenshodo and speak to Aldo.' },
            { 'Go to Norg and speak with Gilgamesh, who speaks of ruins north of The Sanctuary of Zi\'Tah, and may be what Eald\'narche is talking about.', sub = {
                { 'Click on the "Oaken Door" at (K-8) in Norg for the option to "Open the door"; Accepting this option starts the cut-scene.' },
            } },
            { 'You may be on other missions related to Chains of Promathia or Rhapsodies of Vanadiel.', sub = {
                { 'Make sure you choose to "Open the door" to progress this particular mission.' },
            } },
            { 'After the Cut-scene with Lion and Gilgamesh you will be standing outside the Oaken Door again and the next mission will have started.' },
        },
    },
    ['Zilart Mission 10'] = {
        title        = 'The Temple of Desolation',
        starting_npc = 'None',
        subtitle     = 'Sealer of the Portal of the Gods',
        repeatable   = 'No',
        description  = 'On the northernmost point of Mindartia and deep within the wilderness known as the Sanctuary of Zi\'Tah lies a body of ruins feared by many: Ro\'Maeve, the Temple of Desolation.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Go to Ro\'Maeve. You will need Sneak and Invisible through this area, but everything in-zone detects magic, so use Silent Oils and Prism Powders or cast Sneak and Invisible at the zone.', sub = {
                { 'You can now also use a mount in this zone.' },
            } },
            { 'If you have it, Survival Guide to Ro\'Maeve is the fastest way, it puts you right at the zone to Hall of the Gods.', sub = {
                { 'Unity Warp (125) will put you at the entrance of Ro\'Maeve.' },
            } },
            { 'Head for (H-5) and zone in to Hall of the Gods.' },
            { 'Run through the hallway and check the Cermet Grate two times. You will now be on the next mission.' },
        },
    },
    ['Zilart Mission 11'] = {
        title        = 'The Hall of the Gods',
        starting_npc = 'None',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'A strange grate prohibits you from journeying deeper into the Hall of the Gods. The depression in the center may be the key to getting through. You should probably report this find to Gilgamesh.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Unable to progress any further, head back to Norg, open the door, and speak to Gilgamesh.', sub = {
                { 'He will speak of a Mithra who was once trying to sell a crystal.', sub = {
                    { 'You will now be on the next mission.' },
                } },
            } },
        },
    },
    ['Zilart Mission 12'] = {
        title        = 'The Mithra and the Crystal',
        starting_npc = 'None',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'According to Gilgamesh, a Mithra carrying a mysterious crystal she found in Zi\'Tah was recently in Norg. Her name was something like Mary or Maroo or Maree...',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Go to Rabao Home Point #2 and speak to Maryoh Comyujah, who is in (G-7) in front of the windmill.', sub = {
                { 'Chose the top option \'Sounds fair\'. If you spam enter then you won\'t choose this.' },
            } },
            { 'She will ask you to go to the Quicksand Caves (again..).' },
            { 'Head for the secret entrance in Western Altepa Desert (C/D-11), (Same hidden zone as ZM6: Through the Quicksand Caves.)', sub = {
                { 'This Mission happens in a similar location in the caves, but on the opposite side of the area where you went before. Check the coordinates below to be sure.' },
                { 'You can use the Proto-Waypoint in Rabao at (G-8) to get to Quicksand Caves and enter into the right map (but not the right hole, you still need to go to the other side of the map).' },
            } },
            { 'Inside (On Map 5), go to (K-8) and through the pressure door, this will lead you to Map 6.', sub = {
                { 'On map 6, head for (G-8) for another pressure door.' },
            } },
        },
    },
    ['Zilart Mission 13'] = {
        title        = 'The Gate of the Gods',
        starting_npc = 'None',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'The path to Tu\'Lia has opened!',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'After the last cutscene where you teleport up, you will be granted access to Tu\'Lia, otherwise known as "sky". You\'ll be able to use the shimmering circle you found downstairs to return anytime for future reference.' },
            { 'Run forward to zone into Ru\'Aun Gardens and begin the next mission.', sub = {
                { 'Don\'t forget to grab the Survival Guide just up ahead after you zone into Ru\'Aun Gardens.' },
                { 'If you have the quest for Prishe\'s Boots +1 active, a different cutscene will play the first time you enter the zone. Exit the zone and re-enter to receive the correct cutscene.' },
            } },
        },
    },
    ['Zilart Mission 14'] = {
        title        = 'Ark Angels',
        starting_npc = 'None',
        subtitle     = 'Pentacide Perpetrator (Divine Might only)',
        repeatable   = 'Yes',
        description  = 'Apathy, arrogance, cowardice, envy, rage--the darkness that lurks within us all...',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into Ru\'Aun Gardens for a brief cutscene with Zeid and Aldo.', sub = {
                { 'If you have the quest for Prishe\'s Boots +1 active, a different cutscene will play the first time you enter the zone. Zone out and back in to trigger the proper cutscene.' },
            } },
            { 'Proceed straight forward into the teleporter and enter The Shrine of Ru\'Avitau from the (H-8) entrance in Ru\'Aun Gardens.', sub = {
                { 'Survival Guide puts you close if you have it.' },
            } },
            { 'Head north a short distance and examine the blank target at (G/H-11) for a cutscene.' },
            { 'After the cutscene, return to Ru\'Aun Gardens.' },
            { 'There are 5 BC fights to complete this mission, each spread out across the entire zone. Take the red portals to get to the appropriate towers that you see around the outside edge of the zone.', sub = {
                { 'Ru\'Aun Gardens is mostly safe from all aggro, except for the dolls which stand on blue pads, set in walls. Stay on the other side of the path from these and you\'ll be entirely safe. Everything detects magic except for birds.' },
                { 'To give a brief description of how the portals work:', sub = {
                    { 'The red portals lead to the islands in which you can access the La\'Loff Amphitheater which leads to each of the fights (where the Home Points are set when you view the map).' },
                    { 'The red portals are already activated by default.' },
                    { 'After each fight you will warp back to the island you were originally on by taking a red portal from the Home Point island. What you have to do to get to the next fight is find the pincerstone (it looks like a pincer pointing to the sky with a blue stone between) on the side of the island in the direction you want to travel (Which will be counter-clockwise in this case, i.e. starting from West to East)', sub = {
                        { 'These are marked by blue stars on the map for Ru\'Aun Gardens on this page >>.' },
                    } },
                    { 'On the first island the pincerstone is closer to the centre, but on subsequent islands it will be a small walk to your right once you warp back from the Home Point island.' },
                    { 'Activating the pincerstone will turn on the blue warp point which is located on the same side as the red portal but just to the left of it. (Imagine north is always pointing outside the circle, the blue warp point is south of the red one on the lower level).' },
                    { 'This will transport you to the next larger island and you can then take the red portal (Which is located on the other side to where you arrived) to the next Home Point island.' },
                    { 'Rinse and repeat all the way around.' },
                    { 'Basically all the larger and smaller islands are the same (with some minor differences but all points of interest are placed the same) except for the starting island in the south of the map.', sub = {
                        { 'Note: there are two of each portal circle (blue and red) on either side of each island. The smaller circle is the warp point, and the larger one is where you land. The warp point has pincers around it.' },
                    } },
                } },
            } },
            { 'Visit each of the towers and zone inside, the BC area is called La\'Loff Amphitheater.', sub = {
                { 'You will be facing 5 Ark Angels, who you first saw in the Throne Room, as each of the 5 races wearing black armor and have very pale, ghostly faces. Divine Might combines all 5 Ark Angels in a single fight, fought as an alliance. The mission itself, however, is individual fights, in 6 person BCs.' },
                { 'At each tower, you\'ll have some time to prepare, and then enter to face off against the Ark Angel. Each tower is specific, so you\'ll need to visit them all. Each Ark Angel has 2 jobs, and can use the full abilities of each, as well as their respective weapons weaponskills.' },
            } },
        },
    },
    ['Zilart Mission 15'] = {
        title        = 'The Sealed Shrine',
        starting_npc = 'None',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'The door deep within the Shrine of Ru\'Avitau is sealed with some form of supernatural power. Could this be the work of Eald\'narche?',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head for Norg and speak to Gilgamesh.' },
            { 'Head back to Ru\'Aun Gardens and go to any entrance to the Shrine of Ru\'Avitau. Enter for a cutscene. Teleporting to the home point will also trigger the cutscene.', sub = {
                { 'You may find entering the shrine from (I-6) (near Ru\'Aun Gardens Home Point #1) to save time approaching the next quest.' },
            } },
        },
    },
    ['Zilart Mission 16'] = {
        title        = 'The Celestial Nexus',
        starting_npc = 'None',
        subtitle     = 'Burier of the Illusion',
        repeatable   = 'No',
        description  = 'The fate of Vana\'diel awaits you in the Celestial Nexus!',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'The The Shrine of Ru\'Avitau is full of magic aggro, so even mages should bring along Silent Oil and Prism Powder.', sub = {
                { 'Note that Ninjutsu and Spectral Jig are also options for applying Sneak (Status) and Invisible (Status) without potentially aggroing nearby enemies.' },
            } },
        },
    },
    ['Zilart Mission 17'] = {
        title        = 'Awakening',
        starting_npc = 'None',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'And so ends another chapter in the neverending tale of Vana\'diel. However, as long as there are those who are lured by the thoughts of Paradise, the wheels of destiny will continue to turn.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter Norg for a cutscene with Gilgamesh. If you do not get a cutscene, proceed to the Captain\'s Chamber and speak to Gilgamesh there.' },
            { 'Click on the Neptune\'s Spire Inn door in Lower Jeuno for another cutscene with Aldo.', sub = {
                { 'These can be done in any order, but both must be completed before zoning to Ru\'Lude Gardens to trigger Shadows of the Departed.', sub = {
                    { 'The Quest will not trigger unless sufficient progress has been made in other questlines, visit the page Shadows of the Departed for more details.' },
                } },
            } },
        },
    },
    ['Zilart Mission 7'] = {
        title        = 'The Chamber of Oracles',
        starting_npc = 'None',
        subtitle     = 'Lightweaver',
        repeatable   = 'No',
        description  = 'The Chamber of Oracles is said to be located in the deepest area of the Quicksand Caves.',
        series       = 'Rise of the Zilart',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'You\'ll be in a room with a large device. Check each of the 8 parts of the device to insert the fragments obtained in a previous mission. You\'ll be given a cutscene, thus starting the next mission.' },
        },
    },
}

quest_info['copmissions'] = {
    ['Promathia Mission 1-1'] = {
        title        = 'The Rites of Life',
        starting_npc = 'Lower Delkfutt\'s Tower',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Brilliant light, fearsome beasts, a mysterious laboratory... What do all these have to do with the strange boy brought back to Doctor Monberaux\'s clinic in Upper Jeuno?',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to Lower Delkfutt\'s Tower in Qufim Island for a cutscene and the beginning of Chapter 1.' },
            { 'Zone into Upper Jeuno for another cutscene.' },
            { 'Go to the Infirmary in Upper Jeuno (G-10) near Home Point #3 to speak with Monberaux.' },
            { 'After the cutscene, you will receive the Key Item Mysterious amulet.' },
        },
    },
    ['Promathia Mission 1-2'] = {
        title        = 'Below the Arks',
        starting_npc = 'Pherimociel, Ru\'Lude Gardens - (G-6)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Something is afoot. Travel to the Grand Duke\'s Palace to learn details of recent events.',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to Ru\'Lude Gardens and speak with Pherimociel at (G-6) in the palace for a cutscene which begins this mission.' },
            { 'You must now complete each of the three Promyvions, which can be done in any order.', sub = {
                { 'The walkthrough for completing each Promyvion is located in the next mission, The Mothercrystals.' },
            } },
            { '(Optional) Speak with Rainhard, Ru\'Lude Gardens (H-6), at the top of the stairs in the palace for some dialogue about Harith.' },
            { '(Optional) Speak with Harith in the Duke\'s house (H-5) to learn a little more (very little) about the Emptiness.' },
        },
    },
    ['Promathia Mission 1-3'] = {
        title        = 'The Mothercrystals',
        starting_npc = 'Any of the Following: Promyvion - Dem Promyvion - Holla Promyvion - Mea',
        subtitle     = 'Ancient Flame Follower',
        repeatable   = 'No',
        description  = 'The first mothercrystal has been tainted with Emptiness. Hurry to the remaining crags to find out if any other stones have met the same fate.',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Echo Drops' },
            { 'Antidote' },
            { 'Poison Potion' },
            { 'Some form of Reraise' },
            { 'Holy Water (for the boss in Promyvion - Holla)' },
            { 'Any Animas you may have' },
            { 'Food. MP and HP regen drinks' },
            { 'Any other HP or MP potions' },
        },
    },
    ['Promathia Mission 2-1'] = {
        title        = 'An Invitation West',
        starting_npc = 'Lufaise Meadows - (K-9)',
        subtitle     = 'Dead Body',
        repeatable   = 'No',
        description  = 'You have woken up in some unknown land, only to find your amulet has been stolen by a group of three Tarutaru. You think they may have run off somewhere to the west.',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'After clearing all three Promyvions, you will appear at (K-9) in Lufaise Meadows and immediately enter a cutscene.' },
            { 'When the cutscene ends, make your way west toward Tavnazian Safehold. The entrance is at (F-10).', sub = {
                { 'There are many Orcs, Gigas, and Bugards along the way that will attack you if you are less than level 45 or so.' },
                { 'You can ride mounts in this area, avoiding monsters entirely.' },
            } },
            { 'After reaching Tavnazian Safehold, zone in for another cutscene.' },
        },
    },
    ['Promathia Mission 2-2'] = {
        title        = 'The Lost City',
        starting_npc = 'Tavnazian Safehold',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'According to its inhabitants, the Tavnazian Safehold was carved out of solid rock by survivors of the Great War. Speak with the city\'s inhabitants to learn more of their grave situation.',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'When the cutscene ends, make your way to the Walnut Door at (K-9) on the top floor of the safehold (south side).', sub = {
                { 'Make sure you go to the Walnut Door at (K-9). There\'s another Walnut Door at (K-7) that will not work.' },
            } },
            { 'Enter the room and speak to Despachiaire at (K-10) for a cutscene.', sub = {
                { '(Optional) Talk to Justinius at (J-6), as he will warn you not to go to the Sewer Entrance.' },
            } },
            { 'After the cutscene, head all the way to the lowest level of the safehold and check the Sewer Entrance at (I-7).' },
        },
    },
    ['Promathia Mission 2-3'] = {
        title        = 'Distant Beliefs',
        starting_npc = 'Phomiuna Aqueducts',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'You have volunteered to journey into the Phomiuna Aqueducts to defeat the minotaur. It appears that Nag\'molada has set off ahead of you.',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Reraise' },
            { 'Holy Water' },
            { 'Silent Oil and Prism Powder' },
            { 'Skeleton Key for the gate, or you may defeat Fomors for the Bronze Key' },
        },
    },
    ['Promathia Mission 2-4'] = {
        title        = 'An Eternal Melody',
        starting_npc = 'Walnut Door, Tavnazian Safehold - Top Floor (K-7)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'You must meet with the young Elvaan leader of the Tavnazian Patrol and have her return your amulet. You must also try to find a woman named Ulmia...',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to the (north) Walnut door at on the top floor of Tavnazian Safehold (K-7) for a cutscene. You will receive the Key Item Mysterious amulet.', sub = {
                { 'Make sure you go to the Walnut Door at (K-7), Parelbriaux on widescan stands outside. There\'s another (south) Walnut Door at (K-9) that will not work.' },
                { 'Speak with Justinius at (J-6) to learn of Ulmia\'s whereabouts. (Optional)' },
