        subtitle     = 'Seeker of the Light',
        repeatable   = 'No',
        description  = 'The celestial capital of Al\'Taieu truly exists. Though vastly altered during the ten thousand-year span of their seclusion, the ancients remain alive in the city. Nag\'molada heads for the palace, while you and your companions follow in his wake...',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the Crystalline Field at (H-11) in Al\'Taieu for a brief cutscene.', sub = {
                { 'Note that the Auroral Updraft at (H-12) (looks like a red pillar of light) will take you back to the Sealion\'s Den. Sueleen in the Sealion\'s Den will send you back to Al\'Taieu.' },
            } },
            { 'Examine the 3 Rubious Crystals to spawn trios of Ru\'aern NMs. Once they are defeated examine it again for a brief cutscene (a total of three cutscenes, one for each NM trio).', sub = {
                { 'You can use the Auroroal Updraft at E-8 and L-8 to place you back at the Auroral Updraft at H-12 to shorten your running distance when doing this mission.' },
                { 'Beware that Auroral Updraft teleports count as a zone and will erase buffs that don\'t persist through zoning and dismiss all trusts.' },
                { 'If other players are around and spawning the NMs, you may have to wait a while before being able to use the interaction point. The interaction points will say "There is nothing of interest here." If this is the case. It can take up to two minutes for it to be interactable again.' },
            } },
        },
    },
    ['Promathia Mission 8-2'] = {
        title        = 'A Fate Decided',
        starting_npc = 'Grand Palace of Hu\'Xzoi - Particle Gate - (H-8)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Nag\'molada has descended into the depths of the palace in search of the Chamber of Eventide. Join Prishe in her pursuit of the Kuluu diplomat.',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the eastern Particle Gate at (H-8) in the Grand Palace of Hu\'Xzoi for a cutscene that starts the Mission. Examine it again to enter.', sub = {
                { 'The northern Particle Gate next to the Home Point that sends you to the Garden of Ru\'Hmet is the wrong door.' },
            } },
            { 'The next section requires you to make your way through Hu\'Xzoi by escorting the Quasilumin orb-looking NPCs that you might have noticed in Al\'Taieu.', sub = {
                { 'The Map on this page has detailed directions (the blue line). There is an upper and lower level.' },
            } },
            { 'On your way through, you will run into Particle Gates that will not open. Find a nearby Cermet Alcove and check it to spawn a Quasilumin NPC (check the map on this page). It will then progress on a pre-determined route. You can stop and start the Quasilumin much like the NPCs found in the escort quests.' },
            { 'You have to protect the Quasilumin while it travels to its destination. Keep the Quasilumin alive and it will open Particle Gates along its way. It will eventually reach another Cermet Alcove and once there, check the NPC again and it will open the final gate.' },
            { 'On your way through it appears that the only enemies to pose a threat are the shapshifting Ix\'ghrah and Eo\'ghrah and the Eo\'zdei which wait at the end of the first and second escort position.', sub = {
                { 'Note: Quasilumins which are not on the move are used to get the map of the Grand Palace. If you talk to all ten, talking to one again will give you a map of this area.' },
            } },
        },
    },
    ['Promathia Mission 8-3'] = {
        title        = 'When Angels Fall',
        starting_npc = 'N/A',
        subtitle     = 'Warrior of the Crystal',
        repeatable   = 'No',
        description  = 'The Gate of the Gods--the portal leading to the highest level of the palace--has opened. While your companions scramble to reach the audience chamber, you must find which of the five towers will return you into the light...',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'First, check the Gate of the Gods (next to the Home Point) for a cutscene; otherwise, you will not have access to the upper floors (3-4).' },
        },
    },
    ['Promathia Mission 8-4'] = {
        title        = 'Dawn',
        starting_npc = 'N/A',
        subtitle     = 'Banisher of Emptiness',
        repeatable   = 'Yes',
        description  = 'Revelations of truth accompany the awakening of Promathia. The world and its people stand in the twilight of the apocalypse. Dawn Goddess Altana, grant us victory!',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into The Garden of Ru\'Hmet and pass through the Cermet Portal to get to the main Garden elevator.', sub = {
                { 'Use the Home Point you obtained earlier selecting, Home Point #1 of The Garden of Ru\'Hmet.' },
            } },
            { 'Choose to descend to zone into Empyreal Paradox.' },
            { 'Check the Transcendental Radiance for a cutscene and then check it again to enter the "Dawn" Battleground.' },
        },
    },
    ['Promathia Mission 8-5'] = {
        title        = 'The Last Verse',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'N/A',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {},
    },
}

quest_info['ahturhganmissions'] = {
    ['Aht Urhgan Mission 1'] = {
        title        = 'Land of Sacred Serpents',
        starting_npc = 'Naja Salaheem, Aht Urhgan Whitegate (I-10)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'A land of new adventures lies to the east of Mindartia. What splendors and terrors await the curious...?',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Complete the quest The Road to Aht Urhgan.' },
            { 'Head to Mhaura and take the boat to Aht Urhgan Whitegate.', sub = {
                { 'If you choose to pay 500,000 gil you do not need to take the boat to start the mission.' },
                { 'You no longer need to take the boat at all as the Unity Warp for Wajaom Woodlands (lv. 125) will take you to a good location to make a brief trek on foot.', sub = {
                    { 'The survival guide for Aydeewa Subterrane is just inside where it warps you.' },
                    { 'This becomes available as soon as you get the Boarding permit, along with the warp to Mount Zhayolm.' },
                } },
            } },
            { 'Approach Naja Salaheem at (I-10) to receive the Key Item Supplies package.', sub = {
                { 'She is located inside the building upstairs in the northeast corner of the grid square.' },
            } },
            { 'If this is your first time to Aht Urhgan Whitegate, be sure to pick up the Home Point crystal (to make future travel easier).', sub = {
                { 'There is a residential zone pretty close to where you exit the ferry dock. There is a Home Point crystal there.' },
            } },
        },
    },
    ['Aht Urhgan Mission 2'] = {
        title        = 'Immortal Sentries',
        starting_npc = 'Naja Salaheem, Aht Urhgan Whitegate (I-10)',
        subtitle     = 'Private Second Class',
        repeatable   = 'No',
        description  = 'Deliver a package to one of the Immortals found at the Staging Points and Naja will consider you for a mercenary contract.',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Take the Key Item Supplies package to any one of the Staging Points (with the exception of Nyzul Isle Staging Point and the Aht Urhgan Whitegate portal, Chamber of Passage), and talk to the NPC stationed there to complete delivery.', sub = {
                { 'Once you\'re at a staging point, be sure to do the delivery first to the nearby NPC, as interacting with the Runic Portal will teleport you directly back to Aht Urhgan Whitegate, and you will not be allowed to use the Chamber of Passage to return yet.' },
                { 'Visit the Staging Points page by clicking here and then click on one of the Runic Portal Names for detailed steps on reaching one of these locations. You will eventually want them all, so pick any of them.', sub = {
                    { 'Note for returners and new players: there\'s now another quick way to initially get to Nashmau (without taking the Ferry or navigating Alzadaal teleporters) via a Voidwatch Warp easily available to most players using the Caedarva Mire destination. (There\'s no easily unlockable Unity warp for that purpose!)', sub = {
                        { 'At H-10 in Aht Urhgan Whitegate there\'s a tunnel on the first floor where you\'ll find an Ironbound Gate, which leads outside to Wajaom Woodlands Postern where you can talk to Camille to Participate in Voidwatch Ops. You don\'t need to have done any other part of Voidwatch at all - you just need to be level 75 and be Rank 3 in your home nation.' },
                        { 'After receiving the Amber stratum abyssite, you can now use any Atmacite Refiner (in the Present) to warp to these locations initially to unlock other Home Points, Survival Guides, and Staging Points (hence the inclusion in this section!)... you\'ll just need 1000 cruor.' },
                        { 'If you don\'t have cruor from Abyssea, you can exchange 1 copper voucher from a Sparks NPC for the fee – and in Southern San d\'Oria or Bastok Markets this is right next to the Atmacite Refiner at those locations.' },
                        { 'And, from the Atmacite Refiner, do Request Teleportation –> Aht Urhgan. –> Caedarva Mire., and you\'ll be just outside the east entrance of Nashmau. Walk inside to grab the Survival Guide and the Home Point and continue your journey.' },
                        { 'From here, the Azouph Isle Staging Point is very close with a mount. You can use either the east or north exit from Nashmau to get there.' },
                    } },
                } },
            } },
            { 'After you\'ve delivered the Key Item Supplies package to the blue-clad Immortal NPC nearby, use the Runic Portal at the Staging Point to return to Aht Urhgan Whitegate.' },
            { 'Speak to Naja Salaheem.' },
        },
    },
    ['Aht Urhgan Mission 3'] = {
        title        = 'President Salaheem',
        starting_npc = 'Naja Salaheem, Aht Urhgan Whitegate - (I-10)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'You have become an employee of Salaheem\'s Sentinels. Becoming a mercenary is not quite what you expected...',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'You must zone out and return to get the cutscenes.', sub = {
                { 'There is an exit to Wajaom Woodlands west of the office under the stairs.' },
            } },
            { 'Speak to Rytaal (K-10) for an explanation of Assault. This also unlocks access to it.', sub = {
                { 'Rytaal is located in the Commissions Agency through the door in (K-9).' },
            } },
            { 'Speak to Naja Salaheem twice for two cutscenes to finish this mission and immediately begin the next.' },
