        starting_npc = 'Aht Urhgan Whitegate - (K-11)',
        subtitle     = 'Karababa\'s Tour Guide',
        repeatable   = 'No',
        description  = 'You have been asked to guide Lady Karababa to the Olduum ruins found in the tunnels of the Aydeewa Subterrane. How will Naja react to your freelancing? And what are Aphmau and friends planning...?',
        series       = 'Treasures of Aht Urhgan',
