    ['Aht Urhgan Mission 21'] = {
        title        = 'Finders Keepers',
        starting_npc = 'Aydeewa Subterrane',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'After snatching the Olduum artifact, Lady Karababa has left for Salaheem\'s Sentinels. What business could she possibly have with a mercenary company?',
