    ['Aht Urhgan Mission 22'] = {
        title        = 'Shield of Diplomacy',
        starting_npc = 'Naja Salaheem, Aht Urhgan Whitegate - (I-10)',
        subtitle     = 'Karababa\'s Bodyguard',
        repeatable   = 'No',
        description  = 'You are once again in the employ of Lady Karababa. This time, your role is to protect the ambassador within the ominous Navukgo Execution Chamber. Will you be able to redeem your reputation with President Naja...?',
        series       = 'Treasures of Aht Urhgan',
