        starting_npc = 'Navukgo Execution Chamber',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'You have successfully protected Lady Karababa from harm and earned high praise. Perhaps you can expect a bonus from the president when you return to Salaheem\'s Sentinels...?',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
