    ['Aht Urhgan Mission 24'] = {
        title        = 'Foiled Ambition',
        starting_npc = 'Naja Salaheem, Aht Urhgan Whitegate - (I-10)',
        subtitle     = 'Karababa\'s Secret Agent',
