    ['Aht Urhgan Mission 30'] = {
        title        = 'Prevalence of Pirates',
        starting_npc = 'Jade Sepulcher',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Aphmau and her puppets have been taken by the mysterious Luzaf. Track down the corsair and his captives, and repay Rishfee\'s noble sacrifice.',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into Arrapago Reef for a cutscene first.', sub = {
                { 'Best route as of the August 2025 Version Update: Purchase an Arrapago Ring with 100 Imperial standing accolades from Asrahd at Aht Urhgan Whitegate (I-8). This will put you very close to the next step of the mission as well.' },
                { 'Option 1, use the Survival Guide in Caedarva Mire and head North / Northwest before turning South to the Arrapago Reef (4) entrance.' },
                { 'Option 2, use Dvucca Isle Staging Point and use the Caedarva Mire map #2 to zone into the Arrapago Reef (3) off-map/hidden G-9 entrance.' },
                { 'Option 3, use the Ilrusi Atoll Staging Point to receive the initial cutscene, but may be further from the Cutter for the remaining mission requirements.' },
                { 'Option 4, go to the Survival Guide in Arrapago Reef directly for the cutscene, but it won\'t put you near the Cutter for the next part of the mission.' },
            } },
            { 'After the cutscene from zoning into Arrapago Reef, approach the Cutter to receive another cutscene that finishes this mission.', sub = {
                { 'If you entered from Caedarva Mire at (G-9), you are already at the correct entrance. Just walk north to find the boat. L70 Shades are near the boat area.' },
            } },
            { 'DO NOT WARP OUT -- The next mission is easily accessible on foot from here. Head south from the Cutter and into Caedarva Mire.', sub = {
                { 'Note that if you already have Dvucca Isle Staging Point unlocked and the Imperial Standing to pay for a portal use, then warping and using the staging point is a perfectly reasonable (and faster) way to get to the next mission location. But if you don\'t have it unlocked, then by all means, don\'t warp so you can walk/mount your way to it.' },
            } },
        },
    },
    ['Aht Urhgan Mission 31'] = {
