        title        = 'Westerly Winds',
        starting_npc = 'Aht Urhgan Whitegate - (K-11)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'You have been assigned the task of infiltrating the inner political circle of the Empire as an agent of the allied forces. Report to Raillefal.',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to the Shararat Teahouse (K-11) for a cutscene. You will obtain Key ItemRaillefal\'s note', sub = {
                { 'The choices have no effect on the mission. Choose whatever answer you like best.' },
                { 'You\'ll be given a Imperial Silver Piece at the conclusion of the cutscene.' },
            } },
            { 'Speak to Naja Salaheem (I-10) for a cutscene.', sub = {
                { 'You\'ll be given the second Imperial Silver Piece at the conclusion of the cutscene.' },
                { 'If you are asked for an Imp Wing, it is due to the Promotion: Private First Class quest. Simply trade one to continue.' },
            } },
        },
    },
    ['Aht Urhgan Mission 8'] = {
        title        = 'A Mercenary Life',
        starting_npc = 'Naja Salaheem, Aht Urhgan Whitegate - (I-10)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'President Naja is all fired up and eager to see you complete as many missions as you can...',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone, and return to Salaheem\'s Sentinels (I-10) for a cutscene.' },
        },
    },
    ['Aht Urhgan Mission 9'] = {
        title        = 'Undersea Scouting',
        starting_npc = 'Naja Salaheem, Aht Urhgan Whitegate - (I-10)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'You have been requested to enter the Alzadaal Undersea Ruins from Bhaflau Thickets and patrol the interior.',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Trade one Imperial Silver Piece to Kamih Mapokhalam (F-6) located in Bhaflau Thickets on Map 1.', sub = {
                { '(Optional) Trade Kamih Mapokhalam 3 Imperial Mythril Pieces for a map of the Alzadaal Undersea Ruins.', sub = {
                    { 'This map is now purchasable via the Magical Map vendors.' },
                } },
            } },
            { 'Alternative Option, if you\'ve unlocked quick transportation to Nashmau, you can head out of the east entrance into Caedarva Mire and do a short trek, towards the Imperial guard Tyamah at (J-10) of Caedarva Mire. Trade him a Imperial Silver Piece to proceed.', sub = {
                { 'Note: If you enter through the Caedarva Mire you will be to the opposite end of where the cutscene starts and you won\'t be able to advance the quest until you head towards the Bhaflau Thickets entrance. This also means being unable to receive the Key ItemAstral compass until you get there so if you die you\'re going to have to pay the guard another Imperial Silver Piece to come back.' },
            } },
        },
    },
}

quest_info['wotgmissions'] = {
    ['A Hawk in Repose'] = {
        title        = 'A Hawk in Repose',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Word has it that an unknown individual is often seen paying tribute to Sir Ragelise\'s grave out in Batallia Downs. Could it be that this man possesses the information you seek?',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the Weathered Gravestone in Batallia Downs at (I-10) - up the hill - for a cutscene.', sub = {
                { 'Fastest route is using The Eldieme Necropolis Survival Guide, and walking outside to Batallia Downs.' },
                { 'If you get a message "You see the weathered gravestone." then you did not complete Another World and another quest or mission may have taken priority over it.' },
            } },
            { 'Trade a Lilac to the Weathered Gravestone.' },
        },
    },
    ['A Nation on the Brink'] = {
        title        = 'A Nation on the Brink',
        starting_npc = 'Batallia Downs (S)',
        subtitle     = 'Battle of Jeuno Veteran',
        repeatable   = 'No',
        description  = 'Despite Lilisette\'s repeated protests and the imminent arrival of reinforcements from the three nations, the surrender ceremony is set to take place in the depths of Jeuno\'s underground. Will this be the end of the four-nation',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the Underpass Hatch in Batallia Downs (S) at (J-9)/(K-9) for a cutscene. The Hatch is on the rampart inside of a tower.', sub = {
                { 'If you have progressed a bit in Voidwatch, you can use the Atmacite Refiner in Sauromugue Champaign (S) from the last mission\'s cutscene to get here swiftly. Otherwise, the Campaign Arbiter warp from your allied nation will get you somewhat close.' },
            } },
        },
    },
    ['A Sanguinary Prelude'] = {
        title        = 'A Sanguinary Prelude',
        starting_npc = 'Beaucedine Glacier (S)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'You have been granted permission to accompany the Madder Falcons and the Red Roses to the Northlands Take advantage of this opportunity to unearth clues that may lead to the recovery of Lilisette and Portia.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into Beaucedine Glacier (S) for a cutscene.' },
        },
    },
    ['A Spoonful of Sugar'] = {
        title        = 'A Spoonful of Sugar',
        starting_npc = 'Southern San d\'Oria (S)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Using the key ingredient you and Lilisette have laboriously acquired, Amaura was finally able to concoct the same medicine that Sir Ragelise used all those years ago. Deliver it to the ailing knight at the Chateau d\'Oraguille without delay.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to the Victory Gate at I-7 in Southern San d\'Oria (S) and speak to Raustigne.' },
        },
    },
    ['A Timeswept Butterfly'] = {
        title        = 'A Timeswept Butterfly',
        starting_npc = 'East Ronfaure (S)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Still on the trail of the elusive Cait Sith, the unyielding Lilisette continues to claim she knows what the future holds in store. Amidst her crazed rantings, she has requested that you accompany her to La Vaule.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into La Vaule (S).', sub = {
                { 'Next mission automatically begins at end of cutscene.' },
            } },
        },
    },
    ['A Token of Troth'] = {
        title        = 'A Token of Troth',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You have received a cordial invitation to attend the wedding of Sir Ragelise and Portia. Make your way to the Temple of the Goddess in Upper Jeuno, where the ceremony is to be held.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Unequip your weapon and examine the Bulwark Gate in Sauromugue Champaign (S) at (E-6) for a cutscene.' },
            { 'Examine the Bulwark Gate again for another cutscene.' },
        },
    },
    ['Adieu, Lilisette'] = {
        title        = 'Adieu, Lilisette',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Has the world made its choice? Is this the end of the future you have fought tooth and nail to preserve?',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Bastok [S]: The Truth Lies Hid, Bonds of Mythril.' },
            { 'San d\'Oria [S]: Chasing Shadows, Face of the Future.' },
            { 'Windurst [S]: Manifest Destiny, At Journey\'s End.' },
        },
    },
    ['Affairs of State'] = {
        title        = 'Affairs of the State',
        starting_npc = 'Southern San d\'Oria (S)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Jeunoan Ambassador, Nag\'molada, has delivered unsettling news of the duchy\'s plan to surrender to the besieging beastman force. Accompany Count Borel and Lilisette in their mission to entreat the aid of the other two nations.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'You must travel to both Bastok Markets (S) and Windurst Waters (S) to speak with their officials. (May be done in either order.) The Survival Guide warp is closest in Bastok, while the Home Point is very slightly closer in Windurst.', sub = {
                { 'In Bastok Markets (S), speak to Radford near the Metalworks at (H-6).' },
                { 'In Windurst Waters (S), speak to Velda-Galda in Windurst Waters (S) (North) at (K-9), near the zoneline to Windurst Walls.' },
            } },
            { 'Once you have spoken to both characters, you will receive Key ItemCount Borel\'s letter.' },
        },
    },
    ['Another World'] = {
        title        = 'Another World',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: In order to gain an advantage in the looming battle, Lilisette has proposed that you speak with someone who was directly involved in the campaign.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter Southern San d\'Oria from East Ronfaure (in the present) for a cutscene.' },
            { 'Speak to Halver in Chateau d\'Oraguille (I-9).', sub = {
                { 'You must have access to Chateau d\'Oraguille to get past Bacherume in order to see Halver.' },
                { 'Note that The Voracious Resurgence Mission 3-1 will take priority over this mission. If Halver has you speak with Rahal then you will need to complete The Voracious Resurgence Mission 3-1 before continuing.' },
                { 'The Voracious Resurgence mission Epiloque Quests will also take priority over this mission. You must zone out and back into Chateau d\'Oraguille after the cutscene to continue with Another World.' },
            } },
        },
    },
    ['Back to the Beginning'] = {
        title        = 'Back to the Beginning',
        starting_npc = 'N/A',
        subtitle     = 'Cait Sith\'s Assistant',
        repeatable   = 'No',
        description  = 'Hideous statues. Monstrous beasts. The otherworld that lies in between. Could this war-torn land you have been thrust to truly be the outskirts of Jeuno...?',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'In the last mission you had been asked to go to a nearby Allied fortress, one of the three dungeons near Jeuno: Garlaige Citadel (S), Crawlers\' Nest (S), or The Eldieme Necropolis (S). It is there you can pick up a recommendation letter that is required to join the Allied Campaign.' },
            { 'There are three potential recommendation letters that may all be obtained, but you may only be allied to one nation at a time.' },
            { 'Your choice of nation allegiance has no impact on the mission progression.', sub = {
                { 'After you\'ve joined a nation, you can do any of the three nation\'s quests to progress the missions or even do all three in parallel. Joining a nation doesn\'t require you to do that nation\'s quests and the contents of the quests don\'t change based on your allegiance.' },
                { 'The nation you join will charge less for their Allied Notes items. Due to their new alliance, Allied Notes can be redeemed at any vendor in any nation but buying from other nations has a 50% markup.' },
                { 'Your allied nation determines the destination of the Retrace / Instant Retrace spell.' },
                { 'It doesn\'t matter for anything relevant.' },
            } },
        },
    },
    ['Betrayal at Beaucedine'] = {
        title        = 'Betrayal at Beaucedine',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'A cait is on the move! What could the suspected traitor\'s intended destination be? There is only one way to find out!',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the Regal Pawprints (H-9) Beaucedine Glacier (S) for a cutscene. The target is behind the tree near the bottom of the ramp from the Campaign Arbiter.' },
            { 'Examining the Regal Pawprints a second time will spawn five NM\'s: Count Halphas and 4 Dark Demons.', sub = {
                { 'Only Count Halphas needs to be defeated to continue. Once he is dead the Dark Demons will vanish.' },
                { 'The Dark Demons can be slept with sleepga, however Count Halphas is immune to sleep.' },
            } },
            { 'Once defeated, examine the Regal Pawprints again for a cutscene.' },
        },
    },
    ['Borne by the Wind'] = {
        title        = 'Borne by the Wind',
        starting_npc = 'Sauromugue Champaign (S)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Bastok and Windurst have both pledged reinforcements for Jeuno. Make all haste and deliver Count Borel\'s letter to the duchy before the unthinkable comes to pass.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'In Sauromugue Champaign (S), examine the Bulwark Gate at (E-6)/(F-6) for a cutscene to receive the Key ItemUnderpass hatch key and to complete the mission.', sub = {
                { 'The Campaign Arbiter warp from an allied nation will teleport you to a fairly close location. Mount up and ride north and west to reach the location.' },
                { 'Taking the Survival Guide warp to Rolanberry Fields in the present time and entering the Voidwatch passage to the past (which is right next to survival guide) will also bring you very close to the gate needed.' },
                { 'You are given a dialogue choice during the cutscene. The second option gives a small optional bit of text but you must choose the first to progress.' },
                { 'Depending on your progress in the Voidwatch quest line, you may get a brief cutscene with the Jeunoan leader. Examine the Bulwark Gate again to continue with the Wings of the Goddess mission.' },
            } },
        },
    },
    ['By the Fading Light'] = {
        title        = 'By the Fading Light',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'The brighter future continues to fade even as the Crystal War rages on, the warring factions oblivious to the greater scheme of things. With a path ahead unapparent, Cait Sith proposes that you head to Xarcabard to observe how the struggle unfolds.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the Red Rally Point in Xarcabard (S) at (F-8) for a cutscene.' },
        },
    },
    ['Cait in the Woods'] = {
        title        = 'Cait in the Woods',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: According to Lilisette, Cait Sith has business in Ronfaure.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the Blank Target at East Ronfaure (S) (H-7) (NW corner of grid) for a cutscene and Key Item Ronfaure dawndrop.' },
        },
    },
    ['Cait Sith (Mission)'] = {
        title        = 'Cait Sith',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Beyond the cavernous maws lies the age of the Crystal War. You have agreed to aid Cait Sith in her attempt to lessen the pain inflicted in this time of strife.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'This mission is triggered by clicking any of the three Cavernous Maws outside Jeuno in the past (or any maws in the present that you have already activated by exiting through the past) after Back to the Beginning, and requires you to continue the national storylines with the following quests:', sub = {
                { 'Bastok - Light in the Darkness, Burden of Suspicion' },
                { 'San d\'Oria - Boy and the Beast, Wrath of the Griffon' },
                { 'Windurst - Knot Quite There, A Manifest Problem' },
            } },
        },
    },
    ['Cavernous Maws (Mission)'] = {
        title        = 'Cavernous Maws',
        starting_npc = 'Cavernous Maw in Batallia Downs, Rolanberry Fields, or Sauromugue Champaign.',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Are the hideous statues scattered across Quon and Mindartia the portals to a new chapter of adventure...?',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Visit any Cavernous Maw in the following locations:' },
        },
    },
    ['Crossroads of Time'] = {
        title        = 'Crossroads of Time',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Amidst scenes of horrendous devastation, Archduke Kam\'lanaut makes an inspired victory declaration before all. Meanwhile, shrouded figures intently observe the unfolding of events from a vantage point...',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'This mission is triggered automatically after completion of A Nation on the Brink, and is required to continue the national storylines with the following quests:', sub = {
                { 'Bastok - Quelling the Storm, Honor Under Fire' },
                { 'San d\'Oria - The Price of Valor, Bonds That Never Die' },
                { 'Windurst - The Long March North, The Forbidden Path' },
            } },
        },
    },
    ['Dancers in Distress'] = {
        title        = 'Dancers in Distress',
        starting_npc = 'Southern San d\'Oria (S)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Alexei Mayakov is displeased with his two dancers, Lilisette and Portia, who are suspected to have once again skipped rehearsal to attend Sir Ragelise at the Chateau d\'Oraguille.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to Raustigne in Southern San d\'Oria (S) at (I-7/8) for a cutscene.' },
            { 'Examine the Elegant Footprints in Jugner Forest (S) (I-6) for a cutscene. It is next to the tree stump near the (H-6)/(I-6) center border, just across the makeshift bridge if coming from East Ronfaure (S).', sub = {
                { 'The fastest way to the Elegant Footprints is the Survival Guide in East Ronfaure (S).' },
            } },
        },
    },
    ['Darkness Descends'] = {
        title        = 'Darkness Descends',
        starting_npc = 'N/A',
        subtitle     = 'Wanderer of Time',
        repeatable   = 'No',
        description  = 'Mission Orders: Your pursuit of Sir Ragelise and Portia has brought you back to the enemy stronghold. Seek them out before the unthinkable comes to pass!',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Continue through Castle Zvahl Baileys (S) and Castle Zvahl Keep (S), and zone into the Throne Room (S) for a cutscene.' },
            { 'Click on the Throne Room door to begin the BC Darkness Descends.', sub = {
                { 'In this BC you will fight Aquila and Haudrale with the aid of Lilisette.' },
                { 'Aquila casts black magic spells such as tier 4 elemental magic and tier 3 elemental magic, Sleepga II, and Dispelga.', sub = {
                    { 'He also has Enspells and has a weapon skill called Altair Bullet that does conal damage with additional effect paralyze, and a large knockback.' },
                } },
                { 'Haudrale casts black magic spells and has a weapon skill with a knock back effect.' },
                { 'Lilisette will automatically begin the fight after 3 minutes.' },
                { 'Should Lilisette fall in battle, the BC will end.' },
            } },
        },
    },
    ['Daughter of a Knight'] = {
        title        = 'Daughter of a Knight',
        starting_npc = 'Jugner Forest (S)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Could the mystery object the Cait Siths were discussing be related in any way to the medicine Sir Ragelise used to take? The answer lies with Amaura, a resident of present-day Southern San d\'Oria.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to Amaura in Southern San d\'Oria HP #4 at (G-6). She will request a Cernunnos Bulb.', sub = {
                { '(Optional) Speaking to Amaura again will have her restate some recycled dialogue about Key ItemCernunnos resin.' },
                { 'The fastest route to her would be to take Home Point #4 for Southern San d\'Oria.' },
                { 'If you did not farm one after Dancers in Distress as recommended, kill Wandering Saplings in Jugner Forest (S) for a Cernunnos Bulb.' },
            } },
            { 'Trade the Cernunnos Bulb to Amaura and watch the cutscene.' },
            { 'Trade the Cernunnos Bulb to the Humus-rich Earth in Jugner Forest (S) at (E-6) to plant it.', sub = {
                { 'The fastest way to get here is using the Campaign Arbiter warp and riding a mount Northwest.' },
                { 'Be careful of aggro from the Lobisons in the area.' },
            } },
            { 'Now time travel to Jugner Forest (Present Day) and examine the Humus-rich Earth at the same spot for a cutscene.', sub = {
                { 'The Outpost warp for Norvallen will take you fairly close and the Voidwatch warp is a little farther.' },
            } },
            { 'Examine the Humus-rich Earth again to spawn the mob Cernunnos.', sub = {
                { 'Cernunnos is a Treant-type mob that can cast spells such as Protect IV, Shell IV, Stone IV, Stonega III.' },
            } },
            { 'Examine the Humus-rich Earth again after defeating Cernunnos to obtain the Key ItemCernunnos resin.' },
            { 'Return to Amaura with the key item for a cutscene.' },
            { 'Speak to Amaura after waiting until the next game day and zoning to obtain the Key Item Bottle of treant tonic and complete the mission.', sub = {
                { '(Optional) She\'ll suggest you do some household chores for her if you speak with her before then. If you speak to her after the day has changed but without zoning, she\'ll tell you she\'s busy brewing a powerful potion.' },
                { 'You may be required to talk to her multiple times if you are currently doing the To Cure a Cough quest. Key ItemCough medicine is not the required key item.' },
            } },
        },
    },
    ['Distorter of Time'] = {
        title        = 'Distorter of Time',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'What shocking truth lies behind Cait Sith Ceithir\'s bold declaration that Atomos will choose the future? The answer must wait! Use the combined power of the surviving Cait Siths to stop the rampant Atomos!',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'You have 30 minutes to complete this battle.' },
            { 'If you fail this mission, you can get another Key Item Umbra bug from the Regal Pawprint under the tree root at (H-10), one of the locations you previously spoke to Cait Sith Naoi. To get back to the battle from this location, you\'ll want to ascend two ramps in the zone, then head northwest to the knob of rock in the ground you were at before in (H-7), near which is the Regal Pawprint. You are limited to 1 Key Item per game day.' },
        },
    },
    ['Dungeons and Dancers'] = {
        title        = 'Dungeons and Dancers',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Lilisette and Portia are being detained in a subterranean location somewhere beneath the Beaucedine Glacier Your rescue effort begins with a search for the entrance underground.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the Regal Pawprints Beaucedine Glacier (S) (G-9, east side, high ground. Do NOT go to the tower.) for a cutscene. (It\'s labelled in White on the map on this page.)', sub = {
                { 'This is south-west and on the same level as the Campaign warp (Moana, C.A.) and the tower; do not head down the ramp.' },
            } },
            { 'Examine the Regal Pawprints again to enter the battlefield at Everbloom Hollow.' },
            { 'You have 30 minutes to complete the mission.', sub = {
                { 'If you fail you can get another Key Item Aroma bug at Naoi\'s Regal Pawprints at (H-10).' },
                { 'There\'s no timer to indicate how much time you have left, but you\'ll get warnings in the log at the 10, 5, and 1 minute marks.' },
            } },
        },
    },
    ['Edge of Existence'] = {
        title        = 'Edge of Existence',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'The future heavily favors the world of strife, and nothing short of a miracle will help to turn the tide. Slim a chance though it may be, reviving Lilisette is the only avenue that remains. First you must seek the counsel of Atomos, the Devourer of Memories.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine one of the Cavernous Maws below for a cutscene:', sub = {
                { 'Sauromugue Champaign (J-10) - Taking the Survival Guide to Sauromugue Champaign puts you right next to this Cavernous Maw.' },
                { 'Batallia Downs (H-5) - Taking the Survival Guide to Batallia Downs puts you right next to this Cavernous Maw.' },
                { 'Rolanberry Fields (H-6) - Taking the Survival Guide to Rolanberry Fields puts you right next to this Cavernous Maw.' },
            } },
        },
    },
    ['Fall of the Hawk'] = {
        title        = 'Fall of the Hawk',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Cast out of both Kingdom and Alliance in disgrace, Sir Ragelise has disappeared with Portia in tow...but not before making known his trepidation at the ominous vortex that appeared above Castle Zvahl.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter Castle Zvahl Baileys (S) to see a cutscene.', sub = {
                { 'Fastest way here is the Castle Zvahl Baileys (S) Survival Guide warp.' },
            } },
        },
    },
    ['Fate in Haze'] = {
        title        = 'Fate in Haze',
        starting_npc = 'N/A',
