    ['Maiden of the Dusk'] = {
        title        = 'Maiden of the Dusk',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The hour of reckoning is nigh. Seek Lady Lilith at her throne within the Walk of Echoes, where the decisive battle between realities will be waged.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the Veridical Conflux in Grauberg (S) at (F-5) for a cutscene. You will be transported to Walk of Echoes.', sub = {
                { 'If Walk of Echoes was the last dawndrop you did from the last mission, you must exit and examine the Veridical Conflux for the cutscene.' },
            } },
            { 'Examine the Ornate Door north of the Verdical Conflux in the Walk of Echoes for a cutscene; examine it again to enter the BC Maiden of the Dusk.' },
            { 'Your opponent in this BC is Lilith; she casts AoE enfeebling spells, and has two forms.', sub = {
                { 'In the first form:', sub = {
                    { 'Her regular melee attacks are AoE and cause knockback, and she has a weaponskill with the additional effect of Dispel.' },
                    { 'Aside from AoE enfeebling spells, she casts Comet, and at low HP, Meteor.' },
                    { 'She can use Trance multiple times. While under trance, she can use a gaze weaponskill called Fatal Attraction which will charm; this can be avoided by turning away from her.' },
                    { 'After defeating the first form, there will be a cutscene and you will return to the entry point of the battlefield to rest and buff again if needed.' },
                } },
                { 'In her second form:', sub = {
                    { 'Her weaponskills are Dark Flare, Dark Burst, Dark Quake, Dark Freeze, Dark Tornado; they are conal attacks that do sizable amounts of damage.' },
                    { 'She also has a weaponskill called Dark Moon that causes Weakness for a short period of time.' },
                    { 'She summons Elemental Gyves which can be nuked down fairly easily. Avoid standing in them when possible.', sub = {
                        { 'Red gives Burn and Attack Down.' },
                        { 'Cyan gives Frost and Magic Attack Down.' },
                        { 'Yellow gives Rasp and Defense Down.' },
                        { 'Green gives Choke and Evasion Down.' },
                        { 'Blue gives Drown and Magic Defense Down.' },
                        { 'Purple gives Shock and Accuracy Down.' },
                        { 'White gives Dia and Disease.' },
                        { 'Black gives Bio and a 5 second Doom effect. Two appear after Dark Moon. Be especially careful of this one.' },
                    } },
                    { 'Her two hour is Dark Sun; it is AoE Death in approximately a 15 yalm radiusVerification Needed. She will say a line before she uses it, so be prepared to run when she is under 50%.' },
                } },
                { 'Both phases are rather trivial at ilvl 119, but advise caution on Fatal Attraction.' },
            } },
            { 'The mission will be complete after a 10 minute cutscene with Lady Lilith, Lilisette and Cait Sith.', sub = {
                { 'After this cutscene, you may buy the HTMB KI Maiden phantom gem for 10 Merit Points.' },
            } },
            { 'If you are defeated, wait for the next game day and check the Grauberg (S) Veridical Conflux to get another Key ItemPrimal glow.' },
        },
    },
