    ['When Wills Collide'] = {
        title        = 'When Wills Collide',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: To regain a foothold in the struggle and ensure Lilisette\'s rebirth, you must confront whatever darkness lies in wait at the Walk of Echoes.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter Walk of Echoes from the Veridical Conflux in Grauberg (S) at (F-5).' },
            { 'Examine the Ornate Door north of the Veridical Conflux in the Walk of Echoes for a cutscene, examine it again to enter a BC.' },
            { 'Your opponents in this BC are the Spitewardens.', sub = {
                { 'The first Spitewarden is a MNK who uses a staff. Can use Hundred Fists, has a special weaponskill called Forlorn Strike.' },
                { 'The second Spitewarden is a PLD. Can use Invincible, casts Banish and Banishga spells, and shares hate with the third Spitewarden.' },
                { 'The third Spitewarden is a DNC. Can use trance, and is capable of curing and removing debuffs (such as gravity), and will occasionally cure the second Spitewarden. Also has a special gaze attack with a Doom effect, it can be avoided by turning away.' },
                { 'The fourth Spitewarden does not seem to have a job, but will use a weapon that matches the person who starts the BC, and has access to all weaponskills for that weapon, also has an ability at low HP called Essence Jack that will lower your statuses, inflict terror, and give a damage boost.', sub = {
                    { 'A good strategy is to use gravity to kite the Spitewardens while DDs deal with them one at a time. If you are going to kite, it is a good idea to deal with the third Spitewarden first, since DNC is capable of dispelling Gravity, although the second Spitewarden will assist.' },
                    { 'The BC is won when all four Spitewardens are defeated, should you be defeated, you will have to obtain another Punch Bug to try again.' },
                } },
            } },
            { 'This fight is easily won at iLevel and you may not even need Trusts to help.' },
        },
    },
    ['Where It All Began'] = {
        title        = 'Where It All Began',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: With the encroachment between realities ended, certain disaster has been averted. How do the others fare in the wake of balance restored? Perhaps a visit to the Lion Springs Tavern in Southern San d\'Oria is in order.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the door to Lion Springs Tavern in Southern San d\'Oria (S) (K-6) for a cutscene and the Key Item Wedding invitation.' },
