    ['While the Cat is Away'] = {
        title        = 'While the Cat is Away',
        starting_npc = 'Southern San d\'Oria (S)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Summoned by his troops, Sir Ragelise, leader of the Knights of the Ironcrest Hawk, has headed for the castle with the ever-flamboyant Alexei Mayakov. In an intriguing aside, a most curious presence watches their every move, concealed in the nearby shadows...',
