        walkthrough  = {
            { 'Head to Tenshodo in Lower Jeuno and examine the Treasure Chest for your reward.', sub = {
                { 'The easiest way to repeat the fight to change your augmented item is to first toss it, then purchase the Key Item Mega Bonanza Kupon from Squintrox Dryeyes in Port Jeuno for 2,000 gil and 20 Beastmen Seals.', sub = {
                    { 'This will allow you to quickly re-enter the BCNM in the Throne Room. Even with a Key Item Mega Bonanza Kupon, you will not be able to re-enter the BCNM if you still have the Angel skin key. You must first exchange it with the red chest in the Lower Jeuno Tenshodo.' },
                } },
                { 'There is a Japanese Midnight wait on immediately repeating the fight. Otherwise you will receive the message: "Mega Bonanza Kupon has no effect. You cannot enter battlefield at present. Please wait a little longer".' },
            } },
            { 'After the fight, you will immediately receive your key rewards.' },
        },
    },
    ['Kupo Mission 2'] = {
        title        = 'Drenched! It Began with a Raindrop',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'With the ramshackle roof of your Mog House unable to withstand the elements, your moogle cohort entreats you to find three materials required for some much-needed renovations: an Orcish armor plate, a Quadav backscale, and a block of Yagudo caulk.',
        series       = 'A Kupo d\'Etat',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Trade the following three items to your Moogle:', sub = {
                { 'Orc. Armor Plate dropped from Orcs in Yughott Grotto.' },
                { 'Quadav Backscale dropped from Quadavs from Palborough Mines.' },
                { 'Yagudo Caulk dropped from Yagudos in Giddeus.' },
            } },
        },
    },
    ['Kupo Mission 3'] = {
        title        = 'Hasten! In a Jam in Jeuno?',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Word has it that the Rent-a-Room in Jeuno is also showing signs of spoilage. Unable to resist your moogle companion\'s earnest plea, you reluctantly agree to investigate the premises...',
        series       = 'A Kupo d\'Etat',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the Inconspicuous Door in Upper Jeuno (H-8) (across from Durable Shields) for a cutscene.' },
        },
    },
    ['Kupo Mission 4'] = {
        title        = 'Welcome! To My Decrepit Domicile',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'Yes',
        description  = 'Rotting roofboards, crumbling walls... Yes, this Rent-a-Room is a mess. Your moogle associate has the handyman skills; all he needs are a few essential items to make the requisite repairs.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Go to Gusgen Mines or Palborough Mines or Ifrit\'s Cauldron and mine for the Key Item sturdy metal strip.' },
            { 'Go to East Ronfaure or Jugner Forest or Ghelsba Outpost and log for the Key Item piece of rugged tree bark.' },
            { 'Go to Giddeus or West Sarutabaruta and harvest the Key Item savory lamb roast.' },
            { 'After you have all three Key Item key items, examine the Inconspicuous Door in Upper Jeuno (at (H-8), across from Durable Shields) three times for three cutscenes.', sub = {
                { 'You do not need to collect all three before the cutscenes. Each item triggers one cutscene. This method is just more efficient.' },
            } },
        },
    },
    ['Kupo Mission 5'] = {
        title        = 'Curses! A Horrifically Harrowing Hex',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'When a missive from Boss Kupeliaure unexpectedly unleashes a calamitous curse, our hard-luck heroes seek out the aid of the esteemed yet eccentric exorcist Professor Shantotto.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to Shantotto in Windurst Walls (K-7) for a cutscene. She will ask you for a Key Item Ripe starfruit. This automatically starts the next mission.' },
        },
    },
    ['Kupo Mission 6'] = {
        title        = 'An Errand! The Professor\'s Price',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'The Professor consents to lend you her aid, but as expected, there\'s a price to be paid. Within a Cardian in the Outer Horutoto Ruins lies the reagent she does seek; return it to her, that you might avert a fate most bleak!',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter the Outer Horutoto Ruins from West Sarutabaruta (F-11).' },
            { 'Kill Cardians in the area to get one (or more) of the following Key Items:', sub = {
                { 'Key Item Orb of Swords' },
                { 'Key Item Orb of Cups' },
                { 'Key Item Orb of Batons' },
                { 'Key Item Orb of Coins' },
            } },
            { 'After receiving the Orbs you want, zone into Outer Horutoto Ruins from East Sarutabaruta (H-3).' },
            { 'Examine the ??? on top of the platform at (H-6) (it\'ll be right in front of you when you enter the zone) to begin a battlefield.', sub = {
                { 'Trust Magic can not be used in this battlefield.' },
                { 'Up to 15 Custom Cardians will spawn and begin to attack.' },
                { 'The player starting the battle will lose all of their possessed Orbs.' },
                { 'The number and types of Orb key items in the possession of the player starting the battle will affect the number of Custom Cardians that spawn and damage type immunity:', sub = {
                    { 'Key Item Orb of Swords removes slashing damage immunity.' },
                    { 'Key Item Orb of Batons removes blunt damage immunity' },
                    { 'Key Item Orb of Cups removes piercing damage immunity.' },
                    { 'Key Item Orb of Coins removes magic damage immunity.' },
                    { 'With 1 or 2 Orbs, 15 Cardians will appear.' },
                    { 'With 3 Orbs, 10 Cardians will appear.' },
                    { 'With all 4 Orbs, 5 Cardians will appear.' },
                } },
                { 'Anyone else in the party with different Orbs, will lose them and not have their bonus granted.', sub = {
                    { 'You receive 500 experience points, a Key Item Ripe starfruit, and a Key Item Peach coral key upon winning.' },
                } },
            } },
            { 'Return to Shantotto. She will require you give her 5000 gil.' },
            { 'Return to the Inconspicuous Door in Upper Jeuno (H-8) (across from Durable Shields) for a cutscene.' },
        },
    },
    ['Kupo Mission 7'] = {
        title        = 'Shock! Arrant Abuse of Authority',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'When the linguistically challenged toady Toto Kupeliaure demands a ridiculous sum in unpaid rent, your moogle comrade chooses to make the ultimate sacrifice. Venture forth and unearth the moggy bank that contains his hard-earned wedding funds!',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'For this mission, you will be asked to go Chocobo Digging in a random zone.' },
            { 'Head to the zone mentioned by your moogle and attempt to dig up its treasure, a Key Item Moldy, worm-eaten chest.', sub = {
                { 'You will need Gysahl Greens to make your chocobo dig.' },
                { 'This may take multiple tries, so be sure to plan with a proper amount of Gysahl Greens. (A stack, more in some cases.)' },
                { 'Each time you dig you are given a general direction the treasure is as well as a hint about how close it is to your current location.', sub = {
                    { 'When you get the message "You are convinced that your moogle friend has been digging in the immediate vicinity.", it means you are almost right on top of the treasure.' },
                } },
            } },
            { 'Return to the Inconspicuous Door in Upper Jeuno (H-8) (across from Durable Shields) for a CS.' },
        },
    },
    ['Kupo Mission 8'] = {
        title        = 'Lender Beware! Read the Fine Print',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Oh, woe! Having exhausted all other options, your star-crossed moogle associate is forced to seek aid from the shadiest of scoundrels. You have an appointment with the underworld moneylender Riko Kupenreich at his office in Sea Serpent Grotto.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Travel to Sea Serpent Grotto and examine the Shady Sconce at (C-5) for a cutscene. You may need to do this twice to make sure it registers.', sub = {
                { 'Norg is the closest teleport.' },
            } },
            { 'Use a Sahagin Key to enter the Ornamental Door at (J-11) in Sea Serpent Grotto.' },
            { 'Continue to Sea Serpent Grotto map 5, then examine the Waterfall Basin at (H-6) for a cutscene.' },
            { 'Return to the Inconspicuous Door in Upper Jeuno (H-8) (across from Durable Shields).' },
        },
    },
    ['Kupo Mission 9'] = {
        title        = 'Rescue! A Moogle\'s Labor of Love',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'A dire development! Your moogle partner\'s betrothed, the fair Kupiruru, has been kidnapped by Toto\'s band of hoodlums! Make haste for the Chamber of Oracles to save the moogle maiden from a frightening fate!',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Make sure you possess the Map of the Quicksand Caves before you start! This is required.' },
            { 'Head to Western Altepa Desert (D-12) or use Geomagnetic Fount Waypoint to get to Quicksand Caves map 5.', sub = {
                { 'Alternatively use Quicksand Caves Home Point #1 for the Chamber of Oracles and exit out from exit 5 of map 5 at (H-4) to Western Altepa Desert. Once out go south towards the hidden area of (D-12) that will bring you straight to the goblin at entrance 4.' },
            } },
        },
    },
}

quest_info['asamissions'] = {
    ['A Shantotto Ascension Mission 1'] = {
        title        = 'A Shantotto Ascension',
        starting_npc = 'Windurst Walls',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Doctor Shantotto returned to Windurst one day after a mysterious, unexplained absence, shocking her colleagues by proclaiming herself ruler of her own empire. What could have possibly triggered this intensification of her inimical urges? The shocking truth awaits adventurers who would seek it!',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into Windurst Walls from Windurst Woods or Windurst Waters while level 10 or above.', sub = {
                { 'Entering via any other means (including the Mog House) will not trigger the starting cutscene.' },
            } },
        },
    },
    ['A Shantotto Ascension Mission 10'] = {
        title        = 'Battaru Royale',
        starting_npc = 'Full Moon Fountain',
        subtitle     = 'None',
        repeatable   = 'Yes',
        description  = 'Mission Orders: Determined to enact her odious plot to conquer all of Vana\'diel, Domina Shantotto has unleashed her army of clones upon you. Defeat them all lest you and your companions be reduced to bones!',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'After the initial cutscene from the Moon Spiral, click it again while possessing at least one elemental sap Key Item to receive the option to enter the Battaru Royale battlefield.', sub = {
                { 'Trusts can be summoned in this fight (relevant if you\'re doing it below item level 119.)' },
            } },
            { 'The battle is against 8 Tarutaru Fomor mobs, one for each element. (Clone of Boulders, Clone of Torrents, Clone of Gusts, Clone of Flames, Clone of Glaciers, Clone of Sparks, Clone of Lights, Clone of Shadows)', sub = {
                { 'Each Fomor will cast elemental and enfeebling spells of their corresponding element.' },
                { 'Each Fomor will summon an avatar of their corresponding element when they reach about 50% HP, and the avatar will use its associated Astral Flow ability before despawing.' },
                { 'The Fomors have access to all their usual TP abilities.' },
            } },
            { 'Successfully completing the battle will result in the awarding of a Key Item Chocobo key, which can be redeemed at the Treasure Coffer in Tenshodo Headquarters in Lower Jeuno.' },
        },
    },
    ['A Shantotto Ascension Mission 11'] = {
        title        = 'Romancing the Clone',
        starting_npc = 'Aldo',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: To your dismay but not complete surprise, Original Shantotto has chosen to side with her heinous alter ego. Best you return at once to Tenshodo Headquarters to plan your next move.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Talk to Aldo at (J-8) in Tenshodo Headquarters in Lower Jeuno for a cutscene.' },
        },
    },
    ['A Shantotto Ascension Mission 12'] = {
        title        = 'Sisters in Arms',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The two Shantottos have relocated their base of operation to the Sacrificial Chamber within the Temple of Uggalepih. Accompany Aldo and Professor Yoran-Oran there and put an end to this menace once and for all!',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Your goal is to get to the Mahogany Door in the Sacrificial Chamber for a cutscene. Along the way, there will be glowing ???s in the Temple of Uggalepih and Den of Rancor that give tablet Key Items which will be helpful in the upcoming battlefield. Each tablet will grant a specific buff.', sub = {
                { 'At max level, you only need 1 tablet to get the cutscene from the Mahogany Door: one possible way is to warp to Den of Rancor Home Point #1, exit south via the switch, grab the Key Item Tablet of Hexes: Blight at (H-9), warp back to Den of Rancor Home Point #1, and continue to the Sacrificial Chamber.' },
                { 'If you\'re attempting the upcoming battle below level 99, collecting all the tablets will make the fight easier.' },
            } },
        },
    },
    ['A Shantotto Ascension Mission 13'] = {
        title        = 'Project: Shantottofication',
        starting_npc = 'Sacrificial Chamber',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The inimitably fiendish Shantottofication curse, if allowed to wreak havoc on the land, would spell the end of the world as we know it. Only you can prevent an unimaginable fate from befalling Vana\'diel!',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'After the initial cutscene, click the Mahogany Door in the Sacrificial Chamber again for the option to the enter the Project: Shantottofication battlefield.', sub = {
                { 'The tablet Key Items are consumed upon entry and each one grants a buff. Possessing a full set will grant a +150 resistance to Element: Earth Earth, Element: Water Water, Element: Wind Wind, Element: Fire Fire, Element: Ice Ice and Element: Thunder Thunder magic, +150 to STR, VIT, DEX, AGI, MND, INT and CHR, a 3x multiplier to HP and MP, and a special Reraise that does not confer Weakness upon use.' },
                { 'The tablets are not necessary to begin the fight, and it is soloable by most Jobs in 119 gear with Trusts.' },
            } },
            { 'The fight is against D. Shantotto and Shantotto:', sub = {
                { 'D. Shantotto casts high level magic spells and uses Scythe weaponskills, including Salvation Scythe, which does AoE damage and inflicts poison and paralysis.' },
                { 'Shantotto casts high level magic spells and uses staff weaponskills, including Divine Malison, which does AoE damage and inflicts stun, slow, silence and plague.' },
            } },
            { 'Once one or the other reaches 50% HP, she will enter a kind of rage mode where she calls the other over to perform skillchains using their signature weaponskills on the current target.', sub = {
                { 'They cannot be drawn apart at this time.' },
                { 'While in this mode, the "raged" Shantotto cannot be killed. Damage can still be done to her, but she will not drop below 1% HP until it ends.' },
                { 'If the party wipes after the rage mode is triggered, it will not be repeated if a second attempt is made without exiting the battlefield.' },
            } },
            { 'Successful completion of the fight will award a Key Item Tonberry key, which can be redeemed at the Treasure Coffer in Tenshodo Headquarters in Lower Jeuno.' },
        },
    },
    ['A Shantotto Ascension Mission 14'] = {
        title        = 'An Uneasy Peace',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Disaster has been averted thanks to your relentless efforts, each denizen of Vana\'diel returning to the life they used to know. But how long can this period of tranquility be expected to endure? Professor Yoran-Oran cannot help but be pessimistic...',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into Windurst Walls from Windurst Woods or Windurst Waters for a cutscene.', sub = {
                { 'Entering via any other means (including the Mog House or HP Warp) will not trigger the final cutscene.' },
            } },
            { 'You will be awarded a Key Item Behemoth key, which can be redeemed at the Treasure Coffer in Tenshodo Headquarters in Lower Jeuno for Blitzer Poleyn, Desultor Tassets or Tatsu. Sitagoromo.' },
        },
    },
    ['A Shantotto Ascension Mission 15'] = {
        title        = 'A Shantotto Ascension (Fin)',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = '',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Redeem the Key Item Behemoth key at the Tenshodo in Lower Jeuno for your reward.' },
        },
    },
    ['A Shantotto Ascension Mission 2'] = {
        title        = 'Burgeoning Dread',
        starting_npc = 'East Sarutabaruta or West Sarutabaruta',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Does this feeling of disquiet welling up within portend the coming of catastrophe, or is it simply something to be ignored? You can only hope that it is all in your mind...',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into either East Sarutabaruta or West Sarutabaruta via one of Windurst\'s gates for a cutscene.', sub = {
                { 'Take note of which Enfeeblement Kit you are asked for in the cutscene. It will be required to complete the next mission.' },
            } },
        },
    },
    ['A Shantotto Ascension Mission 3'] = {
        title        = 'That Which Curdles Blood',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You have been served what appears to be a draft card inducting you into the Shantotto Empire as a special operative. Report to provisional headquarters located on Qufim Island with extreme haste...and the specified gifts of tribute in hand.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'You are tasked with creating an Enfeeblement Kit of Silence, Enfeeblement Kit of Sleep, Enfeeblement Kit of Poison, or Enfeeblement Kit of Blindness.', sub = {
                { 'If you do not recall which item you have been tasked with creating, speak with one of the NPCs listed below. They will give you the recipes for making the components, but you do not have to talk to them at any point in the gathering of ingredients or the synthing of items.', sub = {
                    { 'Kuroido-Moido at (E-7) in Port Windurst.' },
                    { 'Faulpie at (E-8) in Southern San d\'Oria.' },
                    { 'Abd-al-Raziq at (L-7) in Bastok Mines.' },
                } },
            } },
            { 'For the kit, you will need:', sub = {
                { 'Padded Box: Earth Crystal, Bast Parchment x2, Inferior Cocoon (Can also be made from a Woodworking Kit 5 from guild NPC)' },
                { 'Fine Parchment: Dark Crystal, Parchment, Pumice Stone (You will need to make two of these)' },
                { 'Enchanted Ink: Dark Crystal, Black Ink, Magicked Blood (You will need to make two of these}' },
                { 'A Silencing Potion, Sleeping Potion, Poison Potion, or Blinding Potion (It will depend on which enfeeblement kit you are told to make)' },
            } },
            { 'Once you have obtained all the components, combine them together with an Earth Crystal.', sub = {
                { 'As a note, all of the components can be traded, but the enfeeblement kit itself cannot, and therefore must be synthed by the player doing the mission.' },
                { 'Synths can fail, so it may be wise to have access to extra ingredients.' },
                { 'An Alchemy level of 10 is recommended to synth the Enfeeblement Kit to increase the chances of success.' },
            } },
            { 'Trade the kit to the Trodden Snow at (H-7) in Qufim Island for a cutscene.' },
        },
    },
    ['A Shantotto Ascension Mission 4'] = {
        title        = 'Sugar-coated Directive',
        starting_npc = 'Trodden Snow, Qufim Island - (H-7)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Your inaugural mission as special operative of the Shantotto Empire requires you to attach enchanted seals to the protocrystals scattered across Vana\'diel. Your new empress has stressed that she takes failure poorly.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'You are given 6 Key Item seals (Key Item Domina\'s scarlet seal, Key Item Domina\'s cerulean seal, Key Item Domina\'s emerald seal, Key Item Domina\'s amber seal, Key Item Domina\'s violet seal, Key Item Domina\'s azure seal) and instructed to attach at least 3 of them to the Protocrystals found around Vana\'diel.', sub = {
                { 'Protocrystals are found in the Cloister of Storms, Cloister of Frost, Cloister of Flames, Cloister of Tremors, Cloister of Tides and Cloister of Gales.' },
            } },
            { 'Click each Protocrystal once, then click again for the option to enter a Battlefield entitled Sugar-coated Directive.', sub = {
                { 'Enter the battlefield and defeat a weakened version of the corresponding Prime Avatar.' },
                { 'The Avatar will not die until it has tried to use its Astral Flow ability 5 times.' },
            } },
            { 'After the battle, click the crystal again to attach the seal and receive a counterseal Key Item (Key Item Scarlet counterseal, Key Item Cerulean counterseal, Key Item Emerald counterseal, Key Item Amber counterseal, Key Item Violet counterseal, Key Item Azure counterseal).', sub = {
                { 'Note: If you leave the area before receiving the counterseal Key Item, you can simply return in order to obtain it; the battle is not repeated.' },
            } },
            { 'Once at least 3 counterseals are obtained, return to the Trodden Snow at (H-7) in Qufim Island for a cutscene.' },
            { 'You will receive a Gil reward that is dependent on the number of counterseals obtained:', sub = {
                { '3 seals: 3,000 Gil' },
                { '4 seals: 10,000 Gil' },
                { '5 seals: 30,000 Gil' },
                { '6 seals: 50,000 Gil' },
            } },
        },
    },
    ['A Shantotto Ascension Mission 5'] = {
        title        = 'Enemy of the Empire (I)',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Seeking to usurp the Tenshodo as the underworld\'s foremost supplier of contraband, Domina Shantotto requires that you remove its leader, Aldo, from the picture. A clandestine meeting between you and the target has been arranged in the Gustav Tunnel. All that is needed to initiate contact is a black book, acquirable from Andrause in Norg.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Talk to Andrause at (I-8) in Norg.' },
            { 'You will be given 3 specific monsters from which you must acquire a Soul Plate using a Soultrapper.', sub = {
                { 'Andrause will offer to sell you a Soultrapper and 12 Blank Soul Plates for 800 Gil.' },
                { 'You can buy another 12 Blank Soul Plates from him each day (after JP Midnight).' },
                { 'Note: he will only accept Soul Plates of monsters found in Sea Serpent Grotto.' },
            } },
            { 'How to take pictures:', sub = {
                { 'Equip the Soultrapper into your Ranged slot, and the Blank Soul Plates into your Ammo slot.' },
                { 'You can then use the Soultrapper via the Inventory onto a target, or alternatively, use a macro line /item "Soultrapper" <t> or any equivalent.' },
                { 'The Soultrapper cannot be used while under the effect of Sneak or Invisible.' },
                { 'Sometimes you\'ll fail taking a picture. Just try again!' },
            } },
            { 'Andrause will mention which monsters he\'s "investigating", and depending on the monsters chosen, you may need a Silver Beastcoin, Mtl. Beastcoin or Gold Beastcoin to gain access to them:', sub = {
                { 'Monsters found in the open area: Bigclaw (M-14), Brook Sahagin, Riparian Sahagin, Rivulet Sahagin, Royal Leech, Undead Bats and Grotto Pugil.' },
                { 'Monsters found behind the Silver Beastcoin door: Grotto Pugil, Sea Bonze.' },
                { 'Monsters found behind the Mythril Beastcoin door: Blubber Eyes, Bog Sahagin, Marsh Sahagin, Rock Crab, Razorjaw Pugil, Sahagin Parasite, Swamp Sahagin.' },
                { 'Monsters found behind the Gold Beastcoin door: Coastal Sahagin, Devil Manta, Delta Sahagin, Dire Bat, Lagoon Sahagin, Mousse, Robber Crab, Shore Sahagin.', sub = {
                    { 'Unity Warp (125) puts you past the Gold Beastcoin door.' },
                    { 'Delta Sahagin\'s can sometimes be pulled down into the open area at (J-12, K-12 Map 1) off the ledge from behind the Ornamental Door with magic.' },
                } },
            } },
            { 'Trade the required Soul Plates to him one at a time and he will give you a Key Item Black book Key Item.', sub = {
                { 'Should you require another, he will give you one in exchange for 3 more Soul Plates of his choosing.' },
            } },
            { 'Once you have the book, click on the Outcropping at (F-10) in Gustav Tunnel for a cutscene.' },
            { 'Clicking it a second time will immediately start the next mission and initiate a fight against 3 Tenshodo agents.', sub = {
                { 'The Black book is taken once the fight starts, so if you should lose, you will need to acquire another.' },
            } },
        },
    },
    ['A Shantotto Ascension Mission 6'] = {
        title        = 'Enemy of the Empire (II)',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The overzealous young Tenshodo agents are not interested in listening to reason. In the name of your empress, you have no choice but to flex your adventurer muscles and pound some sense into them.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Interact with the Outcropping at (F-10) in Gustav Tunnel for a cutscene.', sub = {
                { 'Unity Warp 128 from Cape Teriggan can be faster for those without movement speed bonuses.' },
                { 'Survival Guide in Gustav Tunnel (K-7) puts you on the opposite end of the tunnel. You will not need Sneak at level 75.' },
            } },
            { 'The following fight is trivial at level cap, but if you\'re at a lower level, prepare to battle:' },
            { 'Interacting with the Outcropping again will start a fight against 3 Tenshodo agents named Renfred, Bompupu and Gorattz and consume the Key Item Black book Key Item.', sub = {
                { 'Trust Magic can not be used in this fight.' },
                { 'You will keep your buffs: Phalanx will negate all damage from this fight except Bompupu\'s nukes.' },
            } },
            { 'The 3 agents start off untargetable and cast Utsusemi: Ni a few times, then 4 clones of each will spawn.', sub = {
                { 'The clones aren\'t very strong, having low HP, accuracy, attack and defense, and cast elemental and enfeebling Ninjutsu.' },
            } },
            { 'At some point (either time elapsed or number of clones defeated), the 3 agents will join the fight, at which time they can be attacked, and must be defeated in order to win the encounter.', sub = {
                { 'They can be differentiated from the clones because they have higher HP and will continue to cast Utsusemi as well as other Ninjutsu.' },
                { 'Once in the fight, they will still continue to spawn clones as the clones are dispatched.' },
                { 'Once an agent is defeated, any of his or her remaining clones will despawn after a couple of seconds.' },
            } },
            { 'When all 3 agents are down, you will be rewarded a Key Item Cactuar key, which can be redeemed at the Treasure Coffer in Tenshodo Headquarters in Lower Jeuno.' },
            { 'Interact with the Outcropping again for a cutscene.' },
        },
    },
    ['A Shantotto Ascension Mission 7'] = {
        title        = 'Sugar-coated Subterfuge',
        starting_npc = 'Aldo',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: A candid conversation has cleared things up between you and Aldo. He bids you come to Tenshodo Headquarters in Jeuno in order to further discuss Shantotto\'s diabolical designs.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Talk to Aldo at (J-8) inside Tenshodo Headquarters in Lower Jeuno for a cutscene.' },
        },
    },
    ['A Shantotto Ascension Mission 8'] = {
        title        = 'Shantotto in Chains',
        starting_npc = 'Ro\'Maeve',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You have learned that the original Doctor Shantotto is being held captive somewhere in Ro\'Maeve. Realizing that only Shantotto can stand against Shantotto, Professor Yoran-Oran has proposed a rescue mission.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Click the Ensorcelled Door at (B-10) south-west corner in Ro\'Maeve.', sub = {
                { 'There is no cutscene, but you will be told about a "hexagonal depression" on the door.' },
            } },
            { 'You must collect 6 Key Item Key Item fragments from various monsters.', sub = {
                { 'Note: If you are in a party/alliance, everyone in the group will obtain the Key Item Key Item if it drops.' },
                { 'The fragments are not a guaranteed drop, but have a high drop rate. Treasure Hunter does not work on them, because they are not normal items.' },
                { 'The NMs will despawn 5 minutes after being engaged and will respawn 2 minutes after either despawning or successfully being killed.' },
            } },
            { 'If relying on damage from Trusts, refer to the Damage Type table to select the appropriate Trust for each NM.' },
        },
    },
    ['A Shantotto Ascension Mission 9'] = {
        title        = 'Fountain of Trouble',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Original Shantotto has revealed that her corrupted counterpart concocts her plan for world domination from her Full Moon Fountain lair. In the defense of Vana\'diel, make your way there without delay.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'The 8 elemental saps can be found at various locations throughout Toraimarai Canal and have the effect of weakening the Astral Flow ability of the corresponding Fomor\'s avatar in the battlefield awaiting you in the next mission.', sub = {
                { 'At max level, it is possible to skip most of the mission by warping to Home Point #1, getting the Key Item Dark sap crystal near the Home Point, then backtracking to Full Moon Fountain to continue the questline.' },
                { 'If you\'re attempting the upcoming battle below level 99, collecting all the saps will make the fight easier.' },
            } },
            { 'The elemental saps appear as glowing ???s at the following locations:', sub = {
                { 'Key Item Dark sap crystal: (F-8) Map 1' },
                { 'Key Item Earth sap crystal: (J-8) or (H-7) Map 1' },
                { 'Key Item Water sap crystal: (H-7) or (J-9) Map 1' },
                { 'Key Item Fire sap crystal: (J-9) Map 1; (F-10) or (J-8) Map 2' },
                { 'Key Item Ice sap crystal: (I-8) or (H-7) Map 2' },
                { 'Key Item Light sap crystal: (G-8) Map 2 (one of two places)' },
                { 'Key Item Lightning sap crystal: (H-7) Map 1; (G-10/11) Map 2' },
                { 'Key Item Wind sap crystal: (H-9) or (J-9) Map 2' },
            } },
            { 'Once one or more saps are collected, check the Moon Spiral in Full Moon Fountain to watch the cutscene and complete the mission.' },
        },
    },
}

quest_info['soamissions'] = {
    ['Rhapsodies of Vanadiel Mission 3-8'] = {
        title        = 'Gone but Not Forgotten',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: According to Balamor, the orb Iroha gave you has something to do with the power of time. He will return what he took from you if you bring him a relic of the founder king. Look for it somewhere in Rala Waterways.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'In Rala Waterways, select the sluice gate and enter, head to the secret hideout at (C-6).', sub = {
                { 'Must be on at least Seekers of Adoulin Mission 2-7-1 Behind the Sluices and up to the part where you enter the sluice to get proper access to the Sluice Gate.' },
                { 'Most easily accessed via Western Adoulin (F-5) from the Adoulin Waterfront Waypoint.' },
            } },
            { 'Examine the Inconspicuous Barrel to receive the Key Item Founder king\'s orb key item.', sub = {
                { 'This will complete the Mission.' },
            } },
        },
    },
    ['Seekers of Adoulin Mission 1-1'] = {
        title        = 'Rumors from the West',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Word around the Middle Lands is that a pioneering initative has begun in the land of the setting sun. The Jeuno Chamber of Commerce and Industry is looking for potential pioneers to assist in the projects. They have prepared a test of skill.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'After loading up the game for the first time after registering and installing Seekers of Adoulin and entering one of the three starting nations, you will receive a brief cutscene indicating that you should make your way to Jeuno.', sub = {
                { 'This cutscene is not necessary to continue.' },
            } },
            { 'Proceed to Lower Jeuno and speak with Darcia in the Chamber of Commerce at (H-7) and select the option "I would like to apply!" to complete this mission and begin the next. You will receive the Key Item Geomagnetron Key Item.' },
        },
    },
    ['Seekers of Adoulin Mission 1-2'] = {
        title        = 'The Geomagnetron',
        starting_npc = 'Darcia, Lower Jeuno (H-7)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Bring the geomagnetron Darcia has entrusted you with to one of the dungeons she mentioned, find the applicable area located therein, and record the energies there onto the mysterious device.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak with Darcia in Lower Jeuno at (H-7) (Chamber of Commerce and Industry) and choose the option "I would like to apply!" indicating your interest to receive the Key Item Geomagnetron Key Item and a list of locations to which it can be attuned.' },
            { 'Travel to one of the locations and attune the device to the Geomagnetic Fount found there:', sub = {
                { 'Gustav Tunnel: Map 1, at the pond closest to the Cape Teriggan exit (G-10).', sub = {
                    { 'Really close to Unity Warp 128. Go south into Map 1, the pond will be south-west, seconds away.' },
                } },
                { 'Ranguemont Pass: Southeastern corner, (J-10)' },
                { 'Yughott Grotto: (J-7), in the pond' },
                { 'King Ranperre\'s Tomb: (K-6), nearest to Jugner Forest Proto-Waypoint' },
                { 'Monastic Cavern: (H-10) Map 1' },
                { 'The Eldieme Necropolis: (J-10) Map 2. Fall from first floor (F-8)' },
                { 'Ordelle\'s Caves: Hidden Apparatus Area (F-12)' },
                { 'Gusgen Mines: Last map, NW corner (G-7) Map 3' },
                { 'Dangruf Wadi: (E-11), after falling in the hole in the hidden tunnel' },
                { 'Korroloka Tunnel: (G-9) Map 4, (Jammer Leech NM spot)' },
                { 'Palborough Mines: (J-8) Map 2' },
                { 'Labyrinth of Onzozo: (J-5), Off the map in the northeast (access from the south).' },
                { 'Maze of Shakhrami: (K-9) Map 1' },
                { 'Garlaige Citadel: (G-8) Map 2, behind banishing gate #1' },
                { 'Crawlers\' Nest: (F-7) Map 1' },
                { 'Outer Horutoto Ruins: (G-7) Map 2', sub = {
                    { 'Enter from East Sarutabaruta (H-3)' },
                } },
                { 'Inner Horutoto Ruins: (G/H-7) Map 2, Beetles Burrow.', sub = {
                    { 'Enter from East Sarutabaruta (J-7)' },
                } },
                { 'Toraimarai Canal: (I-6) towards Inner Horutoto Ruins' },
            } },
            { 'Return to Darcia with the attuned Geomagnetron to receive the Key Item Adoulinian charter permit.' },
            { 'Alternatively, this mission can be skipped by paying 1,000,000 Gil to the NPC to immediately receive the Key Item Adoulinian charter permit.', sub = {
                { 'This mission can also be skipped by completing Rhapsodies of Vanadiel Mission The River Runs Red, Iroha will hand you the Geomagnetron for you to speak with Darcia to receive the Key Item Adoulinian charter permit.' },
            } },
        },
    },
    ['Seekers of Adoulin Mission 1-3'] = {
        title        = 'Onward to Adoulin',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Depart for the frontier city of Adoulin via a waypoint and begin a whole new saga of adventure!',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Activate the Waypoint located at (H-7) in Lower Jeuno to begin your new adventure in Seekers of Adoulin!' },
        },
    },
    ['Seekers of Adoulin Mission 1-4'] = {
        title        = 'Heartwings and the Kindhearted',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You learn from Arciela, the maiden whom you met in the Ceizak Battlegrounds, that the Sacred City of Adoulin lies to the north.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head North/East through Ceizak Battlegrounds to arrive at Western Adoulin (K-7).', sub = {
                { 'You can use Mounts here.' },
            } },
        },
    },
    ['Seekers of Adoulin Mission 1-5'] = {
        title        = 'Pioneer Registration',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Before embarking on a trek to colonize Ulbuka, you\'ll first need to register with the Pioneers\' Coalition. Look for a sign painted with a shovel and you can\'t miss it!',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Proceed to the Pioneers\' Coalition at Western Adoulin (E-8) and speak with Brenton for a cutscene.', sub = {
                { 'Make sure you talk to a Task Delegator NPC at this point to begin accruing imprimaturs.' },
            } },
        },
    },
    ['Seekers of Adoulin Mission 1-6'] = {
        title        = 'Life on the Frontier',
        starting_npc = 'Brenton, Western Adoulin (E-8)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: With pioneer registration under your belt, you can now undertake assignments from the various coalitions scattered around the city. Take on as many as you can and help the colonization effort succeed!',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Depending on Fame you will get the cutscene sooner with less Imprimaturs used.', sub = {
                { '15 imps utilized with I\'m on a Boat / Hide and Go Peak quests completed is sufficient for all missions requiring fame.', sub = {
                    { 'It is also possible to complete missions with zero Imprimaturs spent, but the fame requirement is higher.' },
                } },
            } },
            { 'Upon completing that, you also gain the ability to purchase Key Items that allow for participation in Wildskeeper Reives, battling against the Naakuals.', sub = {
                { 'These can be purchased from Dimmian in Eastern Adoulin (E-6).' },
            } },
            { 'Talk to Brenton for a cutscene to complete the mission and receive the Key Item Dinner invitation.' },
        },
    },
    ['Seekers of Adoulin Mission 1-7'] = {
        title        = 'Meeting of the Minds',
        starting_npc = 'Brenton, Western Adoulin (E-8)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You have been invited to dine with the city\'s political leaders at Castle Adoulin. Head to the eastern district and present your missive to the guard at the castle gates.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Talk to Ploh Trishbahk at the Gates of Castle Adoulin in Eastern Adoulin (K-9) between 15:00-22:00. The cutscene received completes this Mission.', sub = {
                { 'At this point, begin the quest Flavors of Our Lives and get to the point where Teodor is introduced to avoid delays later. You will have to wait an additional gameday in the next mission if you fail to do this.' },
            } },
        },
    },
    ['Seekers of Adoulin Mission 1-8'] = {
        title        = 'Arciela Appears Again',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: By reuniting with--and learning the identity of--Arciela V. Adoulin, you have set the wheel of fate in motion...',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'The Imprimatur requirement can be fulfilled prior to this Mission, in which case the next Mission can be started on the next game day.', sub = {
                { 'You may continue this Mission by meeting a total of completing Coalition Assignments (measured by total Imprimaturs spent on them) along with achieving a certain level of Adoulin Fame.', sub = {
                    { '15 imps utilized + Fame 2 (I\'m on a Boat / Hide and Go Peak / Western Waypoints, Ho! / Wes...Eastern Waypoints, Ho! / The Old Man and the Harpoon) is sufficient.' },
                } },
            } },
        },
    },
    ['Seekers of Adoulin Mission 2-1'] = {
        title        = 'Budding Prospects',
        starting_npc = 'Levil, Western Adoulin (E-8)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Rumors abound of a queen that rules over the precocious leafkin. Find out more about this mysterious creature by asking around Adoulin. Perhaps the well-trafficked Mummers\' Coalition would be a good place to start.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Go to the Pioneers\' Coalition and talk to Levil.' },
            { 'If you haven\'t started the Quest Flavors of Our Lives and been introduced to Teodor yet, you will need to do the following:', sub = {
                { 'Talk to Berghent at (J-9) near the Big Bridge.' },
                { 'Go to the Mummers\' Coalition and talk to Masad.', sub = {
                    { 'You will need to wait until the next in-game day and you may need to zone to get the cutscene for the Mission from Masad.' },
                } },
            } },
            { 'Go to the Mummers\' Coalition and talk to Masad.', sub = {
                { 'You may need to speak with him twice after the day changes and you zone to receive the cutscene.' },
            } },
        },
    },
    ['Seekers of Adoulin Mission 2-1-1'] = {
        title        = 'The Light Shining in Your Eyes',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The black-clad statesman Teodor has informed you that the dark blade wielded by Arciela is the only thing that will prove your worth to the leafkin. Report back to Levil with your findings.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Go to the Pioneers\' Coalition and talk to Levil.' },
        },
    },
    ['Seekers of Adoulin Mission 2-1-2'] = {
        title        = 'The Heirloom',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Arciela\'s blade was bestowed upon her by Ygnas, and she never lets it leave her side. The best place to find her is likely Castle Adoulin.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Approach Eastern Adoulin\'s Castle Gate for a cutscene.' },
        },
    },
    ['Seekers of Adoulin Mission 2-2'] = {
        title        = 'An Aimless Journey',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Arciela was nowhere to be found at the castle, but one of her servants let slip that she was off to investigate an ergon locus in Cirdas Caverns. Has she really traveled out there alone...?',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Travel to Cirdas Caverns and head towards the Ergon Locus at (E-9) for a cutscene.', sub = {
                { 'The Ergon Locus is blocked by a Colonization Reive requiring "Logging"' },
            } },
            { 'After viewing the cutscene you can now continue Tears of the Generals (Rhapsodies of Vanadiel Mission 3-6).' },
        },
    },
    ['Seekers of Adoulin Mission 2-4'] = {
        title        = 'Honor and Audacity',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: A fight has broken out and Gratzigg, the Peacekeepers\' Coalition leader, has ordered it be moved to an official venue. Head to the Watergarden Coliseum to witness the spectacle.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into Rala Waterways from Eastern Adoulin (F-7) for a cutscene with Arciela.' },
        },
    },
    ['Seekers of Adoulin Mission 2-4-1'] = {
        title        = 'The Watergarden Coliseum',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Seeing an official duel apparently requires permission. However, during yet another chance encounter with Arciela, the princess tells you that as long as you are her escort, the guards will have to let you into the coliseum.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to the room at the center of (M-6) in Rala Waterways and speak to Yeggha Dolashi for a cutscene.', sub = {
                { 'The closest entrance is the (F-7) entrance from Eastern Adoulin.' },
            } },
        },
    },
    ['Seekers of Adoulin Mission 2-2-1'] = {
        title        = 'Ortharsyne',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Having reunited with Arciela in Cirdas Caverns, you learned that she will not let you have the sword, but instead will go with you to Yorcia Weald. The entrance to Yorcia Weald lies in I-7 of Cirdas Caverns.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into Yorcia Weald for a cutscene', sub = {
                { 'You may use a waypoint or the Home Point to Yorcia Weald to trigger this cutscene.' },
            } },
        },
    },
    ['Seekers of Adoulin Mission 2-5'] = {
        title        = 'Friction and Fissures',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The rift between those in support of the colonization movement and those in opposition to it is quickly deepening. The matter weighs heavily on everyone, but upon the princess most of all.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to Levil at the Pioneers\' Coalition (E-8) in Western Adoulin for a cutscene.' },
        },
    },
    ['Seekers of Adoulin Mission 2-5-1'] = {
        title        = 'The Celennia Memorial Library',
        starting_npc = 'Levil, Western Adoulin (E-8)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Though this most recent upheaval may have been quelled, it is but one symptom of a much larger problem that plagues Adoulin. Head to the Celennia Memorial Library to learn more about this pandemic of discord.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Proceed to the Celennia Memorial Library at (F-10) in Eastern Adoulin. Talk to Eppel-Treppel to enter the building.' },
            { 'Read all three options in the book entitled History on the bookshelf. The section is between Yefafa and Vainrachault.', sub = {
                { 'If you are unable to read any books on the shelves, you will first need to complete the quest Order Up from Reja Ygridhi, who is located inside the library.', sub = {
                    { '1000 Bayld is required to purchase a Key Item Celennia Memorial Library card from Patient Snake (Eastern Adoulin, F-9) in order to start the quest. He is located at the end of the pathway leading to the interior of the Scouts\' Coalition.' },
                } },
            } },
            { 'Return to Levil in the Pioneers\' Coalition in Western Adoulin.' },
        },
    },
    ['Seekers of Adoulin Mission 2-5-2'] = {
        title        = 'For Whom Do We Toil?',
        starting_npc = 'Levil, Western Adoulin (E-8)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The only thing on Adoulinians\' lips these days seems to be that the city\'s youth are using the Rala Waterways without permission. Descend underground once more to see if this is actually the case.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter Rala Waterways for a cutscene.', sub = {
                { 'The closest entrance to the destination is via Western Adoulin at (F-5) which is closest to the Adoulin Waterfront Waypoint.' },
            } },
            { 'Proceed south to the dead end at (C-6) and click the Sluice Gate. Enter the password which can be determined from the clues in this Mission and the previous mission (case sensitive, enter it in all capitals) to start a cutscene.', sub = {
                { 'Hints: [The password is four letters and hinted at on a marked page in the history book in the library and upon zoning into Rala Waterways.]' },
                { 'Solution: [The password is the first initial of each order leader on the marked library page. These are the four leaders who voted against the Colonization effort.]' },
                { 'Password: [HGSI - the initials of the leaders Hildebert, Gratzigg, Svenja, and Ikhi Askamot.]' },
                { 'If you enter the incorrect password too many times, you will be locked out of entering the password until after you return to the library and read the History book again.' },
            } },
            { 'Once the cutscene is completed you will receive the Key Item Note detailing seditious plans.', sub = {
                { 'If you failed to repeat the password correctly during the cutscene (after being challenged upon choosing the conversationally incorrect response "It could increase crops threefold!") you will need to click the door once more to get the Key Item. This needs to be entered in upper-case as well or they will still proclaim "We have a spy among us! Off with [his/her] head!". You will get a different scene after you interact with the Sluice Gate again, where The congretation has already dispersed....' },
                { 'However, if you select the better option "Of course it won\'t help" you do not have to re-enter the password.' },
            } },
        },
    },
    ['Seekers of Adoulin Mission 2-2-2'] = {
        title        = 'In the Presence of Royalty',
        starting_npc = 'N/A',
        subtitle     = 'Queen\'s Confidante',
        repeatable   = 'No',
        description  = 'Mission Orders: Fate saw you meet with Rosulatia, the burnr seed of the leafkin. She has asked you to find a Yorcia\'s tear to learn about the abnormalities in Eastern Ulbuka. Find one and head to the sole pure font of water within the weald.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Obtain a Key Item Yorcia\'s tear via one of two methods:', sub = {
                { 'Option 1: Click on the Ergon Locus ??? at the southern part of (I-8) in Yorcia Weald.', sub = {
                    { 'You must enter (I-8) from the West, but there is occasionally a wall that blocks the path. The path opens at 21:00.' },
                    { 'There is also another Ergon Locus and a ??? in the northern part of (I-8), but neither of those are the correct location. You need to use the one mentioned above entering (I-8) from the west.' },
                } },
                { 'Option 2: Harvest by using a Sickle on a Harvesting Point.', sub = {
                    { 'Bring extra Sickles as they may break before obtaining the key item. Harvesting with a full inventory will prevent you from receiving normal items; however, Harvesting Points will still be used while attempting for the key item.' },
                    { 'Harvesting Points can be scarce, and will despawn and respawn elsewhere after a set amount of time. Option 1 is much easier.' },
                } },
            } },
            { 'Go to (G-6) after obtaining your Key Item Yorcia\'s tear and click the Pellucid Afflusion next to the pond for a cutscene.', sub = {
