    ['Seekers of Adoulin Mission 4-2-3'] = {
        title        = 'A Vow of Truth',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Sajj\'aka has revealed that the doors to the labyrinth are beginning to open, and Hades\' revival is imminent. Unless Sajj\'aka returns to fighting form, there is no chance of staving off these sinister forces. Yet where could the holy dragon\'s scales be...?',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter Woh Gates from any entrance for a cutscene.', sub = {
                { 'The Frontier Station in Kamihr Drifts is the closest from this zone, the entrance is at (K-11).' },
                { 'If you\'re coming from the city, the closest waypoint is Marjami Ravine WP #4, and a short walk to the northwest.' },
            } },
        },
    },
    ['Seekers of Adoulin Mission 4-2-4'] = {
        title        = 'Darrcuiln',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You have once again met with Darrcuiln, this time in Woh Gates. Follow his lead.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the spot Darkened Crevice in Woh Gates at the (G-7)/(G-8) border for a cutscene. It is slightly inside a tunnel, just before the downward slope.', sub = {
                { 'If you\'re coming from the Kamihr Drifts entrance, fall down at (I-5) then fall down again at (H-6), and once you\'re in the big room proceed to the (G-7)/(G-8) border.' },
                { 'If you\'re coming from the Marjami Ravine entrance, follow the left wall the whole way, which will let you skip the Colonization Reive at (H-9), though you\'ll still need to participate in one at (H-7) to clear the way.', sub = {
                    { 'Before getting too close to the big room from either route, use Sneak+Invisible at a distance (or better yet use Silent Oil & Prism Powder), as the Bergschrund Gefryst is aggressive toward magic, Metalcruncher Worm is aggressive to sound, and Serac Rabbit and Powdery Snoll are aggressive to sight.' },
                } },
            } },
            { 'You will receive the Key Item Tuft of golden fur after this cutscene. This is considered a BCNM entry item, and will be lost upon entry to the upcoming battle.' },
        },
    },
    ['Seekers of Adoulin Mission 4-3'] = {
        title        = 'The Gates',
        starting_npc = 'N/A',
        subtitle     = 'Ulbukan Understudy',
        repeatable   = 'No',
        description  = 'Mission Orders: Chasing after Darrcuiln, you stumbled upon hordes of umbrils fighting leafkins. Who is the strange man fighting alongside the woodland creatures? Assist them in battle and find out the truth.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the Darkened Crevice at (G-8) in Woh Gates to enter "The Gates" BCNM against waves of Umbrils.', sub = {
                { 'You may attempt the Battlefield solo.' },
                { 'The battle starts automatically after about a minute. Giving you a quick moment to buff and call Trusts.' },
            } },
            { 'You are assisted by Arciela, Darrcuiln, Noble Warrior, and some cute Resolute Leafkins.', sub = {
                { 'Arciela Casts Haste, Protect V, and Shell V on herself, party members, and the other NPCs.' },
            } },
            { 'The fight is lost if any NPCs die.', sub = {
                { 'The NPCs can be buffed and healed with Blood Pact: Wards.' },
                { 'NPCs can also be buffed via accession if you cast it on a trust you summon, such as Regen V.' },
                { 'Curaga when cast on a Trust will affect the entire group, but not when cast on a PC.' },
            } },
            { 'The fight is still won if all players are dead, but the NPCs finish killing the monsters.' },
            { 'See the Discussion Page page for strategies and further battle information.' },
        },
    },
