    ['Seekers of Adoulin Mission 4-3-2'] = {
        title        = 'A New Force Arises',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Morimar proffers that Sajj\'aka\'s scales have been sealed deep within the labyrinth. Employ The holy dragon\'s protection to access areas of Ra\'Kaznar previously sealed off, and find his scales.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to Outer Ra\'Kaznar by using the Liseran Door: Entrance in Kamihr Drifts (F-8).', sub = {
                { 'If previously unlocked, you can use the Waypoint: Enigmatic Device → Outer Ra\'Kaznar.' },
            } },
            { 'In Outer Ra\'Kaznar, find and examine the following location:', sub = {
                { 'Effigy of Sealing at (I-11) (Upstairs, Map 1) to receive the Key Item Starblessed scale.' },
                { 'Silvery Plate at (C-7) (Upstairs, Map 1) to receive the Key Item Silvery plate.', sub = {
                    { 'Note: Do not proceed to next scale before picking up this Key Item. It allows use of the elevator at (I-6) (Upstairs, Map 1) to reach last scale.' },
                } },
                { 'Effigy of Sealing at (H-2) (Upstairs, Map 1) to receive the Key Item Moontouched scale.' },
                { 'Demonic Architrave at (C-8) (Basement, Map 2) to receive the Key Item Sunkissed scale.', sub = {
                    { 'While the scales can be collected in any order, it is highly recommended to use the order provided above due to the natural flow of traversing throughout the zone.' },
                    { '(Optional): After collecting any scale, minor additional cutscenes become available at both the Alpine Trail at (H-5) in Kamihr Drifts and the Celennia Memorial Library. Even if they are not triggered by returning halfway through the Mission, they can still be watched at the Goblin Footprint at (K-11) in Kamihr Drifts and by talking to Jedelaih in the Celennia Memorial Library respectively.', sub = {
                        { 'There are no additional scenes for having collected two scales.' },
                    } },
                } },
            } },
            { 'After collecting all the items, return to Kamihr Drifts - Biovauc #3 (or Home Point) again and examine the Alpine Trail at (H-5) for a cutscene and the Key Item World Tree sapling.' },
        },
    },
