        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Your kind words have instilled confidence in the princess once more. In thanks, Ygnas has bequeathed to you an item used in accessing the founder king\'s tomb in Rala Waterways, where he says Balamor resides.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter Rala Waterways from Eastern Adoulin (F-7), next to Waypoint #1 and #4.' },
            { 'Head to (N-10) (very south-eastern point on the map) and click on the Royal Sepulcher for a cutscene.' },
        },
    },
    ['Seekers of Adoulin Mission 4-6'] = {
        title        = 'Balamor\'s Ruse',
        starting_npc = 'N/A',
        subtitle     = 'Shedder of Harlequin Tears',
        repeatable   = 'No',
        description  = 'Mission Orders: Ygnas was correct, and the evil clown was hiding in that tomb. A true enigma, Balamor has hidden statue segments in the monsters that roam the waterways and implores you to find them.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Kill enemies in Rala Waterways until you acquire a Key Item Consummate simulacrum.', sub = {
                { 'The drop rate seems to be higher from the Waterway Pugils and New Moon Bats. (Efts and Diremites near the Augural Conveyor didn\'t drop after farming for about 15+ minutes, but New Moon Bats near the East Adoulin entrance dropped on the first kill on one occasion, and on the second on another).' },
                { 'All party members in the zone who are currently on the mission will receive the Key Item Consummate simulacrum at the same time. Party members who have previously completed the mission can cause the key item to drop - farming doesn\'t need to be done by the member(s) on the mission.' },
                { 'The Key Item Consummate simulacrum will appear in your Temporary Key Items after any Wildskeeper Reive entry items but before any entry items for the high tier (Ark Angels etc.,) mission battlefields. You will also receive a message in your chat log but it is easily missed if you are not paying attention.' },
            } },
            { 'After acquiring the Key Item Consummate simulacrum, head to the Augural Conveyor at (B-6) in Rala Waterways and select it. This is near the zone from the Western Adoulin Waterfront at (F-5).', sub = {
                { 'Unlike other mission battles, there is no initial cutscene; choosing "The Charlatan" will immediately take you into the battle.' },
            } },
            { 'This battle is against Balamor and three Dullahan.', sub = {
                { 'Only the leader of the party loses their Key Item Consummate simulacrum upon entry. If you fail, only the leader has to go get another KI.' },
                { 'All party members who haven\'t previously completed the mission must possess the key item to enter.' },
                { 'Arciela aids you in this fight. She can hold her own quite well, but the battle will be lost if she falls.' },
                { 'Trust Magic can be summoned inside.' },
                { 'All of Balamor\'s regular attacks seem to be Area of Effect.' },
                { 'The Regicidal Dullahan will always target Arciela and can not be pulled off. Balamor and his two Balamor\'s Sycophants share hate. Causing hate to change for any of them will change the target of all three.' },
                { 'Only Balamor needs to be defeated to end the fight.', sub = {
                    { 'Balamor will surrender around 20% HP.' },
                } },
            } },
            { 'Upon successfully completing this mission, you do not need another KI to re-enter the battlefield.' },
        },
    },
    ['Seekers of Adoulin Mission 4-6-1'] = {
