    ['Rhapsodies of Vanadiel Mission 1-14'] = {
        title        = 'The Ties that Bind',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Ill tidings abound. Something is causing sailors to take leave of their senses, with a strange ringing reminding you of what occurred in Escha - Zi\'Tah. See what is happening in Sea Serpent Grotto.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Exit Norg on foot (not chocobo!) to the South (H-10).' },
            { 'You\'re now on Map 1 at (F-1) of Sea Serpent Grotto. Keep following the tunnel southward until you get to an apparent dead end near a torch at (H-6).' },
            { 'There\'s a hidden door here that has a blank label when you target it, and will open it when you interact with it. It\'s always unlocked - open it and proceed.', sub = {
                { '(This is usually the entrance you\'d need to find when getting into Norg traditionally.)' },
            } },
            { 'From here, take an immediate left to go north-east to J-5, and then a right (southward) to the one-way drop down at K-7. Continue!' },
            { 'Now hug the left wall as you go forward, ignoring the Ornamented Door\' (J-10) and proceeding down the tunnel to the left, until you reach a large room (K-11).' },
            { 'The sparkling ??? is right in front of you on the edge of the water (J-12).' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-15'] = {
        title        = 'Impurity',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The great Siren is the cause of the recent disturbances plaguing Norg, and she claims that Iroha was not the only one who came to the present time from the future. The masked man attacked Iroha, who faded into nothingness. Chase after him.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'If you are still in Sea Serpent Grotto from the previous quest, a Black Mage can cast Escape to take themselves and their party straight out to Yuhtunga Jungle.', sub = {
                { 'Players without the spell Escape can instead take a short walk to the exit.' },
            } },
            { 'If you are starting from Norg, the quickest means to reach the ??? is renting a Chocobo from Marilleune (H-9) in Norg, near the exit to Sea Serpent Grotto and ride to the ???.' },
            { 'If you are starting from any other location, an alternative quick trip is using the Level 119 Unity Wanted teleport to Yuhtunga Jungle.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-16'] = {
        title        = 'The Lost Avatar',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Siren and the masked man attempted to conjure forth another vortex in Yuhtunga Jungle in a bid to cause Escha to spread further. Fight the winged beast and stop her before it\'s too late.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Note that the following fight is considerably more difficult than the content leading up to it. If solo (with trusts), you may want to reach at least level 80 before attempting.' },
            { 'Examine the ??? again to start a battle.', sub = {
                { 'You will be fighting Siren.' },
                { 'Siren will despawn after approximately 15 minutes, ending the fight. You will need to kill her within 15 minutes to receive credit.' },
                { 'Can Charm, which will despawn your trusts if it hits you. Charm has no effect if it hits your trusts, so let one of them tank her. (Item Level 119 players should have no issues soloing her even if they do get charmed.)' },
                { 'Uses Massacre Elegy and Wind Threnody II.' },
                { 'Absorbs Wind Elemental damage, including that from Skillchains such as Detonation or Fragmentation.', sub = {
                    { 'Take care when using Trusts such as Cipher: Shantotto II, as their AI is designed to target the foe\'s greatest Elemental weakness, however in cases where foes will completely Absorb an Element, the AI will instead target that element to heal the foe.' },
                } },
            } },
            { 'After the fight, examine the ??? again for another cutscene.', sub = {
                { 'You will be rewarded with Key Item "Rhapsody in Azure".' },
                { 'If you "Call for Help" on Siren, you won\'t get the cutscene and will have to wait 1 minute to pop again.' },
                { 'In the event of death, one may rezone and still receive the cutscene as long as Siren is defeated.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-17'] = {
        title        = 'Volto Oscuro',
        starting_npc = 'N/A',
        subtitle     = 'The Fated',
        repeatable   = 'No',
        description  = 'Mission Orders: Siren has regained her senses and shared with you what the future holds. Volto Oscuro\'s power is immense, and it will stop at nothing to fulfill its goals. Report what you learned to Gilgamesh back in Norg.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
