    ['Rhapsodies of Vanadiel Mission 1-18'] = {
        title        = 'Ring My Bell',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Gilgamesh and his compatriot have decided to search for a man from the Far East by the name of Tenzen. Explore Escha - Zi\'Tah while they look for clues.',
