    ['Rhapsodies of Vanadiel Mission 1-4'] = {
        title        = 'Set Free',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The town\'s leader has informed you that Gilgamesh is looking for a particular adventurer and that he wants some goods. Mhaura: three Mandragora Dewdrops from pygmaioi. Selbina: three clumps of bee pollen from huge wasps.',
