    ['Rhapsodies of Vanadiel Mission 2-13'] = {
        title        = 'From the Ruins',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Alexander aided Phoenix in reviving Iroha. He knows much about the encroaching darkness, revealing that it\'s something far more sinister than the absence of light. Iroha has been brought back to Aht Urhgan to recover, where she and Aphmau await.',
