    ['Rhapsodies of Vanadiel Mission 2-35'] = {
        title        = 'Eddies of Despair',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Cid and his team have headed to Escha - Ru\'Aun, where a vortex is sucking up the crystals\' power. What lies beyond? Be on your guard as you proceed.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Upon entering Escha - Ru\'Aun, to the left (next to Dremi) there is a ??? that gives you Eschan Droplets item. Afterwards, click on the Eschan Portal to get to the next one.', sub = {
                { 'At each portal, you need to look around for ??? and obtain another Eschan Droplet. This will allow you to teleport to the next one. Repeat this process until you\'ve reached Portal #15. The location of each ??? is as follows:', sub = {
                    { 'Eschan Portal #2 — At the end of the only path. (Next to the door, don\'t use the one in front of the teleport).' },
                    { 'Eschan Portal #3 — Up the first staircase near the pillar to the right.' },
                    { 'Eschan Portal #4 — Across the bridge, between the two large pillars to the left.' },
                    { 'Eschan Portal #5 — At the end of the only path. (Next to the door, don\'t use the one in front of the teleport).' },
                    { 'Eschan Portal #6 — Southern (G-6), walk past and underneath the second staircase, and it is on the bridge with the closed door.' },
                    { 'Eschan Portal #7 — (F-5), Directly left of the second bridge.' },
                    { 'Eschan Portal #8 — At the end of the only path.' },
                    { 'Eschan Portal #9 — Head up both sets of stairs and turn left. Make another left at the bridge crossing the water. The ??? is in the middle of this area.', sub = {
                        { 'The Gargoyles will aggro at night time if you walk too close to their alcoves.' },
                    } },
                    { 'Eschan Portal #10 — Across both bridges, at the south-west side of the last platform.' },
                    { 'Eschan Portal #11 — At the end of the only path.' },
                    { 'Eschan Portal #12 — Sneak up then proceed up both sets of stairs, and turn right. Keep moving until you see a staircase on the left, and run past it. The ??? is past the staircase, at (J-7).' },
                    { 'Eschan Portal #13 — Across the first bridge, next to the first large pillar to the left.' },
                    { 'Eschan Portal #14 — At the end of the only path.', sub = {
                        { 'This process is not restricted to this mission and can be completed at any time after you\'ve gained entry access to the zone.' },
                        { 'If you have difficulty finding the ??? on a certain island, you can also go back to the start and pick up a new Eschan Droplets from the ???, then pay silt to use the Eschan Portal and use the new KI to continue unlocking portals.' },
                    } },
                } },
            } },
        },
    },
