        title        = 'Pretender to the Throne',
        starting_npc = 'N/A',
        subtitle     = 'Banisher of the Profane',
        repeatable   = 'No',
        description  = 'Mission Orders: The dark jester Balamor was working to drain the crystals of power in an attempt to fashion a new world in his image. Fight Balamor to draw his attention away from Selh\'teus while the Kuluu attempts to seal the vortex.',
        series       = 'Rhapsodies of Vana\'diel',
