        walkthrough  = {
            { 'Examine the Imperial Whitegate at Aht Urhgan Whitegate (L-8/9) when Aphmau is in town.', sub = {
                { 'Even if you have passed Passing Glory, there are some missions where Aphmau is not available. You must progress to a mission where she is "in town".', sub = {
