    ['Rhapsodies of Vanadiel Mission 3-1'] = {
        title        = 'Darkness Beckons',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The ambassador\'s plan is more sinister than imagined. He infused your soul with darkness in an attempt to hinder you. Yet you have been left with a tiny song of hope--what could it mean?',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Travel to the Crag of Holla, Dem, or Mea and examine the Dimensional Portal. You will receive the option to travel to Reisenjima.' },
            { 'Upon arrival, you will receive a brief cutscene.' },
            { 'Speak with Shiftrix, the goblin by the entrance, (you don\'t need to pay for info) to activate the Oseem augmentation system.', sub = {
                { 'Note: If you\'re doing missions just to utilize the Dark Matter Arcane Glyphics Campaign, you may stop here.' },
                { 'He sells a Key Item Map of Reisenjima (50 Silt.)' },
                { 'You may also want to grab a Key Item Mollifier (500 Silt) for use in the next Mission while here.' },
            } },
            { 'Make your way to the Etched Rock at (K-9) for a cutscene.', sub = {
                { 'Simply follow the path. The Etched Rock is at the far end and there is no shortcut.', sub = {
                    { 'One shortcut does exist, by using Cumulus Masque +1 (synthesized from two Cumulus Masque acquired from a Monthly Adventurer Campaign or other seasonal distributions). It works as of this mission, and places you right by #6. Get #1 prior to using the item for a return trip (there\'s no Eschan Droplet by #6), use the Cumulus Masque +1, and pick up the Ethereal Ingress #6 being careful not to get aggroed.' },
                } },
                { 'Make your way to (K-9) to check the Etched Rock and from this point forward you can pick up Ethereal Ingress. They do not blink when not yet acquired, unlike other teleport points, and most are on or close to the path, with #3 and #4 (the two in the north west) being the only substantial detour.', sub = {
                    { 'Note that more than the first six exist: #7 is associated with Domain Invasion / Quetzalcoatl, #9 is south down the river starting from #5 and has ???s useful for Geas Fete, and the other two can\'t be unlocked just yet.' },
                } },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 3-10'] = {
        title        = 'Solemnity',
        starting_npc = 'N/A',
        subtitle     = 'None',
