    ['Rhapsodies of Vanadiel Mission 3-14'] = {
        title        = 'Unshakable Nightmares',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Part of Selh\'teus\'s crystal must be cracked for you to become a god of light. What\'s more, you must also purge yourself of the ambassador\'s taint. Head to the Walk of Echoes to accomplish the latter task.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter Walk of Echoes for a cutscene.', sub = {
                { 'All three zoning methods listed below lead to the same section of the Walk of Echoes. The first one is the most easily accessible.' },
                { 'Note: If you zone in from blue ??? next to the Cavernous Maw & Survival Guide in Batallia Downs, you will need to exit after the cutscene and go to one of the other locations for the next mission as this is the wrong Walk of Echoes.' },
                { 'Note: As of 5/12/2026, zoning in from the blue ??? next to the Cavernous Maw & Survival Guide in Batallia Downs did not require going to another location. You may simply need to leave and return to ??? in Batallia Downs.' },
                { 'If you receive the message, "You are unable to make further progress in Rhapsodies of Vana\'diel due to an event occurring in the quest Champion of the Dawn," then you must zone into Walk of Echoes from Xarcabard (S) to activate and receive the cut scene for Champion of the Dawn and you must complete that quest and then A Forbidden Reunion first. You will not receive the Rhapsodies of Vana\'diel 3-14 cutscene upon re-entering Walk of Echoes after completing these quests, and you may simply proceed to the next Mission. Verification Needed', sub = {
                    { 'I am unclear why, but collecting the three Breath of dawns was all that was needed to skip ahead, and I did not have to finish Champion of the Dawn.' },
                    { 'One is able to skip having to complete A Forbidden Reunion by first entering though Xarcabard (S), receive the "You are unable to make further progress in Rhapsodies of Vana\'diel due to an event occurring in the quest Champion of the Dawn, leave using the teleport to Witchfire Glen, re-enter, receive the Champion of the Dawn cutscene, leave again to Witchfire Glen, and finally re-enter once more to the Walk of Echoes.' },
                } },
            } },
        },
    },
