    ['The Voracious Resurgence Mission 10-5'] = {
        title        = 'Duke Alloces\'s Decision',
        starting_npc = 'Heroes\' Gambit, Xarcabard (J-9)',
        subtitle     = 'Another Psyche',
        repeatable   = 'No',
        description  = 'Mission Orders: The Demons, too, seem to have a traitor in their midst. Odin has permitted you to wield a Prime Weapon and has bid you defeat Chaos and Garazu Horeizu. Prepare for the battle and head to the throne room in Castle Zvahl.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Equip your upgraded Prime Weapon and interact with the Heroes\' Gambit targetable location at (J-9) in Xarcabard for a cutscene.', sub = {
                { 'The unity warp 125 to Xarcabard will take you close to it.' },
                { 'Excludes Duban and Loughnashade.' },
            } },
            { 'Return to Castle Zvahl Keep and interact with the Valhallan Rift at (G-7) for a cutscene.', sub = {
                { 'It is located directly across from the Home Point.' },
                { 'The Rift is not visible if you have not advanced to this point in the story.' },
            } },
            { 'Interact with the Valhallan Rift again to enter the BCNM "Duke Alloces\'s Decision" with Chaos (RDM/DRK).', sub = {
                { 'Time limit of 15 minutes.' },
                { 'You will be assisted by the Destiny Destroyers. They do very little damage but are very strong defensively. Keep reraise active. If you wipe, the Destiny Destroyers can tank Chaos long enough for you to recover.', sub = {
                    { 'If any of the Destiny Destroyers die, the fight automatically ends. This is despite the previous cutscenes telling you their lives don\'t matter.' },
                } },
                { 'Chaos frequently casts a potent dispel which erases everything, including stances, and strips pieces of gear.' },
                { 'Chaos is difficult to enfeeble, though not immune. Manafont will remove all enfeebles, in any case.' },
                { 'Contrary to lore up to this point, any weapon can deal damage to Chaos, not just Prime Weapons.' },
                { 'After triggering the pre-fight cutscene, you can change to any job regardless of possession of a prime weapon.' },
            } },
            { 'After the cutscene, you will be moved to Xarcabard.' },
            { 'Return to and interact with the Heroes\' Gambit targetable location at (J-9) in Xarcabard for another cutscene and receive your gil reward and lose the Key Item Despairing psyche.' },
        },
    },
    ['The Voracious Resurgence Mission 10-6'] = {
