        starting_npc = 'Moogle, Home Nation Mog House',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Your local Mog House moogle says that the time has come for moogle and adventurer to work as one. You must head to the stone circle in La Theine Plateau. Get a move on!',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to your Moogle in the Mog House of your home nation for a cutscene.' },
            { 'Head to the Stone Circle in La Theine Plateau at (G-6) and interact with the ??? targetable location for a cutscene.', sub = {
                { 'UNM 99 warp to La Theine Plateau is the quickest route to the Stone Circle.' },
            } },
            { 'Interact with the Moogle Meeting targetable location in La Theine Plateau at (H-10) for a cutscene. To get here you have to exit from Map 3 in Ordelle\'s Caves.', sub = {
                { 'To reach this location you need to run through the caves and exit near Morbolger.' },
                { 'You can also use the Proto-Waypoint teleport to La Theine Plateau if you have it unlocked.', sub = {
