            { 'Check the Disturbed Earth once more after the battle for a cutscene.' },
            { 'Return to Heavens Tower and speak with Kupipi for a final cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 2-3'] = {
        title        = 'Zhuu Buxu\'s Gambit',
        starting_npc = 'Kupipi, Heavens Tower',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You have to retrieve the doll stolen from Heavens Tower with all due haste. A simple adventurer would attract little suspicion from the Yagudo. Your first task is to deliver a star-crested summons to Tosuka-Porika in the Optistery and receive further instructions.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to Kupipi in Heavens Tower for a cutscene to receive Key Item Star-crested summons. Zoning after the last mission is not required.' },
            { 'Speak to Tosuka-Porika in Windurst Waters HP #1 in the Optistery (G-8) (Map 1) for another cutscene.' },
            { 'Touch the Worn Chest in the storage room of the basement area of Giddeus on the second map at (F-6).', sub = {
                { 'Drop via \'E\' on the map.' },
                { 'To enter the treasure room, click on the door, not the Yagudo guard.' },
