                { 'There is a time limit of 15 minutes.' },
            } },
            { 'Touch the Worn Chest again after the battle for a cutscene and to get the Key Item Strange doll.', sub = {
                { 'If you zone before touching the Worn Chest, you can return and check it to continue without fighting again.' },
            } },
            { 'Return to Tosuka-Porika in Windurst Waters for a cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 2-4'] = {
        title        = 'Star Onion Fortune',
        starting_npc = 'Tosuka-Porika, Windurst Waters (G-8) Map 1',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The doll you retrieved from Giddeus is no more than a child\'s plaything. Return it to its owner near a warehouse near the waterfront in Windurst.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to Tosuka-Porika again for a cutscene. Zoning is not required after the previous mission.' },
            { 'Speak to Kohlo-Lakolo in Port Windurst (G-5) (HP #1) behind Warehouse 1 for a cutscene.', sub = {
                { '(Optional): Talking to Kohlo-Lakolo again will give you a hint.' },
                { '(Optional): Speaking to Shanruru gives an additional cutscene.' },
            } },
            { 'Open up your Temporary Key Item menu and examine the Key Item Piece of evidence in your Temporary Key Items to see a cipher.' },
            { 'Speak to Kohlo-Lakolo for another cutscene. He will ask if you deciphered the evidence, say yup.', sub = {
