            { 'Travel to the The Boyahda Tree and visit any of the three Muggy Air sites at (D-5), (H-6), and (H-9) Map 1, bottom floor.', sub = {
                { 'You may take Unity Warp (Level 125) to The Boyahda Tree. Once there, turn around to zone to Map 1.' },
                { 'May need to travel to all 3 spots as one activates the cutscene.' },
            } },
            { 'Touching the active site will immediately spawn the Templar Crawler NM. The active site will have a white glowing animation. Not all sites will be active, so keep looking at the different positions.', sub = {
                { 'Deals enhanced damage via Poison Breath.' },
                { 'Appears to gain an additional Protect buff after using Cocoon.' },
            } },
            { 'Each party member will receive a Key Item Sublime lucky egg upon defeating the NM.' },
            { 'Return to Kohlo-Lakolo for a cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 2-5'] = {
        title        = 'The Doll Whisperer',
        starting_npc = 'Kohlo-Lakolo, Port Windurst (G-5)',
        subtitle     = 'Ghdwk Vshdnhu (Death Speaker)',
        repeatable   = 'No',
