        next         = '',
        walkthrough  = {
            { 'Speak to Kohlo-Lakolo for a cutscene. Zoning is not required after the previous mission.', sub = {
                { '(Optional): Speak to Kohlo-Lakolo again as well as the rest of the S.O.B.s for more dialogue.' },
