    ['The Voracious Resurgence Mission 3-1'] = {
        title        = 'Dancing Prince',
        starting_npc = 'Halver, Chateau d\'Oraguille',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: A ball is set to take place at House Virgaut. You have been charged with helping ensure that Trion is fully prepared, including making sure there is no Orcish interference like last time. Rahal, leader of the Royal Knights, can tell you more.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to Halver in Chateau d\'Oraguille for a cutscene.' },
            { 'Home Point #2 in North San d\'Oria is the fastest.' },
            { 'Speak to Rahal in the Royal Knight\'s quarters to the west for a cutscene.' },
            { 'Head to Davoi and speak with Quemaricond at either (G-7) or (H-7) for a cutscene. He walks back and forth on the path.', sub = {
                { 'Proto-Waypoint would be the fastest way to get there.' },
                { 'Survival Guide (Norvallen) is also a fast option if you don\'t have the Proto-Waypoint' },
            } },
            { 'Head to Monastic Cavern from the (H-11) entrance in Davoi.' },
            { 'Touch the Ritual Site at the border of (H-10)/(H-9) inside the Monastic Cavern to begin a confrontation with an Orcish Bewitcher (BLM/DRK).', sub = {
                { 'Has about 30k HP.' },
                { 'Uses Manafont as early as 90% HP.' },
                { 'You will automatically receive the Key Item Orcish battle plan upon defeating the NM.' },
            } },
            { 'Return to Quemaricond for a cutscene to receive Key Item Quemaricond\'s report.', sub = {
                { 'Escape then re-enter Davoi is the fastest path.' },
            } },
            { 'Speak with Rahal for the final cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 3-2'] = {
        title        = 'Claidie\'s Concern',
        starting_npc = 'Halver, Chateau d\'Oraguille',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Halver has another request on the eve of the ball. Trion once fell ill with a mysterious malady, and such a tragedy cannot be allowed to repeat. A special remedy is available, and you have been asked to procure it from Chalvatot.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak with Halver for a cutscene to begin the mission.' },
            { 'Head towards Queen Leaute\'s Memorial Garden (F-7) to the west of the Central Garden for a cutscene.' },
            { 'Head to Attohwa Chasm with some Sickles and harvest at the glowing flower Harvesting Point (H-8) to receive Key Item Solidago flower.', sub = {
                { 'Trailblazing Sickles or the +1 variant do not work at this harvesting point.' },
                { 'This is a specific location, you cannot just find any harvesting point in the zone.' },
                { 'Unity Warp 125 is the fastest way to get there.', sub = {
                    { 'Turn around and follow the tunnel until it reaches (H-8).' },
