            { 'Speak with Rahal in the Royal Knight\'s quarters for another cutscene.' },
            { 'Head to Beaucedine Glacier.', sub = {
                { 'The quickest way is via Survival Guide (Fauregandi) warp.' },
            } },
            { 'Touch the Ferric Stench (H-8) next to the East side of the tower to begin a confrontation with:', sub = {
                { 'Orcish Atlatl (WAR)' },
                { 'Orcish Axeman (BST)' },
