        },
    },
    ['The Voracious Resurgence Mission 3-5'] = {
        title        = 'Of Knights and Orcs',
        starting_npc = 'Halver, Chateau d\'Oraguille',
        subtitle     = 'The Awakener',
        repeatable   = 'No',
        description  = 'Mission Orders: Slackjawed Mukdrom\'s forces have captured a contingent of the Carmine Swallows. The victims have doubtless been taken to Fei\'Yin and require backup posthaste. Excenmille has chosen to examine the western half, so it falls to you to take the east side.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into Fei\'Yin from Beaucedine Glacier for a cutscene.' },
            { 'Obtain a Doll Gizmo. You can buy them from the Auction House under Others ➞ Misc. 1. It\'s also a 100% drop from the Manipulator in Temple of Uggalepih map 2 at (I-10)/(J-10) patrolling in the big room.', sub = {
                { 'Proto-Waypoint is the closest warp.' },
                { 'The Unity Concord (Level 125) Warp is also a quick way to reach this NM. You will have to defeat the door guardian to get through the door to reach your target.' },
                { 'The Manipulator respawns every 15 minutes.' },
            } },
            { 'Trade the Doll Gizmo to the NPC Talos (H-7) map 2 in Fei\'Yin for a cutscene.', sub = {
                { 'This "NPC" is a pile of Doll Parts in front of a door when heading south down the hall (H-6) from the large room where Capricious Cassie spawns.' },
                { 'The Talos for this mission does not show up on Wide Scan.' },
                { 'The Talos will not be visible after completing the cutscene.' },
                { 'If you are returning after grabbing the Doll Gizmo it is faster to use the Home Point #2 for the Cloister of Frost instead of navigating map 1 to exit A.' },
            } },
            { 'After the cutscene, return to the Point of Interest next to Mirror Pond at (J-6) in Beaucedine Glacier for a cutscene.', sub = {
                { 'Subjob BLM and casting Escape puts you a short walk away from this position.' },
            } },
            { 'Touch the Point of Interest again to begin a confrontation with Slackjawed Mukdrom (WAR)', sub = {
                { 'Has approximately 50k HP.' },
                { 'Uses Mighty Strikes and has en-Drain on attacks.', sub = {
                    { 'Can use Mighty Strikes multiple times.' },
                } },
            } },
            { 'Touch the Point of Interest once more for a cutscene after defeating the Orc.' },
            { 'Return to Chateau d\'Oraguille and click Door:Prince Royal\'s RM located at (H-7) for a final cutscene and your rewards.' },
        },
    },
    ['The Voracious Resurgence Mission 4-1'] = {
