        },
    },
    ['The Voracious Resurgence Mission 4-4'] = {
        title        = 'Raubahn the Blue',
        starting_npc = 'Imperial Whitegate, Aht Urghan Whitegate (L-9)',
        subtitle     = 'Bond Renewer',
        repeatable   = 'No',
        description  = 'Mission Orders: In the underground prison, Raubahn and his retinue shared quite a bevy of information with you, but you remain as vexed as ever. Now a soulflayer has taken residence nearby, with another strange seal appearing in Caedarva Mire. Convinced these incidents are connected, you head for Caedarva Mire to best the soulflayer.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to the palace at Aht Urghan Whitegate (L-9) HP-#2 and click the gate Imperial Whitegate for a cutscene.' },
            { 'Travel to Caedarva Mire Map 4 (Hediva Isle).', sub = {
                { 'Unity Warp (Lv. 135, Shedu) to Caedarva Mire is the fastest way', sub = {
                    { 'The Shedu warp requires either Captain Mercenary Rank or a Key Item Remnants Permit from Salvage.' },
                } },
                { 'Alternatively, take the Runic Portal to the Nyzul Isle Staging Point in Alzadaal Undersea Ruins.', sub = {
                    { 'From the Nyzul Isle Staging Point, walk west-northwest towards (H-8) and use the teleporter, marked D on map 5.' },
                    { 'After you zone, take the teleporter on your left marked as J on map 4.' },
                    { 'Walk north and zone to Caedarva Mire Map 4 (Hediva Island).' },
                } },
                { 'If you don\'t have the Nyzul Isle or Unity warp, see the Nyzul Isle Staging Point page for instructions to walk there.' },
            } },
            { 'When you\'re ready, go north east through a slightly hidden path and touch the Savage Scars at (I-6) beside the Engraved Tablet for a cutscene.', sub = {
                { 'The upcoming fight is soloable at iLvl 119 with medium difficulty depending on your job and available trusts.', sub = {
                    { 'Summon your trust team in advance so your WHM trust gets Protectra V and Shellra V up on foes along the way.' },
                } },
            } },
            { 'Touch the Savage Scars again for a battle against 1x Arisen Soulflayer and 3x Descended Winebibber (Clot Slimes). 15 minute time limit.', sub = {
                { 'The Descended Winebibbers must also be defeated in order to win.', sub = {
                    { 'Beware of Fluid Toss, a powerful Physical Damage TP move.' },
                } },
                { 'Uran-Mafran will assist in battle. They are a BLM and will melee with a club if the enemy is within melee range, but will otherwise cast spells from his position.', sub = {
                    { 'Uran-Mafran stays at range unless he takes hate.' },
                    { 'If Uran-Mafran is KOed then the fight is lost. They may be cured like any other NPC.' },
                } },
            } },
        },
    },
    ['The Voracious Resurgence Mission 5-1'] = {
        title        = 'Ghatsad\'s Quandary',
        starting_npc = 'Ghatsad, Aht Urhgan Whitegate (I-7)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Ghatsad has been charged with finding additional information about Falak. The legends begin hundreds of years ago, and it appears that Goblins are the original source of the tales. Meet wtih Megomak in Mount Zhayolm and see what you can learn.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak with Ghatsad in the Automaton Workshop (I-7) in Aht Urhgan Whitegate for a cutscene.', sub = {
                { 'You will receive a Key ItemGift for Megomak.' },
            } },
            { 'Head to Mount Zhayolm (I-9) via the Halvung Staging Point and examine the Acid-eaten Door for a cutscene (near Cerberus spawn. This is on the second level, follow the ramp up from the central part of I-8).', sub = {
                { 'This door lies beyond the Gates of Halvung near the Halvung Staging Point, not the other one at (H-8).', sub = {
                    { 'You will need a Key ItemCast metal plate to open the gate. See the page if you lack the KI.' },
                    { 'It is in the far northwest corner of (I-9), on the upper level of the Troll structures.', sub = {
                        { 'Once the door is opened, keep going south up the ramparts, and through an arch. On the right will be the house of Megomak.' },
                    } },
                } },
            } },
            { 'Proceed to Hazhalm Testing Grounds in Caedarva Mire (Einherjar\'s location) and examine the Entry Gate for another cutscene with Uran-Mafran and the Destiny Destroyers.', sub = {
                { 'The quickest transportation is to Caedarva Mire Home Point #1.' },
                { 'Completing the quest "A Stygian Pact" will unlock an extra dialogue option with regards to Odin.' },
            } },
            { 'Head outside to Caedarva Mire and examine the Vexing Sniffles (E-10) (Graveyard, outside of Hazhalm zone) for a cutscene.' },
            { 'Examine the Vexing Sniffles once more to begin a confrontation against Gloom Phantom (WAR/DRK), Magh Bihu (MNK), and Dazbog (PLD).', sub = {
                { 'Approximately 60k HP each.' },
                { 'Mnejing will assist and must be kept alive.', sub = {
                    { 'Note: You must bring the enemies close to Mnejing to engage immediately, otherwise he will despawn and the fight will end prematurely.' },
                    { 'You will receive a Key ItemPure white ampoule after the fight.' },
                } },
                { 'Similar to TVR Mission 1-4 "The Destiny Destroyers," the Gloom Phantom and Dazbog can attempt skillchains if they focus the same target.', sub = {
                    { 'However, Magh Bihu will no longer attempt Magic Bursts afterward but can use Hundred Fists repeatedly.' },
                } },
            } },
            { 'Examine the Vexing Sniffles a final time for a cutscene.' },
            { 'Return to the Acid-eaten Door in Mount Zhayolm at (I-9) for a cutscene.' },
            { 'Return to Ghatsad (I-7) in Aht Urhgan Whitegate for the final cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 5-2'] = {
        title        = 'The Revelation',
        starting_npc = 'Abda-Lurabda, Aht Urhgan Whitegate (I-7)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Ghatsad\'s apprentices are concerned with his demeanor of late, as he is completely engrossed with learning more about Olduum. Head to Aydeewa Subterrane to assist with the investigation. The exact location: right past the area connecting the northern Wajaom Woodlands with Aydeewa Subterrane.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak with Abda-Lurabda in the Automaton Workshop (I-7) in Aht Urhgan Whitegate for a cutscene to begin the mission.', sub = {
                { 'Optional: Speak with Dkhaaya (G-9) for dialogue in regards of Olduum. You need to have finished the quest Olduum since he\'ll repeat dialogue related to it instead.' },
            } },
            { 'Zone into Aydeewa Subterrane from the (I-6) entrance from Wajaom Woodlands for a cutscene.', sub = {
                { 'Exit Al Zahbi or Aht Urhgan Whitegate (H-10) directly for the fastest route to the objective.' },
                { 'You can take the survival guide to Aydeewa Subterrane and Escape. This will put you at the (I-6) entrance.' },
            } },
            { 'Head to and examine the Survey Point at (K-7) of map 2 of Aydeewa Subterrane for a cutscene.' },
            { 'Head south then hug the wall west to examine the Survey Point at the intersection of (I-9)/(J-9) for another cutscene.', sub = {
                { 'You should unlock the Survival Guide before proceeding further if you do not have it as it is a very convenient time to do so.' },
            } },
            { 'Proceed to (E-9), and then west down the ramp (marked as D). This room is full of aggressive Chigoes.', sub = {
                { 'You will be on Map 5 of Aydeewa Subterrane. Examine Survey Point at (F-8) for another cutscene.' },
            } },
            { 'After the cutscene, head south west towards the exit marked as F to transition to map 3.' },
            { 'After the map changes, drop down, follow the path, and make your way south to (G-10).' },
        },
    },
    ['The Voracious Resurgence Mission 5-3'] = {
        title        = 'Tateeya\'s Worries',
        starting_npc = 'Tateeya, Aht Urhgan Whitegate (I-7)',
        subtitle     = 'Treasure of Olduum',
        repeatable   = 'No',
        description  = 'Mission Orders: Ghatsad\'s search continues apace, and he is on the verge of a breakthrough into the mysteries of Olduum. He has made a startling discovery and is a bit on edge. Ask his apprentices for more information.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak with Tateeya in the Automaton Workshop (I-7) in Aht Urhgan Whitegate for a cutscene to begin the Mission.' },
            { 'Speak with Ghatsad for another cutscene.', sub = {
                { 'Being in the middle of No Strings Attached may prevent you from continuing this Quest. Verification Needed' },
            } },
            { 'Head to the Jade Sepulcher.', sub = {
                { 'Fastest way is by Home Point #1 to Bhaflau Thickets Map 2.' },
                { 'Another way is to go to Mamool Ja Staging Point to Bhaflau Thickets Map 2 and head North.' },
            } },
            { 'Examine the Ornamental Door for a cutscene.' },
            { 'Examine the Ornamental Door again to enter the BCNM fight "Tateeya\'s Worries" against:', sub = {
                { 'Drakeweaver Hageel Ja (PLD) - 60k HP' },
                { 'Riftweaver Pomaal Ja (BLU) - 60k HP' },
                { 'Fistweaver Mufaal Ja (Sahagin MNK) - 60k HP' },
                { 'Glyphweaver Sikool Ja (BLM). - 100k HP', sub = {
                    { 'Casts Stun, Thunder V, Thunder VI, Ionohelix II, Thundaja.', sub = {
                        { 'These will not do much harm to a player in MDT/Magic Evasion gear, but will deal solid damage against trusts.' },
                    } },
                } },
                { 'Trusts may be used in the fight.', sub = {
                    { 'This is a true BCNM so there is room to buff and summon trusts before engaging.' },
                } },
                { 'Glyphweaver Sikool Ja\'s weapon must be broken to win the fight, otherwise he\'ll remain at 1%.', sub = {
                    { 'To do this you need to weaponskill as the NM is doing a melee attack or very shortly after.' },
                    { 'If the Sikool hits 1% you will do 0 damage, consider bringing some forms of Regain or Meditate either from main or subjob as appropriate.' },
                } },
                { 'All foes utilize their Two-Hour ability 1-hour abilities.' },
                { 'All foes can be silenced', sub = {
                    { 'Glyphweaver Sikool Ja will be resistant, likely require Immunobreaks.' },
                } },
                { 'All mobs can be slept', sub = {
                    { 'Drakeweaver Hageel Ja possesses the resist sleep trait.' },
                    { 'Glyphweaver Sikool Ja is resistant to sleep and will require Immunobreaks.' },
                    { 'Fistweaver Mufaal Ja was slept twice by M30 RDM' },
                } },
            } },
            { 'Head back to Aht Urhgan Whitegate and examine Imperial Whitegate for the final cutscene and the Thunder Hammer.', sub = {
                { 'Note: Do not discard the Thunder Hammer. You will need it for a later Mission.' },
            } },
        },
    },
    ['The Voracious Resurgence Mission 5-4'] = {
        title        = 'The Seagull Phratrie',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Aznahf and Mutihb of the Seagull Phratrie are squabbling over Aznahf allegedly sinking a vessel that came into Mutihb\'s possession. Though a pteraketos may be at fault, none are sure if it\'s actually real. Survey the cliffs in the northwest of Arrapago Reef.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Before heading out to Arrapago Reef, you will need to obtain a Hamsi.', sub = {
                { 'This can be purchased from Wahnid (H-11) in Aht Urhgan Whitegate, bought from the Auction House or easily fished from Aht Urghan Whitegate with zero fishing skill.' },
                { 'Wahnid is open from 1:00-18:00, closed on Lightsday.', sub = {
                    { 'The item is not automatically restocked. It is only available if previously sold to the guild.' },
                } },
            } },
            { 'You will also need a Lamian Fang Key. Alternatively, Thief can use Skeleton Key and or Thief Tools.', sub = {
                { 'You can obtain the key by examining the ??? once per game day at (I-7) in Caedarva Mire Map 1 (in the vicinity of the small pond containing Jnun).' },
                { 'The Survival Guide teleport to Arrapago Reef (via Arrapago Is.) and running south will exit to Caedarva Mire (I-6).', sub = {
                    { 'Escape from Arrapago Reef will put you in Caedarva Mire (I-6) as well.' },
                    { 'Alternatively, you can use the Azouph Isle Staging Point (Leujaoam Sanctum), exit Nashmau at (H-6) or use the Voidwatch warp to Caedarva Mire.' },
                } },
            } },
            { 'Head to Arrapago Reef and interact with the ??? at the North East corner of (H-10) on a ship for a cutscene to begin the mission.', sub = {
                { 'This is easiest via the Arrapago Reef Survival Guide. Alternatively, from where you obtained the Lamian Fang Key, head to (I-6) to zone into Arrapago Reef.', sub = {
                    { 'From there, move towards (J-10) with a Lamian Fang Key to open the Iron Gate. Trade the key, and quickly cross through.' },
                    { 'Hug the left wall on this cavern map. You will exit through a door back to the first map, and you\'ll you reach (H-10).' },
                } },
                { 'The ??? target is the same for the Corsair job quest. The correct cutscene mentions Pteraketos and Sealord Skin.' },
            } },
            { 'After the cutscene, head to Map 3 of Arrapago Reef (F-7), and trade a Hamsi to the Apkallu Guide for another cutscene.', sub = {
                { 'The fastest way to get to this location is to warp out and use a Survival Guide to teleport to Caedarva Mire, then immediately enter the cave into Arrapago Reef.' },
                { 'Note: If you don\'t have the Caedarva Mire Survival Guide, you will need another Lamian Fang Key to reach it.' },
            } },
        },
    },
    ['The Voracious Resurgence Mission 5-5'] = {
        title        = 'The Sea Sage',
        starting_npc = 'N/A',
        subtitle     = 'Beloved by the Sea God',
        repeatable   = 'No',
        description  = 'Mission Orders: Bijoux, the apkallu elder, has provided you with a good deal of information. You must look for a breathing pearl to dive into the water and find the pteraketos. Bijoux notes that the Olduum civilization, once located in Wajaom Woodlands, may contain clues. Head for the designated location.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Note: You need the Thunder Hammer you received from Mission 5-3 to complete this.' },
            { 'Head to Map 3 of Arrapago Reef (F-7) and speak with Apkallu Guide for a cutscene to begin the mission.', sub = {
                { 'Teleport to Caedarva Mire\'s Survival Guide and then zone to the East.' },
            } },
            { 'Proceed to (G-8) in Wajaom Woodlands to examine the Leypoint for a cutscene.', sub = {
                { 'You may use an Olduum Ring to teleport directly to the spot.' },
                { 'Alternatively, use the Wajaom Woodlands Survival Guide or Unity Warp (125).' },
            } },
            { 'Travel to (G-9), where the Hydra usually spawns.', sub = {
                { 'To get here, first go to (E-10) in Wajaom Woodlands, entrance 8 on the map to enter the Aydeewa Subterrane (Map 3).', sub = {
                    { 'Voidwatch Warp to Mamook will put you close to this entrance, but it\'s much faster to just run there.' },
                } },
                { 'Follow the path, along the left wall the whole way, do not drop down, and exit at (J-8).', sub = {
                    { 'This is exit 7 on the map below.' },
                } },
            } },
            { 'Once outside keep going and after the first ledge drop you will be in an open area.', sub = {
                { 'If you see raptors or spiders then you went the wrong way in the Subterrane.' },
            } },
            { 'Equip the Thunder Hammer in your main weapon slot and approach the Marolith for a cutscene.', sub = {
                { 'The Marolith is not targetable. If Hydra is up, you can walk around it without aggro if you do not want to kill it.' },
                { 'You will receive Key Item Aeropearl afterwards.' },
            } },
            { 'Return to the Apkallu Guide in Arrapago Reef (F-7) via the Caedarva Mire Survival Guide for a cutscene.' },
            { 'Speak with Ghatsad in Aht Urhgan Whitegate (I-7) for another cutscene.', sub = {
                { 'Speaking to Dkhaaya before Ghatsad will give you a mini-cutscene where he tells you he cannot fix the aeropearl and send you to Ghatsad.' },
            } },
            { 'Head to Alzadaal Undersea Ruins and defeat Qiqirn to spawn Panaiveriyamman (WAR), an Acrolith NM.', sub = {
                { 'It will appear immediately after killing a Qiqirn, so summon Trusts beforehand.' },
                { 'You may need to defeat many Qiqirns before Panaiveriyamman spawns.', sub = {
                    { 'If you\'re having trouble popping Panaiveriyamman equip your Thunder Hammer and get physical kills with it.' },
                } },
                { 'Uses Two-Hour ability Mighty Strikes, but doesn\'t hit very hard or accurately in general.' },
                { 'Resistant to magic, especially Element: Dark dark-based spells, but is very susceptible to Element: Water water damage.' },
                { 'Has approximately 150k HP.' },
                { 'You will receive the Key Item Man-made solution after the fight.', sub = {
                    { 'The key item will drop to everyone in a party/alliance, even if you are not on the same map.' },
                } },
            } },
            { 'Return to Ghatsad for a cutscene.', sub = {
                { 'Note: FastCS may cause you to get stuck on a black screen during this CS. Unload FastCS or use the Print Screen button to unlock from a soft freeze.' },
                { 'You will receive Key Item Repaired aeropearl afterwards.' },
            } },
            { 'Head back to the ??? (H-10) Map 1 Arrapago Reef.', sub = {
                { 'Survival guide warp to Arrapago Reef.' },
                { 'You will, yet one more time, require a Lamian Fang Key.' },
            } },
            { 'Return to the Apkallu Guide via the Caedarva Mire Survival Guide for the final cutscene and your reward.', sub = {
                { 'Note: FastCS may or may not get you stuck during this cutscene as well. If you do get locked up, try Print Screen, or `//config FrameRateDivisor 2`, or `//lua unloadall` followed by `//exec autoload/autoload`.' },
            } },
        },
    },
    ['The Voracious Resurgence Mission 6-1'] = {
        title        = 'Sky, Moon, Incantrix',
        starting_npc = 'Reikuu, Reisenjima (K-8)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Gessho and the Far Eastern Yagudo Reikuu believe that the World Eater Egg will give birth to an avatar that must be put down with extreme prejudice. They aim to reunite with their Middle Lands brethren and seek information on the black sword. You are to go procure it from the Goblin Incantrix.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Note: Bring 3 Hoptoad and an Eastern Ginger to save time.' },
            { 'Speak with Reikuu (K-8) near Ethereal Ingress #6 in Reisenjima for a cutscene to begin the mission.' },
            { 'Head to Ethereal Ingress #10 and speak with Incantrix for another cutscene.', sub = {
                { 'You must choose the option "No, of course not" in order to continue with the quest.' },
            } },
            { 'Head to (H-6) between Ethereal Ingress #3 & #5 in Reisenjima and examine Suspicious Overgrowth for a cutscene.', sub = {
                { 'Gessho will ask for 3 Hoptoad and an Eastern Ginger.', sub = {
                    { 'Hoptoad are obtained by fishing in Reisenjima, off the bridge near Ethereal Ingress #2 with a Fly Lure or Lufaise Fly and any rod.', sub = {
                        { 'The bite rate may vary depending on your fishing rod and whether you have Key Item Frog FishingVerification Needed.' },
                        { 'With Lu Shang\'s F. Rod or Ebisu Fishing Rod and sufficient skill, the bite rate is nearly 100%, even without the KI.' },
                    } },
                    { 'Eastern Ginger can be harvested in Reisenjima (touching Grimslight requires Key Item Reaper), harvested in Bhaflau Thickets or found in treasure caskets in Reisenjima.', sub = {
                        { 'Key Item Reaper is sold by Shiftrix (F-12) for 50 Silt.' },
                    } },
                } },
            } },
            { 'Trade the items to the Suspicious Overgrowth for a cutscene.' },
            { 'Return to Reikuu (K-8) near Ethereal Ingress #6 for the final cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 6-2'] = {
        title        = 'Nii\'s Last Stand',
        starting_npc = 'N/A',
        subtitle     = 'Destiny Master',
        repeatable   = 'No',
        description  = 'Mission Orders: The black sword is a bit too inconvenient of a truth for some of the Yagudo. Reikuu has asked to find out more about a 5,000-year-old incident that the Yagudo have forgotten about. Seek out Incantrix once more.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak with Reikuu for a cutscene to begin the mission. No zoning needed from the previous mission.' },
            { 'Head to Ethereal Ingress #10 and speak with Incantrix for another cutscene.' },
            { 'Head to (F-5) Ethereal Ingress #4 and examine the Babbling Brook in the river for a cutscene.' },
            { 'Return to Incantrix for another cutscene.' },
            { 'Head to (K-7) Ethereal Ingress #6 and examine Aspirants\' Grounds (K-7) for a cutscene.', sub = {
                { 'You will receive Key ItemAspirant\'s canteen afterwards.' },
            } },
            { 'Click the Aspirants Grounds again to enter "Nii\'s Last Stand," a 10 minute solo BCNM fight. Trusts cannot be summoned.', sub = {
                { 'Will receive message "Only your party leader may inspect the entrance". You must disband from party to complete this solo fight.' },
                { 'Fair Warning: Fight is very easy and the mobs hit for 1 hp.', sub = {
                    { 'The goal is for you and Nii Aquu to each defeat half of the mobs. Use AoEs without KOing to help Nii Aquu defeat mobs faster.' },
                    { 'Nii Aquu will say five responses during the battle that indicate if the player has maintained the correct ratio of KOs with Nii Aquu.' },
                } },
            } },
        },
    },
    ['The Voracious Resurgence Mission 6-3'] = {
        title        = 'Dance of the Tengu',
        starting_npc = 'N/A',
        subtitle     = 'Tireless Tracker',
        repeatable   = 'No',
        description  = 'Mission Orders: Reikuu is angered that you assisted Nii Aquu in his training, evidently because sticking your nose in where it doesn\'t belong has threatened the burgeoning alliance between the Middle Lands Tengu and those of the traditional Tengu religion. Now Zhuu Buxu is here. Track him down near the waterfall in northwestern Reisenjima.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak with Reikuu (K-8) near Ethereal Ingress #6 in Reisenjima for a cutscene to begin the mission.' },
            { 'Head to (F-5) Ethereal Ingress #4 and examine the Babbling Brook for a cutscene.' },
            { 'Click the Babbling Brook again to enter Dance of the Tengu BCNM (Zhuu Buxu) 15 Minute fight time limit.', sub = {
                { 'Has approximately 125k HP.' },
                { 'This is an Omen fight, so you will be subject to the normal Omen queue.' },
                { 'Trusts may be used in the fight.' },
                { 'Zhuu Buxu has access to Mijin Gakure.', sub = {
                    { 'Nii Aquu will assist and must be kept alive.' },
                } },
            } },
            { 'After the fight, you\'ll automatically enter a cutscene.' },
            { 'Click the Babbling Brook again to enter Dance of the Tengu BCNM (Reikuu) 15 Minute fight.', sub = {
                { 'Has approximately 90k HP.' },
                { 'This is an Omen fight, so you will be subject to the normal Omen queue.' },
                { 'Trusts may be used in the fight.' },
                { 'Gessho will assist and must be kept alive.' },
                { 'Both Reikuu and Gessho can summon clones, and you can stagger Reikuu with a if you can damage the real one.', sub = {
                    { 'Doing so will remove all of Reikuu\'s clones.' },
                    { 'AoE abilities must target the real Reikuu for this to occur.' },
                    { 'The clones make it difficult to target and face Reikuu.' },
                } },
                { 'Reikuu also has access to Mijin Gakure.', sub = {
                    { 'It is capable of doing over 2k damage even in full -dt set. Even if all party members are KOed, Gessho can win the fight still.' },
                } },
            } },
            { 'After the fight, you\'ll automatically enter a cutscene.' },
            { 'Return to Reikuu for the final cutscene and your rewards.' },
        },
    },
    ['The Voracious Resurgence Mission 7-1'] = {
        title        = 'Raebrimm\'s Rebirth',
        starting_npc = 'Gumbah, Bastok Mines (J-7)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Gumbah and Cornelia are searching for Raebrimm. A simple look into the history of the Galka together with other information leads you to think he\'s headed for Zepwell Island. Ask Dancing Wolf in Rabao for help.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak with Gumbah in Bastok Mines (J-7) HP #1 to begin the mission. He is inside the back room of the house on the upper walkway.' },
            { 'Speak with Dancing Wolf in Rabao (G-6)/(G-7) near HP #2 for a cutscene.', sub = {
                { 'Not to be confused with the nearby vendor Brave Wolf.' },
            } },
            { '(Optional): Go to Rabao (G-9) and speak to Agado-Pugado and Rahi Fohlatti for some dialogue.' },
            { 'Head to the (G-5) Entrance to Quicksand Caves in Western Altepa Desert.', sub = {
                { 'The Survival Guide to Kuftal Tunnel and exit into Western Altepa Desert is the fastest way.' },
                { 'If you don\'t have the Survival Guide, Unity Warp 125 to Kuftal Tunnel, then Black Mage spell Escape takes you to the entrance of Kuftal Tunnel.' },
            } },
            { 'Proceed to the weight trigger door at (H-8) then to (G-11) in Quicksand Caves to examine the ??? at the statue for a cutscene.', sub = {
                { 'Requires 1 Galka to open or a combination of other race. Hume Mithra and Elvan give 2/3 so you would need 2 players and Tarutaru give 1/3.' },
                { 'You can open it without other players if you posses a Key Item Loadstone.' },
            } },
            { 'Before leaving this area, it\'s recommended you continue to (C-8) and exit to Western Altepa Desert to press the sapphire column for opening the Altepa Gate in the subsequent mission.' },
            { 'Head to the (D-12) entrance to Quicksand Caves in Western Altepa Desert.', sub = {
                { 'If you have it, the Proto-Waypoint warp to Quicksand Caves takes you to the correct map on the step below.', sub = {
                    { 'Be careful though, as you are placed right on the an edge of a drop off.' },
                    { 'One step back or to the left and you will fall, and you will have to warp again. Walk straight upon zoning in.' },
                } },
                { 'From (K-8) on Map 5, head to (H-8) on Map 6 passing through the entrance marked as D and touch the ??? at (H-8) to begin a confrontation with:', sub = {
                    { '2 Spelunking Sabotenders (MNK)' },
                    { '2 Sand Lizards' },
                    { '2 Sand Tarantulas (WAR)' },
                    { 'Recommended to use trusts, Cactuars can use 1,000 Needles.' },
                    { 'The monsters are resistant to Sleep and Petrify.' },
                } },
            } },
            { 'Touch the ??? again afterwards for the final cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 7-2'] = {
        title        = 'Uran-Mafran of the Maelstrom',
        starting_npc = 'Dancing Wolf, Rabao (G-6)',
        subtitle     = 'Galkan Hazard',
        repeatable   = 'No',
        description  = 'Mission Orders: Galka on their journey of rebirth are being targeted due to their knowledge of the Abyss. Gumbah and Oggbi have asked for your help in protecting the gates. Your first task is to head for Altepa Gate in the Western Altepa Desert and see what awaits you.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak with Dancing Wolf in Rabao (G-6) HP #2 for a cutscene to begin the mission.' },
            { 'Zone into Quicksand Caves from the Altepa Gate for a cutscene. The entrance is in Western Altepa Desert at (I-6/7).', sub = {
                { 'See the Altepa Gate page for instructions on how to open the Altepa Gate.' },
            } },
            { 'The fight with Uran-Mafran (BLM/RDM) will immediately begin once you touch the Journey\'s End at (K-10).', sub = {
                { 'Has approximately 185k HP.' },
                { 'Trusts may be used in this fight.' },
                { 'Uran-Mafran can use Two-Hour ability Manafont multiple times and has a very high degree of Fast Cast', sub = {
                    { 'Two-Hour ability Manafont will remove all applied debuffs.' },
                } },
                { 'Possesses a substantial resistance to silence (though not immunity). Other enfeebles landed normally.', sub = {
                    { 'Seen using BLM -jas, Cure VI, Enspells, Protect V, Shell V, Meteor, Impact, Comet, and AoE enfeebles.' },
                    { 'Two-Hour ability Manafont will make short work of any trusts. Recommended to kill quickly or attempt to land silence.' },
                } },
                { 'Will attempt to self-skillchain with Club Weapon Skills and magic burst accordingly.', sub = {
                    { 'Black Halo and tier VI magic bursts hit hard. Damage taken gear is highly recommended.' },
                    { 'Possesses large amounts of regain and can complete skillchains even if unable to land regular hits.' },
                    { 'Trust tanks will not survive magic bursts. They can deal over 10k damage.' },
                } },
                { 'You will be joined by Oggbi (MNK), who must be kept alive.', sub = {
                    { 'Can use Two-Hour ability Hundred Fists multiple times and various Hand-to-Hand weaponskills.' },
                } },
            } },
            { 'Touch the Journey\'s End afterwards for a cutscene.', sub = {
                { '', sub = {
                    { 'Credit for beating Uran-Mafran is retained even if your character is defeated.' },
                } },
            } },
            { 'Speak with Gumbah in Bastok Mines (J-7) HP #1 for the final cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 7-3'] = {
        title        = 'Koru-Moru\'s Hypothesis',
        starting_npc = 'Shantotto, Windurst Walls (K-7)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Koru-Moru and Yoran-Oran take the stage, and they think they have an idea. Garazu-Horeizu\'s theory of the Maelstrom has been made manifest. But to get to the bottom of things, you need a better magicked doll. Procure a spectral goldenrod, spectral crimson, and luminicloth.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak with Shantotto in Windurst Walls (K-7) HP #3 to begin the mission.', sub = {
                { 'Koru-Moru will ask for the Spectral Crimson, Spect. Goldenrod and Luminicloth.', sub = {
                    { 'Spectral Crimson is a drop from Fomor BRD, PLD, RDM in Misareaux Coast & Lufaise Meadows.', sub = {
                        { 'Misareaux Coast Near Sacrarium (E-7), the campfire at (J-11) and Lufaise Meadows at Blueblade Fell (J-6) during Night hours.', sub = {
                            { 'Unity Warp 125 to Lufaise Meadows brings you somewhat near Blueblade Fell.' },
                            { 'Fomors share spawns with each other and may not respawn as the desired job.' },
                        } },
                    } },
                    { 'Spect. Goldenrod is a drop from Haunts in Kuftal Tunnel or Srei Ap in Uleguerand Range near (K-7).', sub = {
                        { 'Many Haunt spawn at (H-7) in Kuftal Tunnel. Take the Survival Guide via Volbow to Kuftal Tunnel and you\'ll be a short distance from (H-7).' },
                        { 'Srei Ap spawn only at night around the holes that drop you underground.' },
                    } },
                    { 'Recommended places to farm Luminicloth include:', sub = {
                        { 'Fei\'Yin: Revenant, Utukku, and Wekufe.' },
                        { 'Abyssea - Konschtat: Qaitu.' },
                    } },
                } },
            } },
            { '(Optional): Speak with Yoran-Oran (E-5) and Koru-Moru (E-7) at their houses for basic dialogue.' },
            { 'Trade the items to Shantotto for a cutscene and your rewards.', sub = {
                { 'You will receive Key Item Memorian, the Magicked Doll after the cutscene.' },
            } },
        },
    },
    ['The Voracious Resurgence Mission 7-4'] = {
        title        = 'Altennia Burns Bright',
        starting_npc = 'Halver, Chateau d\'Oraguille',
        subtitle     = 'Bearer of Secrets',
        repeatable   = 'No',
        description  = 'Mission Orders: The magicked doll reacted at Excenmille\'s presence when you went to see Prince Trion. The memories come flooding back, and Trion, fearing what may come next, has dispatched Altennia\'s regiment. Head to the Royal Knight\'s Quarters and give Rahal his orders.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to Halver in Chateau d\'Oraguille for a cutscene to begin the mission.', sub = {
                { 'The Key Item Memorian, the Magicked Doll will be activated in this cutscene.' },
                { 'You will also receive Key Item Trion\'s directive afterwards.' },
            } },
            { 'Speak with Rahal in the Royal Knight\'s quarters for another cutscene.', sub = {
                { 'The Key Item Memorian, the Magicked Doll will be activated in this cutscene.' },
            } },
        },
    },
    ['The Voracious Resurgence Mission 8-1'] = {
        title        = 'Maat on the Rampage',
        starting_npc = 'Maat, Ru\'Lude Gardens',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Maat appears to be a tad more injury-prone of late. A woman who came to him for training may be involved. You have been asked to return a basket to her. Head to Lower Jeuno and speak with Muckvix to learn more about her.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak with Maat in Ru\'Lude Gardens (H-5) to begin the mission.', sub = {
                { 'You will receive Key ItemCloth-lined basket after the cutscene.' },
            } },
            { 'Speak with Muckvix in Lower Jeuno (H-10) at the back of the goblin shop for a cutscene.', sub = {
                { 'You will receive Key ItemMap to the woman\'s home after the cutscene.' },
            } },
            { 'Speak with Miladi-Nildi near the Mog House entrance (J-5) in Lower Jeuno for a cutscene.', sub = {
                { 'Note: For Mumor\'s effects to appear in the upcoming cutscenes, under the main menu Config → Effects → set Non-party PC → Non-party PC to OFF or All effects during battle to ON.' },
            } },
            { 'Touch the Goblin Festival Site (K-7) Batallia Downs at night (18:00-06:00) for a cutscene.', sub = {
                { 'Unity Warp (125) to Batallia Downs takes you to (K-8), which is nearby. Alternatively, use the Survival Guide or exit from Upper Jeuno (HP #1).' },
                { 'The site is on the coast on the way to the cave.' },
            } },
            { 'Click the Goblin Festival Site again to begin a confrontation with "The Shadow That Terrorizes Battalia Downs".', sub = {
                { 'You have 15 minutes to complete this fight.' },
                { 'Has approximately 200k HP.' },
                { 'Does not require nighttime hours to start the confrontation.' },
                { 'You will be assisted by Mumor, and the battle will end prematurely if she is defeated.' },
                { '"The Shadow" can activate multiple pre-ToAU Two-Hour ability SP Abilities throughout the fight.', sub = {
                    { 'Can use Benediction REPEATEDLY any time either of you use a WS.', sub = {
                        { 'This can be triggered as high as 89% HP.' },
                    } },
                    { 'Can also use Manafont, Hundred Fists, Chainspell, Meikyo Shisui, Blood Weapon, etc.', sub = {
                        { 'Gains access to AoE enfeebles during Chainspell, such as Dispelga.' },
                        { '"The Shadow" is not resistant to enfeebles. Silence landed first try and lasted the whole fight.' },
                    } },
                } },
                { '"The Shadow" can also potentially self-skillchain via Hand-to-Hand weapon skills throughout the fight.', sub = {
                    { 'This can potentially one-shot Trust tanks and players without defense sets.' },
                } },
            } },
            { 'Click the Goblin Festival Site once more for a cutscene.', sub = {
                { 'You will receive Key ItemMaat\'s pillow after the cutscene.' },
            } },
            { 'Return to Maat for the final cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 8-2'] = {
        title        = 'Not Just a Pretty Face',
        starting_npc = 'Muckvix, Lower Jeuno',
        subtitle     = 'Long Live Mumor',
        repeatable   = 'No',
        description  = 'Mission Orders: Maat appears to have been under the influence of the World Eater Egg. According to Muckvix, it appears to have been carried by monsters prowling around Delkfutt\'s Tower. The Gloom Phantom has headed to Qufim Island to learn more. Assist the troupe by heading to Delkfutt\'s Tower on Qufim Island.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak with Muckvix in Lower Jeuno (H-10) for a cutscene to begin the mission.' },
            { 'Head to Qufim Island near the entrance to Lower Delkfutt\'s Tower and examine the targetable location called Before Delkfutt\'s Tower at (G-6) for a cutscene.', sub = {
                { 'Fastest route is the Survival Guide to Qufim Island.' },
            } },
            { 'Interact with the Before Delkfutt\'s Tower spot again to begin a confrontation with Echion (Gigas WAR).', sub = {
                { 'Has approximately 200k HP.' },
                { 'Trusts may be used in the fight.' },
                { 'You will be assisted by the Destiny Destroyers, and the battle will end prematurely if any of them are defeated. You will be unable to heal any of them.' },
                { 'Echion gains an unremovable Ice Spikes effect following his first Ice Roar that increases in potency after an SP ability is used.', sub = {
                    { 'Can reach up to 500 damage per spike without defense gear.' },
                    { 'Damage can be reduced significantly with Barspells, Carols, and/or Magic Evasion.' },
                    { 'NM can use Mighty Strikes and Hundred Fists multiple times.' },
                } },
                { 'Gains access to Colossal Slam (AoE Knockback + Zombie) < 50% HP.', sub = {
                    { 'Can also use Daunting Hurl (Terror) throughout the fight.' },
                } },
            } },
            { 'Interact with the Before Delkfutt\'s Tower location after the fight for a cutscene.' },
            { 'Return to Muckvix for the final cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 8-3'] = {
        title        = 'Delkfutt the Great',
        starting_npc = 'Shami, Port Jeuno',
        subtitle     = 'Parter of the Veil',
        repeatable   = 'No',
        description  = 'Mission Orders: You heard about how Maat partook of the World Eater Egg from Shami and Shemo. According to Delkfutt, someone from San d\'Oria cracked the egg twenty years ago. Perhaps you must travel to the past to learn more...',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { '(Optional): Speak with Elijah in Upper Jeuno (F-6) for some dialogue.' },
            { 'Speak with Shami in Port Jeuno (H-8) for a cutscene to begin the mission.' },
            { 'Head to Southern San d\'Oria (S) and speak with Valaineral R Davilles (H-8) for a cutscene.', sub = {
                { 'Since Valaineral is a Campaign NPC, he might be out of town until his return from battle. (If Valaineral doesn\'t appear after returning you may need to zone out and return)', sub = {
                    { 'Speaking to Voucheramme , Hinrich , or Dallus-Mallus can help track the Royal Guards\' current location.' },
                } },
            } },
            { 'Head to Batallia Downs (S) at the eastern edge of (G-7) and touch the shiny Secret Entrance to enter The Eldieme Necropolis (S).', sub = {
                { 'The Survival Guide or Campaign Warp to Batallia Downs (S) will place you close to the Secret Entrance.' },
            } },
            { 'Head to (F-9) and interact with the Egg Discovery Site location to start a cutscene.', sub = {
                { 'Noillurie (M-7/8) must be available and not conducting a Campaign Operation. The site will inform you if she is injured or unavailable.', sub = {
                    { 'Speaking to Voucheramme , Hinrich , or Dallus-Mallus can help track the Knights of the Red Rose\'s current location.' },
                } },
            } },
            { 'Check the Egg Discovery Site again to start a battle with Sa\'Jho Shieldbreaker (PLD), Enkelados (BST) with 3 Saplings, and Sharpshot Luttdrutt (RNG).', sub = {
                { 'The time limit is 15 minutes.' },
                { 'All enemies except for the Saplings are immune to sleep and break. Sa\'Jho Shieldbreaker is immune to Silence, but really didn\'t heal the others.' },
                { 'You will need to pull the RNG off the ledge, as it always spawns up there.' },
                { 'You can stand up on the ledge above the glowing spot and have them come to you at RNG spawn point and save pulling him down.' },
                { 'Enkelados can use Charm if his saplings are defeated first.', sub = {
                    { 'Otherwise, he tends to use Familiar instead.' },
                } },
            } },
            { 'After winning the battle, check the Egg Discovery Site for another cutscene.' },
            { 'Return to Valaineral R Davilles (H-8) for a cutscene and your rewards.' },
        },
    },
    ['The Voracious Resurgence Mission 9-1'] = {
        title        = 'Oshasha Violation',
        starting_npc = 'Andreine, Celennia Memorial Library',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Oshasha of the Celennia Memorial Library has asked you to search for a tome known as the Key Item Liber Daemonium. The Velkk in Marjami Ravine appear to have taken possession of a book bearing resemblance to this tome. Head to Marjami Ravine.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak with Andreine in the Celennia Memorial Library (F-10) for a cutscene to begin the mission.', sub = {
                { 'She is the receptionist on the left as you enter.' },
            } },
            { 'Head to Marjami Ravine and examine the Bibliomaniac\'s Lair at (I-10) for a confrontation.', sub = {
                { 'To get here, use Waypoint #2 then head southeast.' },
                { 'When you come to a small watch tower, enter the tunnel there NE at (J-9/10).' },
                { 'Then continue to (I-10). When you reach the tent/reive, enter the cave to the left and climb up the vine.' },
                { 'The Bibliomaniac\'s Lair is on a flat patch of rock at (I-10) in front of the Seat of Gramk-Droog.' },
            } },
            { 'Note that the fight starts instantly after selecting the Lair and clears any aggro from other Velkk in the area.', sub = {
                { 'Gramk-Droog (WAR)' },
                { 'Velkk Defiler (DRK)' },
                { 'Velkk Inquisitor (RDM).', sub = {
                    { 'All three are sleepable and silenceable.' },
                } },
            } },
            { 'Examine the Bibliomaniac\'s Lair again after the fight for a cutscene.', sub = {
                { 'You will receive Key ItemLiber Daemonium after the cutscene.' },
            } },
            { 'Return to Andreine for the final cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 9-2'] = {
        title        = 'Phantasmic Heroes',
        starting_npc = 'Marjoirelle, Western Adoulin',
        subtitle     = 'Demonic Dreamer',
        repeatable   = 'No',
        description  = 'Mission Orders: Translation of the Key Item Liber Daemonium has led you to learn of a demonic presence, Dvergr, in Leafallia. Oshasha and Valli are on the case, but Valli turned away for an instant and Oshasha was gone. Head to Leafallia and look for her.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak with Marjoirelle (H-12) near Home Point #2 in Western Adoulin for a cutscene.' },
            { 'Head to Leafallia and examine the Odyssean Passage for a cutscene.' },
            { 'Touch the nearby Test of Talents for another cutscene.' },
            { 'Touch the Test of Talents again to enter a solo BCNM against the Shadow Lord.', sub = {
                { 'You must disband from party or have no other members in the same zone.' },
                { 'You may use buffs that carry over on zone like haste for this fight.' },
                { 'Trusts may not be used in this fight.' },
                { 'The Shadow Lord can switch between dual-wield and two-handed sword modes, similar to the Shadowreign version.', sub = {
                    { 'Gains access to Blighting Blitz while dual-wielding and can potentially one-shot all NPCs except Valli and players without defense gear.' },
                    { 'Dispel\'s Buffs throughout the fight.', sub = {
                        { 'Appears to be a conal AoE that can absorbed with 4 shadows.' },
                    } },
                    { 'Can use Two-Hour ability Mighty Strikes and/or Two-Hour ability Blood Weapon multiple times throughout the fight.' },
                } },
                { 'You will be assisted by Volker (WAR), Zeid (DRK), Valli (PLD), Oshasha (WHM), and Romaa Mihgo (THF).', sub = {
                    { 'Oshasha will occasionally use an AoE healing ability if the NPC group takes damage on multiple members.' },
                    { 'The other NPCs can also use single-target potions and their job\'s special abilities.' },
                    { 'Note: Losing all five NPCs will result in an automatic loss.' },
                } },
            } },
            { 'You will enter a cutscene after the fight.' },
            { 'Speak with Andreine in the Celennia Memorial Library for the final cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 9-3'] = {
        title        = 'Skokkr Undrborn\'s Temptation',
        starting_npc = 'Glowing Hearth, Eastern Adoulin (H-6)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Your invitation to the Silver Knife has arrived. The dvergr Skokkr Undrborn is supposedly there, potentially in the guise of a humanoid. Ask around for information.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak with Glowing Hearth in Eastern Adoulin (H-6) near Homepoint #1 for a cutscene.', sub = {
                { 'During the cutscene, you will be transported inside of the Silver Knife zone.' },
            } },
            { 'Speak with Oscarnot inside for a cutscene.', sub = {
                { 'If the bidding closes for the Auria Collection you will need to talk to Zemerine before talking to Gama-Shama.' },
            } },
            { 'Speak with Gama-Shama in the Silver Knife. He will mention how it was hard to procure his Esthete\'s Masque and how he obtained his attire from Runje Desaali.' },
            { 'Speak to Runje Desaali in Eastern Adoulin (J-10) until she shows you the Esthete\'s Masque and hint at wanting some specific equipment that is in high demand.', sub = {
                { 'Quickest from the Castle Adoulin gates waypoint.' },
            } },
            { 'Make sure you get the dialogue about the mask before you trade or you will need a new item.' },
            { 'Trade her an Item Level 106 or 115 Wildskeeper Reive Weapon, Armor, or Rare/Ex Accessory. She will give you 4000 or 6000 Bayld depending on the item and the cutscene will continue.', sub = {
                { 'It may be worth looking to see if you have a Kupon AW-WK or Key Item Mog Kupon AW-WK already, before participating in a Wildskeeper Reive.' },
                { 'Records of Eminence NPCs can also trade all 6 Wildkeeper Reive Key Items for a weapon.' },
            } },
            { 'After trading in any applicable item, she then unlocks new shop items. Ask her What does Geosuke recommend?.' },
            { 'Buy a Esthete\'s Masque, Esthete\'s Coat and Esthete\'s Hose from Runje Desaali.', sub = {
                { 'Each piece is 30,000 Bayld. You need all 3 for 90,000 Bayld to continue.' },
            } },
            { 'Return to the Silver Knife and speak to Zemerine with all items equipped or the set as a Lockstyle for a cutscene.', sub = {
                { 'Other lockstyles cannot be used.' },
                { 'If this cutscene does not play, attempt the next step by removing the equipment and talking to Oscarnot. Discussion Page' },
            } },
            { 'Unequip the items or disable your lockstyle, then speak with Oscarnot for another cutscene.' },
            { 'Speak with Glowing Hearth outside of the Silver Knife in Eastern Adoulin for a cutscene and reward.' },
        },
    },
    ['The Voracious Resurgence Mission 9-4'] = {
        title        = 'The Prime Weapons',
        starting_npc = 'Andreine, Celennia Memorial Library',
        subtitle     = 'Searcher of the Voracious',
        repeatable   = 'No',
        description  = 'Mission Orders: Skokkr Undrborn has taken possession of the Liber Daemonium. The tome holds the secrets for manifesting the Prime Weapons once more. Stygian ash, occasionally carried by pixies, is needed to serve as a suitable vessel. The item is quite rare, so head to Celennia Memorial Library and do some research to aid you.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {
            { '(Optional) Speak to Andreine in the Celennia Memorial Library for a hint regarding Oshasha\'s whereabouts.' },
            { 'Travel to Leafallia and interact with the Odyssean Passage for a cutscene.' },
            { 'Trade a Stygian Ash to the Odyssean Passage for another cutscene. You will receive Key Item Bronze-hued tag.', sub = {
                { 'Stygian Ash drops from the Pixie family, which are easily found in Grauberg (S) around Witchfire Glen.', sub = {
                    { 'The most accessible way to get to Witchfire Glen is using your Lightsworm on the blue sparkles near Batallia Downs Survival Guide. Once in Walk of Echoes, turn around and interact with the conflux just behind you to teleport to Witchfire Glen.' },
                    { 'Alternatively, either Campaign Warp to Grauberg or use the Survival Guide.' },
                    { 'Recall-Pashh will also bring you near the conflux in Pashhow Marshlands (S) which you may also use teleport to Witchfire Glen, but it requires you complete late game voidwatch quests.' },
                } },
            } },
            { 'Travel to Outer Ra\'Kaznar (K-3), Upper Floor (map 1).', sub = {
                { 'To get here, it is easy to follow the marked path on the Outer Ra\'Kaznar page\'s maps.' },
                { 'DO NOT interact with the roots at (J-3), continue over to (K-3) when you reach that spot. Otherwise you will be forced to take a teleport to the entrance and run through the entire area again.' },
            } },
            { 'Interact with the Shrouded Workroom at (K-3) for a cutscene.', sub = {
                { 'Be careful, as there are Umbrils around the area.' },
            } },
            { 'Return to Leafallia and interact with the Odyssean Passage for the final cutscene and your reward, completing the mission.' },
            { 'Continue with the creation of your Prime Weapon by following the section below. You will need it to progress in the coming quests.' },
        },
    },
}

quest_info['assaults'] = {
    ['Building Bridges'] = {
        title        = 'Building Bridges',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Thanks to the enemy destroying a bridge along the path of their attack, the unit assaulting Periqia is at an impasse. Find and activate the backup bridge mechanism rumoured to be hidden in the area.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Corporal',
        time_limit   = '15 minutes',
        mission_orders = 'Activate the bridge',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {
            { 'You begin on a small map with the greater part of the area blocked off. You will have to head north-east to reach the main map.' },
            { 'The four switches are located in the west, south, north and east rooms, located at (F-8), (H-10), (H-6) and (J-8) respectively.' },
            { 'The switches can be activated in any order and remain activated permanently.' },
            { 'The Rune of Release appears in the center room at (H-8).' },
        },
    },
    ['Counting Sheep'] = {
        title        = 'Counting Sheep',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'The Imperial Army on the eastern front is being hit by a peculiar cold wave, and warm uniforms are in short supply. Buy as many sheep as you can from the markets in Leujaoam and save the troops.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Corporal',
        time_limit   = '15 minutes',
        mission_orders = 'Buy black sheep',
        recommended_lv = 'Lvl. 60',
        walkthrough  = {
            { 'There are 4 Qiqirn NPCs at the entrance' },
        },
    },
    ['Searat Salvation'] = {
        title        = 'Searat Salvation',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Qiqirn divers assigned the duty of demolishing wrecks on the Ilrusi Atoll have run into a problem with the local wildlife. Lead them back to safety before they decide to abandon their work.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Corporal',
        time_limit   = '15 minutes',
        mission_orders = 'Save the Qiqirn Divers',
        recommended_lv = 'Lvl. 60',
        walkthrough  = {
            { 'Talking to a Qiqirn Diver will induce it to follow you.' },
