    ['Shanarha Grass Conservation'] = {
        title        = 'Shanarha Grass Conservation',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Rabbits are sending shanarha grass, unique to the Leujaoam Sanctum, to the verge of extinction. Drive away the rabbits and protect the vegetation.',
