    ['Shooting Down the Baron'] = {
        title        = 'Shooting Down the Baron',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'An imp known as the Black Baron has hit Periqia like a meteor strike, single-handedly defeating 79 imperial soldiers. The Empire cannot suffer any more losses. It is time for the baron to meet his end.',
