        previous     = '',
        next         = '',
        assault_rank = 'Lance Corporal',
        time_limit   = '15 minutes',
        mission_orders = 'Eliminate the Black Baron',
        recommended_lv = 'Lvl. 60',
        walkthrough  = {
            { 'You will enter the Assault on the east side of the map in the room at (I-8). This is also where the Rune of Release spawns.' },
            { 'The Black Baron will not appear on Widescan.' },
            { 'A short time after he is engaged the Baron will warp away to a different part of the map. For this reason having a job that can summon a pet to follow him to his next location is extremely useful, as it will save a lot of time. /SMN is also fine for this. It should be noted that at ilvl 119 the Black Baron dies in one weaponskill. The pet strategy is no longer necessary.' },
            { 'While he has significantly more HP, he is otherwise pretty much the same as a regular VT Imp.' },
